};

/**
 * Updates flat details from a CSV string.
 */
export const updateFlatsFromCSV = (state: AppState, csvText: string) => {
  const newState = { ...state };
  const lines = csvText.split('\n');
  let updatedCount = 0;

  lines.forEach((line, index) => {
    if (index === 0) return; // Skip headers
    const [flatNumber, ownerName, mobile] = line.split(',').map(s => s?.trim());
    if (!flatNumber) return;

    const flatIndex = newState.flats.findIndex(f => f.flatNumber === flatNumber);
    if (flatIndex !== -1) {
      newState.flats[flatIndex] = {
        ...newState.flats[flatIndex],
        ownerName: ownerName || newState.flats[flatIndex].ownerName,
        mobile: mobile || newState.flats[flatIndex].mobile,
      };
      updatedCount++;
    }
  });

  saveData(newState);
  return { newState, updatedCount };
};

/**
 * Imports maintenance transactions from a CSV string.
 */
export const importTransactionsFromCSV = (state: AppState, csvText: string) => {
  const newState = { ...state };
  const lines = csvText.split('\n');
  let count = 0;
  const errors: string[] = [];

  lines.forEach((line, index) => {
    if (index === 0) return;
    const parts = line.split(',').map(s => s?.trim());
    const [date, flatNumber, amountStr, receiptNoStr, ownerName] = parts;
    if (!flatNumber || !amountStr) return;

    const amount = parseFloat(amountStr);
    const flat = newState.flats.find(f => f.flatNumber === flatNumber);

    if (flat) {
      const receiptNo = receiptNoStr ? parseInt(receiptNoStr) : newState.lastReceiptNo + 1;
      const transaction: Transaction = {
        receiptNo,
        date: date || new Date().toISOString().split('T')[0],
        timestamp: Date.now(),
        flatId: flat.id,
        flatNumber,
        ownerName: ownerName || flat.ownerName,
        amount,
        mobile: flat.mobile || ''
      };

      newState.transactions = [transaction, ...newState.transactions];
      if (receiptNo > newState.lastReceiptNo) newState.lastReceiptNo = receiptNo;

      const flatIndex = newState.flats.findIndex(f => f.id === flat.id);
      newState.flats[flatIndex].status = PaymentStatus.PAID;
      count++;
    } else {
      errors.push(`Flat ${flatNumber} not found at line ${index + 1}`);
    }
  });

  saveData(newState);
  return { newState, count, errors };
};

/**
 * Exports all database tables to an Excel file.
 */
export const exportDataToExcel = (state: AppState) => {
  const wb = XLSX.utils.book_new();

  const flatsSheet = XLSX.utils.json_to_sheet(state.flats);
  XLSX.utils.book_append_sheet(wb, flatsSheet, "Flats");

  const txSheet = XLSX.utils.json_to_sheet(state.transactions);
  XLSX.utils.book_append_sheet(wb, txSheet, "Transactions");

  const financeSheet = XLSX.utils.json_to_sheet(state.financialRecords);
  XLSX.utils.book_append_sheet(wb, financeSheet, "FinancialRecords");

  XLSX.writeFile(wb, `CH_Backup_${new Date().toISOString().split('T')[0]}.xlsx`);
};

/**
 * Imports data from an uploaded Excel file.
 */
export const importDataFromExcel = async (file: File): Promise<AppState> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });

        const flats = XLSX.utils.sheet_to_json(workbook.Sheets["Flats"]) as Flat[];
        const transactions = XLSX.utils.sheet_to_json(workbook.Sheets["Transactions"]) as Transaction[];
        const financialRecords = XLSX.utils.sheet_to_json(workbook.Sheets["FinancialRecords"]) as FinancialRecord[];

        if (!flats || flats.length === 0) throw new Error("Invalid format: No flats found");

        const lastReceiptNo = transactions.reduce((max, t) => Math.max(max, t.receiptNo), 100);

        const newState: AppState = {
          flats,
          transactions,
          financialRecords: financialRecords || [],
          lastReceiptNo
        };
        saveData(newState);
        resolve(newState);
      } catch (err) {
        reject(err);
      }
    };
    reader.readAsArrayBuffer(file);
  });
};

/**
 * Creates a system restore point in local storage.
 */
export const createSystemSnapshot = (state: AppState) => {
  localStorage.setItem(SNAPSHOT_KEY, JSON.stringify({
    state,
    timestamp: Date.now()
  }));
};

/**
 * Restores the application state from the saved restore point.
 */
export const restoreSystemSnapshot = (): AppState | null => {
  const saved = localStorage.getItem(SNAPSHOT_KEY);
  if (!saved) return null;
  const { state } = JSON.parse(saved);
  saveData(state);
  return state;
};

/**
 * Gets the timestamp of the saved restore point.
 */
export const getSnapshotTimestamp = (): number | null => {
  const saved = localStorage.getItem(SNAPSHOT_KEY);
  if (!saved) return null;
  const { timestamp } = JSON.parse(saved);
  return timestamp;
};

/**
 * Saves Firebase configuration for cloud sync.
 */
export const saveCloudConfig = (config: FirebaseConfig) => {
  localStorage.setItem('firebase_config', JSON.stringify(config));
  initFirebase(config);
};

/**
 * Retrieves the saved Firebase configuration.
 */
export const getCloudConfig = (): FirebaseConfig | null => {
  const saved = localStorage.getItem('firebase_config');
  return saved ? JSON.parse(saved) : null;
};

/**
 * Syncs the local state with the cloud database.
 */
export const syncFromCloud = async (): Promise<AppState | null> => {
  const data = await loadFromCloud();
  if (data) {
    saveData(data);
    return data;
  }
  return null;
};

/**
 * Adds a new financial record (income or expense).
 */
export const addFinancialRecord = (state: AppState, record: Omit<FinancialRecord, 'id' | 'timestamp'>) => {
  const newState = { ...state };
  const newRecord: FinancialRecord = {
    ...record,
    id: `fin-${Date.now()}`,
    timestamp: Date.now()
  };
  newState.financialRecords = [newRecord, ...newState.financialRecords];
  saveData(newState);
  return newState;
};

/**
 * Updates an existing financial record.
 */
export const updateFinancialRecord = (state: AppState, id: string, updates: Partial<FinancialRecord>) => {
  const newState = { ...state };
  const index = newState.financialRecords.findIndex(r => r.id === id);
  if (index !== -1) {
    newState.financialRecords[index] = { ...newState.financialRecords[index], ...updates };
    saveData(newState);
  }
  return newState;
};

/**
 * Deletes a financial record.
 */
export const deleteFinancialRecord = (state: AppState, id: string) => {
  const newState = { ...state };
  newState.financialRecords = newState.financialRecords.filter(r => r.id !== id);
  saveData(newState);
  return newState;
};

/**
 * Clears all financial records.
 */
export const clearFinancialRecords = (state: AppState) => {
  const newState = { ...state, financialRecords: [] };
  saveData(newState);
  return newState;
};

/**
 * Imports financial records from a CSV string.
 */
export const importFinancialRecordsFromCSV = (state: AppState, csvText: string) => {
  const newState = { ...state };
  const lines = csvText.split('\n');
  let count = 0;
  const errors: string[] = [];

  lines.forEach((line, index) => {
    if (index === 0) return;
    const parts = line.split(',').map(s => s?.trim());
    const [date, type, amountStr, category, description] = parts;
    if (!type || !amountStr) return;

    const amount = parseFloat(amountStr);
    if (!isNaN(amount)) {
      const record: FinancialRecord = {
        id: `fin-${Date.now()}-${count}`,
        type: type.toUpperCase() as 'INCOME' | 'EXPENSE',
        amount,
        date: date || new Date().toISOString().split('T')[0],
        category: category || 'General',
        description: description || '',
        timestamp: Date.now()
      };
      newState.financialRecords = [record, ...newState.financialRecords];
      count++;
    } else {
      errors.push(`Invalid amount at line ${index + 1}`);
    }
  });

  saveData(newState);
  return { newState, count, errors };
};

/**
 * Updates the AI generated insight in the application state.
 */
export const updateInsight = (state: AppState, text: string) => {
  const newState = {
    ...state,
    aiInsight: {
      text,
      timestamp: Date.now()
    }
  };
  saveData(newState);
  return newState;
};

import { GoogleGenAI, Type } from "@google/genai";
import { AppState, PaymentStatus } from "../types";
import { MAINTENANCE_AMOUNT } from "../constants";

const getSystemInstruction = () => {
  return `You are a financial assistant for a Building Society Manager. 
  Your job is to analyze collection data and provide a brief, professional, and encouraging summary.
  Focus on the percentage collected, amount remaining, and speed of collection.
  Keep it under 3 sentences.`;
};

// Use gemini-3-flash-preview for text tasks
export const generateFinancialInsight = async (state: AppState): Promise<string> => {
  if (!process.env.API_KEY) {
    return "AI insights unavailable: API Key missing.";
  }

  const paidCount = state.flats.filter(f => f.status === PaymentStatus.PAID).length;
  const unpaidCount = state.flats.filter(f => f.status === PaymentStatus.UNPAID).length;
  const totalCollected = state.transactions.reduce((acc, curr) => acc + curr.amount, 0);

  // Calculate today's collection
  const today = new Date().toISOString().split('T')[0];
  const todayCollection = state.transactions
    .filter(t => t.date.startsWith(today))
    .reduce((acc, curr) => acc + curr.amount, 0);

  const prompt = `
    Context:
    Building: Continental Heights B Wing.
    Total Flats: ${state.flats.length}
    Maintenance Amount: ${MAINTENANCE_AMOUNT}

    Current Status:
    Paid: ${paidCount}
    Unpaid: ${unpaidCount}
    Total Collected All Time: ${totalCollected}
    Collected Today: ${todayCollection}

    Provide a "Daily Insight" for the manager dashboard.
  `;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        systemInstruction: getSystemInstruction(),
      }
    });

    // Access response.text directly (not a method)
    return response.text || "Unable to generate insight.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Unable to analyze data at this moment.";
  }
};

// Use gemini-3-flash-preview for parsing text to JSON
export const parseFinancialText = async (text: string): Promise<any> => {
  if (!process.env.API_KEY) return null;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Extract transaction details from: "${text}".
      Return JSON with keys: 
      - type (INCOME or EXPENSE)
      - amount (number)
      - date (YYYY-MM-DD, assume today if not specified)
      - category (short string e.g. 'Repairs', 'Utilities', 'Maintenance')
      - description (brief summary)
      `,
      config: {
        responseMimeType: "application/json",
         responseSchema: {
          type: Type.OBJECT,
          properties: {
            type: { type: Type.STRING },
            amount: { type: Type.NUMBER },
            date: { type: Type.STRING },
            category: { type: Type.STRING },
            description: { type: Type.STRING },
          }
        }
      }
    });

    // Access response.text directly (not a method)
    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("Quick Fill Error:", error);
    return null;
  }
};

import { AppState, Flat, PaymentStatus, Transaction, FinancialRecord } from '../types';
