        >
          <ChevronLeft size={24} />
        </button>

        <h2 className="text-lg font-bold text-slate-800">
          {formatMonthDisplay(selectedMonth)}
        </h2>

        <button 
          onClick={handleNextMonth}
          className="p-2 rounded-full hover:bg-slate-100 text-slate-600 transition-colors active:bg-slate-200"
        >
          <ChevronRight size={24} />
        </button>
      </div>

      {/* ACCOUNT BALANCES GRID */}
      <div className="grid grid-cols-2 gap-4">

          {/* CASH IN HAND */}
          <div className="bg-emerald-600 p-5 rounded-2xl shadow-lg shadow-emerald-200 text-white relative overflow-hidden">
             <div className="relative z-10">
                <p className="text-emerald-100 text-[10px] font-bold uppercase tracking-wider mb-2 flex items-center">
                   <Banknote size={14} className="mr-1" />
                   Cash In Hand
                </p>
                <h3 className="text-2xl font-bold truncate">{formatCurrency(balanceData.cashInHand)}</h3>
             </div>
             <div className="absolute -right-4 -bottom-4 opacity-20 rotate-12">
                <Banknote size={80} />
             </div>
          </div>

          {/* CASH AT BANK */}
          <div className="bg-blue-600 p-5 rounded-2xl shadow-lg shadow-blue-200 text-white relative overflow-hidden">
             <div className="relative z-10">
                <p className="text-blue-100 text-[10px] font-bold uppercase tracking-wider mb-2 flex items-center">
                   <Landmark size={14} className="mr-1" />
                   Cash At Bank
                </p>
                <h3 className="text-2xl font-bold truncate">{formatCurrency(balanceData.cashAtBank)}</h3>
             </div>
             <div className="absolute -right-4 -bottom-4 opacity-20 rotate-12">
                <Landmark size={80} />
             </div>
          </div>
      </div>

      {/* AI Insight Section */}
      <div className="bg-white rounded-2xl border border-slate-100 p-4 shadow-sm flex items-start justify-between">
           <div className="flex-1">
               <div className="flex items-center space-x-2 mb-2">
                   <Sparkles size={16} className="text-indigo-600" />
                   <h3 className="font-bold text-indigo-900 text-sm">AI Insight</h3>
               </div>
               {insight ? (
