            <h2 className="text-xl font-semibold text-black">DAILY COLLECTION REPORT - {formatDate(selectedDate).toUpperCase()}</h2>
        </div>

        {/* Date Selector & Total */}
        <div className="bg-white p-4 rounded-xl border border-slate-200 flex justify-between items-center shadow-sm no-print">
          <div>
             <label className="text-[10px] text-slate-500 uppercase font-bold mb-1 block">Select Date</label>
             <input
                type="date"
                value={selectedDate}
                onChange={(e) => setSelectedDate(e.target.value)}
