        {/* Transactions List */}
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden print:border-black print:shadow-none">
             <div className="flex items-center bg-slate-900 p-3 border-b border-slate-200 text-xs font-bold text-white uppercase tracking-wider print:bg-black print:text-white print:border-black">
