  return (
    <div className="flex flex-col h-full bg-slate-50">
       <div className="bg-white px-4 py-3 border-b border-slate-200 sticky top-0 z-10 shadow-sm no-print">
          <div className="flex bg-slate-100 rounded-lg p-1">
             <button 
               onClick={() => setActiveTab('DAILY')}
               className={`flex-1 py-2 rounded-md text-sm font-bold flex items-center justify-center transition-all ${activeTab === 'DAILY' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
             >
                <FileText size={16} className="mr-2" />
                Daily Report
             </button>
             <button 
               onClick={() => setActiveTab('UNPAID')}
               className={`flex-1 py-2 rounded-md text-sm font-bold flex items-center justify-center transition-all ${activeTab === 'UNPAID' ? 'bg-white text-red-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
             >
                <AlertCircle size={16} className="mr-2" />
                Unpaid List
             </button>
          </div>
       </div>

       <div className="flex-1 overflow-y-auto p-4" id="printable-section">
          {activeTab === 'DAILY' ? renderDailyReport() : renderUnpaidList()}
       </div>
    </div>
  );
};

