/**
 * Loads the application state from local storage.
 * If no state is found, initializes it with default flat data.
 */
export const loadData = (): AppState => {
  const saved = localStorage.getItem(STORAGE_KEY);
  if (saved) {
    const state = JSON.parse(saved);
    // Initialize firebase if config exists
    const config = getCloudConfig();
    if (config) initFirebase(config);
    return state;
  }

  // Initial State for Continental Heights B Wing with full 231 flats
  const flats: Flat[] = INITIAL_FLAT_DATA.map(([flatNumber, ownerName, mobile], index) => ({
    id: `flat-${index}`,
    flatNumber,
    ownerName: ownerName || '',
    mobile: mobile || '',
    status: PaymentStatus.UNPAID,
    // Defaults for new Master fields
    isRented: false,
    tenantName: '',
    tenantMobile: '',
    vehicle2WCount: 0,
    vehicle4WCount: 0,
    vehicle2WNumbers: '',
    vehicle4WNumbers: ''
  }));

  const state: AppState = {
    flats,
    transactions: [],
    financialRecords: [],
    lastReceiptNo: 0, 
  };
  saveData(state);
  return state;
};

/**
 * Saves the application state to local storage and syncs with cloud if enabled.
 */
export const saveData = (state: AppState) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  if (isCloudEnabled()) {
    saveToCloud(state);
  }
};

/**
 * Updates full details for a specific flat (Master Module)
 */
export const updateFlatDetails = (state: AppState, flatId: string, updates: Partial<Flat>) => {
  // Create a deep(ish) copy to ensure React re-renders detecting state change
  const newState = { 
    ...state,
    flats: [...state.flats] 
  };

  const flatIndex = newState.flats.findIndex(f => f.id === flatId);

  if (flatIndex === -1) throw new Error("Flat not found");

  newState.flats[flatIndex] = {
    ...newState.flats[flatIndex],
    ...updates
  };

  saveData(newState);
  return newState;
};

/**
 * Processes a maintenance payment for a flat.
 */
export const processPayment = (state: AppState, flatId: string, ownerName: string, mobile: string, amount: number, date: string) => {
  const newState = { 
    ...state,
    flats: [...state.flats],
    transactions: [...state.transactions]
  };

  const flatIndex = newState.flats.findIndex(f => f.id === flatId);
  if (flatIndex === -1) throw new Error("Flat not found");

  const receiptNo = newState.lastReceiptNo + 1;
  const transaction: Transaction = {
    receiptNo,
    date,
    timestamp: Date.now(),
    flatId,
    flatNumber: newState.flats[flatIndex].flatNumber,
    ownerName,
    amount,
    mobile
  };

  // Update flat status AND master details (Name/Mobile)
  newState.flats[flatIndex] = {
    ...newState.flats[flatIndex],
    status: PaymentStatus.PAID,
    ownerName, // Syncs Collect module changes to Master
    mobile     // Syncs Collect module changes to Master
  };

  newState.transactions = [transaction, ...newState.transactions];
  newState.lastReceiptNo = receiptNo;

  saveData(newState);
  return { newState, transaction };
};

/**
 * Updates an existing maintenance transaction.
 */
export const updateTransaction = (state: AppState, receiptNo: number, updates: Partial<Transaction>) => {
  const newState = { 
    ...state,
    flats: [...state.flats],
    transactions: [...state.transactions]
  };

  const txIndex = newState.transactions.findIndex(t => t.receiptNo === receiptNo);
  if (txIndex === -1) throw new Error("Transaction not found");

  const oldTx = newState.transactions[txIndex];
  const updatedTx = { ...oldTx, ...updates };
  newState.transactions[txIndex] = updatedTx;

  // Sync owner/mobile to flat if it's the latest info
  const flatIndex = newState.flats.findIndex(f => f.id === updatedTx.flatId);
  if (flatIndex !== -1) {
    newState.flats[flatIndex] = {
      ...newState.flats[flatIndex],
      ownerName: updatedTx.ownerName, // Syncs changes to Master
      mobile: updatedTx.mobile        // Syncs changes to Master
    };
  }

  saveData(newState);
  return newState;
};

/**
 * Deletes a maintenance transaction and resets flat status if necessary.
 */
export const deleteTransaction = (state: AppState, receiptNo: number) => {
  const newState = { 
    ...state,
    flats: [...state.flats],
    transactions: [...state.transactions]
  };

  const txIndex = newState.transactions.findIndex(t => t.receiptNo === receiptNo);
  if (txIndex === -1) throw new Error("Transaction not found");

  const tx = newState.transactions[txIndex];
  newState.transactions = newState.transactions.filter(t => t.receiptNo !== receiptNo);

  // If no more transactions for this flat, mark as UNPAID
  const remainingTx = newState.transactions.find(t => t.flatId === tx.flatId);
  if (!remainingTx) {
    const flatIndex = newState.flats.findIndex(f => f.id === tx.flatId);
    if (flatIndex !== -1) {
      newState.flats[flatIndex] = {
        ...newState.flats[flatIndex],
        status: PaymentStatus.UNPAID
      };
    }
  }

  saveData(newState);
  return newState;
};

/**
 * Clears all maintenance transactions. 
 * Resets receipt counter to 0 so next is 1.
 * Keeps flat owners and mobile numbers intact.
 */
export const clearAllTransactions = (state: AppState) => {
  const newState = {
    ...state,
    transactions: [],
    flats: state.flats.map(f => ({ ...f, status: PaymentStatus.UNPAID })),
    lastReceiptNo: 0 
  };
  saveData(newState);
  return newState;
};

/**
 * Updates flat details from a CSV string.
 */
export const updateFlatsFromCSV = (state: AppState, csvText: string) => {
  const newState = { 
    ...state,
    flats: [...state.flats]
  };

  const lines = csvText.split('\n');
  let updatedCount = 0;

  lines.forEach((line, index) => {
    if (index === 0) return; // Skip headers
    const [flatNumber, ownerName, mobile] = line.split(',').map(s => s?.trim());
    if (!flatNumber) return;

    const flatIndex = newState.flats.findIndex(f => f.flatNumber === flatNumber);
    if (flatIndex !== -1) {
      newState.flats[flatIndex] = {
        ...newState.flats[flatIndex],
        ownerName: ownerName || newState.flats[flatIndex].ownerName,
        mobile: mobile || newState.flats[flatIndex].mobile,
      };
      updatedCount++;
    }
  });

  saveData(newState);
  return { newState, updatedCount };
};

/**
 * Imports maintenance transactions from a CSV string.
 */
export const importTransactionsFromCSV = (state: AppState, csvText: string) => {
  const newState = { 
    ...state,
    flats: [...state.flats],
    transactions: [...state.transactions]
  };

  const lines = csvText.split('\n');
  let count = 0;
  const errors: string[] = [];

  lines.forEach((line, index) => {
    if (index === 0) return;
    const parts = line.split(',').map(s => s?.trim());
    const [date, flatNumber, amountStr, receiptNoStr, ownerName] = parts;
    if (!flatNumber || !amountStr) return;

    const amount = parseFloat(amountStr);
    const flat = newState.flats.find(f => f.flatNumber === flatNumber);

    if (flat) {
      const receiptNo = receiptNoStr ? parseInt(receiptNoStr) : newState.lastReceiptNo + 1;
      const transaction: Transaction = {
        receiptNo,
        date: date || new Date().toISOString().split('T')[0],
        timestamp: Date.now(),
        flatId: flat.id,
        flatNumber,
        ownerName: ownerName || flat.ownerName,
        amount,
        mobile: flat.mobile || ''
      };

      newState.transactions = [transaction, ...newState.transactions];
      if (receiptNo > newState.lastReceiptNo) newState.lastReceiptNo = receiptNo;

      const flatIndex = newState.flats.findIndex(f => f.id === flat.id);
      newState.flats[flatIndex] = {
         ...newState.flats[flatIndex],
         status: PaymentStatus.PAID
      };
      count++;
    } else {
      errors.push(`Flat ${flatNumber} not found at line ${index + 1}`);
    }
  });

  saveData(newState);
  return { newState, count, errors };
};

/**
 * Exports all database tables to an Excel file.
 */
export const exportDataToExcel = (state: AppState) => {
  const wb = XLSX.utils.book_new();

  const flatsSheet = XLSX.utils.json_to_sheet(state.flats);
  XLSX.utils.book_append_sheet(wb, flatsSheet, "Flats");

  const txSheet = XLSX.utils.json_to_sheet(state.transactions);
  XLSX.utils.book_append_sheet(wb, txSheet, "Transactions");

  const financeSheet = XLSX.utils.json_to_sheet(state.financialRecords);
  XLSX.utils.book_append_sheet(wb, financeSheet, "FinancialRecords");

  XLSX.writeFile(wb, `CH_Backup_${new Date().toISOString().split('T')[0]}.xlsx`);
};

/**
 * Imports data from an uploaded Excel file.
 */
export const importDataFromExcel = async (file: File): Promise<AppState> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });

        const flats = XLSX.utils.sheet_to_json(workbook.Sheets["Flats"]) as Flat[];
        const transactions = XLSX.utils.sheet_to_json(workbook.Sheets["Transactions"]) as Transaction[];
        const financialRecords = XLSX.utils.sheet_to_json(workbook.Sheets["FinancialRecords"]) as FinancialRecord[];

        if (!flats || flats.length === 0) throw new Error("Invalid format: No flats found");

        const lastReceiptNo = transactions.reduce((max, t) => Math.max(max, t.receiptNo), 0);

        const newState: AppState = {
          flats,
          transactions,
          financialRecords: financialRecords || [],
          lastReceiptNo
        };
        saveData(newState);
        resolve(newState);
      } catch (err) {
        reject(err);
      }
    };
    reader.readAsArrayBuffer(file);
  });
};

/**
 * Creates a system restore point in local storage.
 */
export const createSystemSnapshot = (state: AppState) => {
  localStorage.setItem(SNAPSHOT_KEY, JSON.stringify({
    state,
    timestamp: Date.now()
  }));
};

/**
 * Restores the application state from the saved restore point.
 */
export const restoreSystemSnapshot = (): AppState | null => {
  const saved = localStorage.getItem(SNAPSHOT_KEY);
  if (!saved) return null;
  const { state } = JSON.parse(saved);
  saveData(state);
  return state;
};

/**
 * Gets the timestamp of the saved restore point.
 */
export const getSnapshotTimestamp = (): number | null => {
  const saved = localStorage.getItem(SNAPSHOT_KEY);
  if (!saved) return null;
  const { timestamp } = JSON.parse(saved);
  return timestamp;
};

/**
 * Saves Firebase configuration for cloud sync.
 */
export const saveCloudConfig = (config: FirebaseConfig) => {
  localStorage.setItem('firebase_config', JSON.stringify(config));
  initFirebase(config);
};

/**
 * Retrieves the saved Firebase configuration.
 */
export const getCloudConfig = (): FirebaseConfig | null => {
  const saved = localStorage.getItem('firebase_config');
  return saved ? JSON.parse(saved) : null;
};

/**
 * Syncs the local state with the cloud database.
 */
export const syncFromCloud = async (): Promise<AppState | null> => {
  const data = await loadFromCloud();
  if (data) {
    saveData(data);
    return data;
  }
  return null;
};

/**
 * Adds a new financial record (income, expense, or transfer).
 */
export const addFinancialRecord = (state: AppState, record: Omit<FinancialRecord, 'id' | 'timestamp'>) => {
  const newState = { 
    ...state,
    financialRecords: [...state.financialRecords]
  };
  const newRecord: FinancialRecord = {
    ...record,
    id: `fin-${Date.now()}`,
    timestamp: Date.now(),
    // Fallback defaults for safety if omitted
    type: record.type || 'EXPENSE',
    paymentMode: record.paymentMode || 'CASH'
  };
  newState.financialRecords = [newRecord, ...newState.financialRecords];
  saveData(newState);
  return newState;
};

/**
 * Updates an existing financial record.
 */
export const updateFinancialRecord = (state: AppState, id: string, updates: Partial<FinancialRecord>) => {
  const newState = { 
    ...state,
    financialRecords: [...state.financialRecords]
  };
  const index = newState.financialRecords.findIndex(r => r.id === id);
  if (index !== -1) {
    newState.financialRecords[index] = { ...newState.financialRecords[index], ...updates };
    saveData(newState);
  }
  return newState;
};

/**
 * Deletes a financial record.
 */
export const deleteFinancialRecord = (state: AppState, id: string) => {
  const newState = { 
    ...state,
    financialRecords: state.financialRecords.filter(r => r.id !== id)
  };
  saveData(newState);
  return newState;
};

/**
 * Clears all financial records.
 */
export const clearFinancialRecords = (state: AppState) => {
  const newState = { ...state, financialRecords: [] };
  saveData(newState);
  return newState;
};

/**
 * Imports financial records from a CSV string.
 */
export const importFinancialRecordsFromCSV = (state: AppState, csvText: string) => {
  const newState = { 
    ...state,
    financialRecords: [...state.financialRecords]
  };

  const lines = csvText.split('\n');
  let count = 0;
  const errors: string[] = [];

  lines.forEach((line, index) => {
    if (index === 0) return;
    const parts = line.split(',').map(s => s?.trim());
    // Extended CSV support: Date, Type, Amount, Category, Description, Mode (Optional)
    const [date, type, amountStr, category, description, mode] = parts;
    if (!type || !amountStr) return;

    const amount = parseFloat(amountStr);
    if (!isNaN(amount)) {
      const record: FinancialRecord = {
        id: `fin-${Date.now()}-${count}`,
        type: (type.toUpperCase() as any), // 'INCOME' | 'EXPENSE' | 'TRANSFER'
        amount,
        date: date || new Date().toISOString().split('T')[0],
        category: category || 'General',
        description: description || '',
        // Default to CASH if mode is missing or invalid
        paymentMode: (mode?.toUpperCase() === 'BANK') ? 'BANK' : 'CASH',
        timestamp: Date.now()
      };
      newState.financialRecords = [record, ...newState.financialRecords];
      count++;
    } else {
      errors.push(`Invalid amount at line ${index + 1}`);
    }
  });

  saveData(newState);
  return { newState, count, errors };
};

/**
 * Updates the AI generated insight in the application state.
 */
export const updateInsight = (state: AppState, text: string) => {
  const newState = {
    ...state,
    aiInsight: {
      text,
      timestamp: Date.now()
    }
  };
  saveData(newState);
  return newState;
};

