export const generateWhatsAppLink = (
  mobile: string, 
  receiptNo: number, 
  name: string, 
  flat: string, 
  amount: number, 
  date: string
): string => {
  if (!mobile) return '#';

  // 1. Remove ALL non-digit characters (especially the + sign and spaces)
  let cleanMobile = mobile.replace(/\D/g, '');

  // 2. Handle 11-digit numbers starting with 0 (e.g. 09876543210 -> 9876543210)
  if (cleanMobile.length === 11 && cleanMobile.startsWith('0')) {
    cleanMobile = cleanMobile.substring(1);
  }

  // 3. Robust Country Code Logic for wa.me API:
  // If the number is exactly 10 digits, it's missing the country code. 
  // Prepend '91' but NO plus sign, as WhatsApp API fails with '+' or spaces.
  if (cleanMobile.length === 10) {
    cleanMobile = `91${cleanMobile}`;
