  if (!n) return '';

  let str = '';
  str += (Number(n[1]) !== 0) ? (a[Number(n[1])] || b[n[1][0] as any] + ' ' + a[n[1][1] as any]) + 'Crore ' : '';
  str += (Number(n[2]) !== 0) ? (a[Number(n[2])] || b[n[2][0] as any] + ' ' + a[n[2][1] as any]) + 'Lakh ' : '';
  str += (Number(n[3]) !== 0) ? (a[Number(n[3])] || b[n[3][0] as any] + ' ' + a[n[3][1] as any]) + 'Thousand ' : '';
  str += (Number(n[4]) !== 0) ? (a[Number(n[4])] || b[n[4][0] as any] + ' ' + a[n[4][1] as any]) + 'Hundred ' : '';
  str += (Number(n[5]) !== 0) ? ((str !== '') ? 'and ' : '') + (a[Number(n[5])] || b[n[5][0] as any] + ' ' + a[n[5][1] as any]) : '';

  return str.trim() + ' Only';
};

/**
 * Cleans the mobile number according to user requirement:
 * - Remove all non-digits (spaces, plus signs, etc.)
 * - Remove '91' country code if present (at start of 12 digits)
 * - Take only first 10 digits if multiple numbers exist
 */
const getCleanLocalMobile = (mobile: string): string => {
  if (!mobile) return '';

  // 1. Remove all non-digits (strips '+', spaces, '/', etc.)
  let clean = mobile.replace(/\D/g, '');

  // 2. Remove leading '0' if 11 digits
  if (clean.length === 11 && clean.startsWith('0')) {
    clean = clean.substring(1);
  }

  // 3. Remove '91' if 12 digits
  if (clean.length === 12 && clean.startsWith('91')) {
    clean = clean.substring(2);
  }

  // 4. Ensure we only take first 10 digits (handles cases like "9876543210 / 9123456780")
  if (clean.length > 10) {
    clean = clean.substring(0, 10);
  }

  return clean;
};

