/**
 * Cleans the mobile number and ensures it has the correct international format for WhatsApp.
 * Without the '91' prefix, WhatsApp might misinterpret numbers starting with '961' as Lebanon.
 */
const getCleanLocalMobile = (mobile: string): string => {
  if (!mobile) return '';

  // 1. Remove all non-digits
  let clean = mobile.replace(/\D/g, '');

  // 2. Handle cases where user stored multiple numbers or had extra digits
  // If it's a standard 10 digit Indian number, we need to add 91
  if (clean.length === 10) {
    return '91' + clean;
  }

  // 3. If it's 11 digits starting with 0, remove 0 and add 91
  if (clean.length === 11 && clean.startsWith('0')) {
    return '91' + clean.substring(1);
  }

  // 4. If it's already 12 digits starting with 91, it's perfect
  if (clean.length === 12 && clean.startsWith('91')) {
    return clean;
  }

  // 5. Fallback: If it's messy but looks like an Indian number, 
  // try to find the last 10 digits and prefix 91
  if (clean.length > 10) {
    return '91' + clean.slice(-10);
  }

  return clean;
};

