                  <div key={t.receiptNo} className="flex items-center p-3 text-xs hover:bg-slate-50 transition-colors print:hover:bg-transparent">
                    <div className="w-12 shrink-0 font-mono text-slate-500 print:text-black">#{t.receiptNo}</div>
                    <div className="w-16 shrink-0 font-bold text-slate-800 print:text-black">{t.flatNumber}</div>
                    <div className="flex-1 min-w-0 px-2 truncate text-slate-600 print:text-black font-medium" title={t.ownerName}>
                        {t.ownerName}
                    </div>
                    <div className="w-20 shrink-0 text-right">
                        <div className="font-extrabold text-emerald-600 uppercase tracking-tighter text-[13px] print:text-black">PAID</div>
                    </div>
                    <div className="w-10 shrink-0 flex justify-end space-x-1 no-print">
                        <a 
                             href={generateWhatsAppLink(t.mobile, t.receiptNo, t.ownerName, t.flatNumber, t.amount, formatDate(t.date))}
                             target="_blank"
                             rel="noreferrer"
                             className="text-green-600 p-1.5 hover:bg-green-100 rounded transition-colors"
                        >
                            <Share2 size={14} />
                        </a>
                    </div>
                  </div>
                ))}
             </div>
        </div>
    </div>
  );

  const renderUnpaidList = () => (
    <div className="space-y-6">
       {/* Screen Header for Unpaid */}
       <div className="flex justify-between items-center no-print">
        <div className="flex items-center space-x-2">
            <h2 className="text-lg font-bold text-slate-800">Pending Payments</h2>
            <span className="bg-red-100 text-red-700 px-2 py-0.5 rounded-full text-[10px] font-bold">
            {unpaidFlats.length}
            </span>
        </div>
        <button 
            onClick={handleDownload} 
            className="flex items-center space-x-2 text-white bg-blue-600 px-3 py-2 rounded-lg text-xs font-bold hover:bg-blue-700 shadow-md transition-colors"
          >
            <Download size={14} />
            <span>PDF</span>
          </button>
       </div>

       {/* Print Only Header */}
       <div className="hidden print:block text-center mb-6 border-b border-black pb-4">
            <h1 className="text-2xl font-bold text-black mb-1">CONTINENTAL HEIGHTS B WING</h1>
            <h2 className="text-xl font-semibold text-black">PENDING PAYMENTS LIST - {formatDate(getTodayDateString()).toUpperCase()}</h2>
            <div className="mt-2 text-right">
                <p className="font-bold text-black text-sm">Total Pending: Rs. {(unpaidFlats.length * MAINTENANCE_AMOUNT).toLocaleString('en-IN')}</p>
            </div>
       </div>

       <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden print:border-black print:shadow-none">
        <div className="flex items-center bg-black p-3 border-b border-black text-xs font-bold text-white uppercase tracking-wider print:bg-black print:text-white print:border-black sticky top-0">
           <div className="w-20 shrink-0">Flat</div>
           <div className="flex-1 min-w-0 px-2">Owner</div>
           <div className="w-10 shrink-0 text-center no-print"></div>
        </div>

        <div className="divide-y divide-slate-100 print:divide-black bg-white">
          {unpaidFlats.map(flat => (
            <div key={flat.id} className="flex items-center p-3 text-xs hover:bg-slate-50 transition-colors print:hover:bg-transparent">
               <div className="w-20 shrink-0 font-bold text-slate-800 print:text-black">{flat.flatNumber}</div>
               <div className="flex-1 min-w-0 px-2 truncate text-slate-600 print:text-black font-medium" title={flat.ownerName}>
                  {flat.ownerName || '-'}
               </div>
               <div className="w-10 shrink-0 flex justify-center no-print">
                   {flat.mobile && (
                     <a 
                       href={generateReminderLink(flat.mobile, flat.ownerName, flat.flatNumber)}
                       target="_blank"
                       rel="noreferrer"
                       className="text-green-600 p-1.5 hover:bg-green-100 rounded transition-colors"
                     >
                        <MessageCircle size={16} />
                     </a>
                   )}
               </div>
            </div>
          ))}
          {unpaidFlats.length === 0 && (
             <div className="p-10 text-center flex flex-col items-center justify-center text-green-600">
                <CheckCircle2 size={40} className="mb-2 opacity-50" />
                <p className="font-bold">All payments collected!</p>
             </div>
          )}
        </div>
       </div>
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-slate-50">
       <div className="bg-white px-4 py-3 border-b border-slate-200 sticky top-0 z-10 shadow-sm no-print">
          <div className="flex bg-slate-100 rounded-lg p-1">
             <button 
               onClick={() => setActiveTab('DAILY')}
               className={`flex-1 py-2 rounded-md text-sm font-bold flex items-center justify-center transition-all ${activeTab === 'DAILY' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
             >
                <FileText size={16} className="mr-2" />
                Daily Report
             </button>
             <button 
               onClick={() => setActiveTab('UNPAID')}
               className={`flex-1 py-2 rounded-md text-sm font-bold flex items-center justify-center transition-all ${activeTab === 'UNPAID' ? 'bg-white text-red-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
             >
                <AlertCircle size={16} className="mr-2" />
                Unpaid List
             </button>
          </div>
       </div>

       <div className="flex-1 overflow-y-auto p-4" id="printable-section">
          {activeTab === 'DAILY' ? renderDailyReport() : renderUnpaidList()}
       </div>
    </div>
  );
};

