  const env = loadEnv(mode, '.', '');
  return {
    plugins: [react()],
    base: './', // CRITICAL: Ensures assets load using relative paths for APK/Cordova/Capacitor
    define: {
      // Polyfill process.env for the @google/genai SDK compatibility
      'process.env': env
    },
    build: {
