import React, { useRef, useState, useEffect } from 'react';
import { AppState } from '../types';
import { updateFlatsFromCSV, exportDataToExcel, importDataFromExcel, importTransactionsFromCSV, createSystemSnapshot, restoreSystemSnapshot, getSnapshotTimestamp, saveCloudConfig, getCloudConfig, syncFromCloud, importFinancialRecordsFromCSV, clearFinancialRecords } from '../services/storageService';
import { downloadSampleCsv, downloadTransactionSampleCsv, downloadFinanceSampleCsv } from '../utils/helpers';
import { Upload, Download, FileText, CheckCircle, AlertTriangle, Database, Save, Receipt, RefreshCw, RotateCcw, History, Smartphone, Cloud, Wallet, Trash2 } from 'lucide-react';
import { STORAGE_KEY } from '../constants';

interface SettingsProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
}

const Settings: React.FC<SettingsProps> = ({ state, refreshState }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const dbInputRef = useRef<HTMLInputElement>(null);
  const txFileInputRef = useRef<HTMLInputElement>(null);
  const financeFileInputRef = useRef<HTMLInputElement>(null);

  const [status, setStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });
  const [snapshotTime, setSnapshotTime] = useState<string | null>(null);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  // Cloud Config State
  const [cloudConfig, setCloudConfig] = useState({ apiKey: '', authDomain: '', projectId: '' });
  const [cloudConnected, setCloudConnected] = useState(false);

  useEffect(() => {
    // Load snapshot time
    const ts = getSnapshotTimestamp();
    if (ts) {
        setSnapshotTime(new Date(ts).toLocaleString());
    }

    // Load cloud config
    const savedConfig = getCloudConfig();
    if (savedConfig) {
      setCloudConfig({
        apiKey: savedConfig.apiKey,
        authDomain: savedConfig.authDomain,
        projectId: savedConfig.projectId
      });
      setCloudConnected(true);
    }

    // Listen for PWA install prompt
    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  const handleInstallClick = () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      deferredPrompt.userChoice.then((choiceResult: any) => {
        if (choiceResult.outcome === 'accepted') {
          console.log('User accepted the install prompt');
        }
        setDeferredPrompt(null);
      });
    }
  };

  // Cloud Config Handler
  const handleSaveCloudConfig = () => {
    if (!cloudConfig.apiKey || !cloudConfig.projectId) {
      setStatus({ type: 'error', message: 'API Key and Project ID are required.' });
      return;
    }

    saveCloudConfig(cloudConfig);
    setCloudConnected(true);
    setStatus({ type: 'success', message: 'Cloud configuration saved! App is now connected to Firebase.' });

    // Auto sync
    handleCloudSync();
  };

  const handleCloudSync = async () => {
    try {
      const cloudData = await syncFromCloud();
      if (cloudData) {
        refreshState(cloudData);
        setStatus({ type: 'success', message: 'Successfully synced data from Cloud!' });
      } else {
        setStatus({ type: 'error', message: 'Connected, but no data found in Cloud yet. Saving local data to cloud...' });
        // Trigger a save to push local data to cloud
        // (saveData calls saveToCloud internally if config exists)
      }
    } catch (e) {
       setStatus({ type: 'error', message: 'Failed to sync with Cloud.' });
    }
  };

  // CSV Bulk Update (Flats)
  const handleCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (text) {
        try {
          const { newState, updatedCount } = updateFlatsFromCSV(state, text);
          refreshState(newState);
          setStatus({
            type: 'success',
            message: `Successfully updated details for ${updatedCount} flats!`
          });
          if (fileInputRef.current) fileInputRef.current.value = '';
        } catch (error) {
           setStatus({
            type: 'error',
            message: 'Failed to process CSV.'
          });
        }
      }
    };
    reader.readAsText(file);
  };

  // CSV Bulk Import (Transactions)
  const handleTxCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (text) {
        try {
          const { newState, count, errors } = importTransactionsFromCSV(state, text);
          refreshState(newState);

          let msg = `Successfully imported ${count} transactions.`;
          if (errors.length > 0) {
            msg += ` ${errors.length} rows failed. Check console.`;
            console.warn("Import Errors:", errors);
          }

          if (count > 0) {
              setStatus({ type: 'success', message: msg });
           } else if (errors.length > 0) {
              setStatus({ type: 'error', message: "Failed to import any transactions. Check file format." });
           } else {
              setStatus({ type: 'idle', message: "" });
           }

          if (txFileInputRef.current) txFileInputRef.current.value = '';
        } catch (error) {
           setStatus({
            type: 'error',
            message: 'Failed to process CSV.'
          });
        }
      }
    };
    reader.readAsText(file);
  };

  // CSV Bulk Import (Financial Records)
  const handleFinanceCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (text) {
        try {
          const { newState, count, errors } = importFinancialRecordsFromCSV(state, text);
          refreshState(newState);

          let msg = `Successfully imported ${count} financial records.`;
          if (errors.length > 0) {
             console.warn("Import Errors:", errors);
             msg += ` (Some rows failed)`;
          }

          if (count > 0) {
              setStatus({ type: 'success', message: msg });
          } else {
              setStatus({ type: 'error', message: "Failed to import records. Check format." });
          }

          if (financeFileInputRef.current) financeFileInputRef.current.value = '';
        } catch (error) {
           setStatus({
            type: 'error',
            message: 'Failed to process CSV.'
          });
        }
      }
    };
    reader.readAsText(file);
  };

  // Excel Database Export
  const handleExportDB = () => {
    try {
      exportDataToExcel(state);
      setStatus({ type: 'success', message: 'Database exported to Excel successfully.' });
    } catch (e) {
      setStatus({ type: 'error', message: 'Failed to export database.' });
    }
  };

  // Excel Database Import
  const handleImportDB = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!window.confirm("WARNING: This will OVERWRITE all current data with the data from the Excel file. Are you sure?")) {
      if (dbInputRef.current) dbInputRef.current.value = '';
      return;
    }

    try {
      const newState = await importDataFromExcel(file);
      refreshState(newState);
      setStatus({ type: 'success', message: 'Database restored from Excel successfully.' });
    } catch (e) {
      console.error(e);
      // Show the specific error message
      const msg = e instanceof Error ? e.message : 'Unknown error occurred during import.';
      setStatus({ type: 'error', message: msg });
    }
    if (dbInputRef.current) dbInputRef.current.value = '';
  };

  const handleClearFinance = () => {
     if (window.confirm("Are you sure you want to DELETE ALL FINANCE RECORDS?\n\nThis will clear the Accounts data (Income/Expense).")) {
        const newState = clearFinancialRecords(state);
        refreshState(newState);
        setStatus({ type: 'success', message: 'All finance records cleared.' });
    }
