import { initializeApp, FirebaseApp } from 'firebase/app';
import { getFirestore, doc, setDoc, getDoc, Firestore } from 'firebase/firestore';
import { AppState } from '../types';

let app: FirebaseApp | null = null;
let db: Firestore | null = null;
const COLLECTION_NAME = 'app_data';
const DOC_ID = 'main_db';

export interface FirebaseConfig {
  apiKey: string;
  authDomain: string;
  projectId: string;
  storageBucket?: string;
  messagingSenderId?: string;
  appId?: string;
}

// --- HARDCODED CONFIGURATION ---
// TODO: Paste your Firebase Console > Project Settings > General > Config values here
const HARDCODED_CONFIG: FirebaseConfig = {
  apiKey: "PASTE_YOUR_API_KEY_HERE",
  authDomain: "PASTE_YOUR_PROJECT_ID.firebaseapp.com",
  projectId: "PASTE_YOUR_PROJECT_ID",
  storageBucket: "",
  messagingSenderId: "",
  appId: ""
};

export const initFirebase = (config?: FirebaseConfig) => {
  try {
    // Priority: Function Argument > Hardcoded Config
    const configToUse = config || HARDCODED_CONFIG;

    // specific check to avoid initializing with placeholders
    if (!configToUse.apiKey || configToUse.apiKey.includes('PASTE_YOUR')) {
        // console.warn("Firebase Config missing or incomplete.");
        return false;
    }

    if (!app) {
      app = initializeApp(configToUse);
      db = getFirestore(app);
      console.log("Firebase initialized successfully");
    }
    return true;
  } catch (error) {
    console.error("Firebase initialization failed", error);
    return false;
  }
};

export const saveToCloud = async (data: AppState): Promise<boolean> => {
  if (!db) {
    // Try initializing in case it wasn't called yet
    if (!initFirebase()) {
        console.warn("Cannot save to cloud: Firebase not initialized");
        return false;
    }
  }

  // db check again after potential init
  if (!db) return false;

  try {
    await setDoc(doc(db, COLLECTION_NAME, DOC_ID), data);
    console.log("Data saved to cloud successfully");
    return true;
  } catch (error) {
    console.error("Failed to save to cloud", error);
    return false;
  }
};

export const loadFromCloud = async (): Promise<AppState | null> => {
  if (!db) {
     if (!initFirebase()) {
        console.warn("Cannot load from cloud: Firebase not initialized");
        return null;
     }
  }

  // db check again after potential init
  if (!db) return null;

  try {
    const docRef = doc(db, COLLECTION_NAME, DOC_ID);
    const docSnap = await getDoc(docRef);

    if (docSnap.exists()) {
      console.log("Data loaded from cloud");
      return docSnap.data() as AppState;
    } else {
      console.log("No cloud data found!");
      return null;
    }
  } catch (error) {
    console.error("Failed to load from cloud", error);
    return null;
  }
};

export const isCloudEnabled = (): boolean => {
  // If db is not null, it's enabled. 
  // If db is null, try init. If init works, it's enabled.
  if (db) return true;
  return initFirebase();
};

