import { isCloudEnabled } from '../services/firebaseService';

interface SettingsProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
}

const Settings: React.FC<SettingsProps> = ({ state, refreshState }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const dbInputRef = useRef<HTMLInputElement>(null);
  const txFileInputRef = useRef<HTMLInputElement>(null);
  const financeFileInputRef = useRef<HTMLInputElement>(null);

  const [status, setStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });
  const [snapshotTime, setSnapshotTime] = useState<string | null>(null);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  const [cloudConnected, setCloudConnected] = useState(false);

  useEffect(() => {
    // Load snapshot time
    const ts = getSnapshotTimestamp();
    if (ts) {
        setSnapshotTime(new Date(ts).toLocaleString());
    }

    // Check cloud connection (auto-init via hardcoded config)
    if (isCloudEnabled()) {
      setCloudConnected(true);
      // Optional: Auto sync on load of settings to ensure freshness
      // handleCloudSync(); 
    }

    // Listen for PWA install prompt
    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  const handleInstallClick = () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      deferredPrompt.userChoice.then((choiceResult: any) => {
        if (choiceResult.outcome === 'accepted') {
          console.log('User accepted the install prompt');
        }
        setDeferredPrompt(null);
      });
    }
  };

