      const text = event.target?.result as string;
      if (text) {
        try {
          const { newState, updatedCount } = updateFlatsFromCSV(state, text);
          refreshState(newState);
          setStatus({
            type: 'success',
            message: `Successfully updated details for ${updatedCount} flats!`
