  apiKey: "AIzaSyAcFWaCkEMT8pdNwCyNhPrbbr9I7EPbImA",
  authDomain: "continental-heights-b-wi-21189.firebaseapp.com",
  projectId: "continental-heights-b-wi-21189",
  storageBucket: "",
  messagingSenderId: "",
  appId: ""
};

export const initFirebase = (config?: FirebaseConfig) => {
  try {
    // Priority: Function Argument > Hardcoded Config
    const configToUse = config || HARDCODED_CONFIG;

    // specific check to avoid initializing with placeholders
    if (!configToUse.apiKey || configToUse.apiKey.includes('PASTE_YOUR')) {
        return false;
    }

    // Check if app is already initialized to avoid "Firebase: Firebase App named '[DEFAULT]' already exists" error
    if (!getApps().length) {
      app = initializeApp(configToUse);
    } else {
      app = getApps()[0];
    }

    // Initialize Firestore
    if (!db) {
      db = getFirestore(app);
      console.log("Firebase/Firestore initialized successfully");
    }

    return true;
  } catch (error) {
    console.error("Firebase initialization failed", error);
    return false;
  }
};

export const saveToCloud = async (data: AppState): Promise<boolean> => {
  // Ensure DB is ready
  if (!db) {
    if (!initFirebase()) {
        console.warn("Cannot save to cloud: Firebase not initialized");
        return false;
    }
  }

  if (!db) return false;

  try {
    await setDoc(doc(db, COLLECTION_NAME, DOC_ID), data);
    console.log("Data saved to cloud successfully");
    return true;
  } catch (error) {
    console.error("Failed to save to cloud", error);
    return false;
  }
};

export const loadFromCloud = async (): Promise<AppState | null> => {
  // Ensure DB is ready
  if (!db) {
     if (!initFirebase()) {
        console.warn("Cannot load from cloud: Firebase not initialized");
        return null;
     }
  }

  if (!db) return null;

  try {
    const docRef = doc(db, COLLECTION_NAME, DOC_ID);
    const docSnap = await getDoc(docRef);

    if (docSnap.exists()) {
      console.log("Data loaded from cloud");
      return docSnap.data() as AppState;
    } else {
      console.log("No cloud data found!");
      return null;
    }
  } catch (error) {
    console.error("Failed to load from cloud", error);
    return null;
  }
};

export const isCloudEnabled = (): boolean => {
  if (db) return true;
  return initFirebase();
};

