/**
 * Loads the application state from local storage.
 */
export const loadData = (): AppState => {
  // Always attempt to init firebase first with hardcoded config if available
  // We do not wait for result, just kick off init
  initFirebase();

  const saved = localStorage.getItem(STORAGE_KEY);

  if (saved) {
    try {
      const state = JSON.parse(saved);
      // Basic validation: ensure it's an object with flats
      if (state && Array.isArray(state.flats)) {
         return state;
      }
    } catch (e) {
      console.error("Failed to parse saved data", e);
    }
  }

  // Initial State if no valid saved data exists
  const flats: Flat[] = INITIAL_FLAT_DATA.map(([flatNumber, ownerName, mobile], index) => ({
    id: `flat-${index}`,
    flatNumber,
    ownerName: ownerName || '',
    mobile: mobile || '',
    status: PaymentStatus.UNPAID,
    isRented: false,
    tenantName: '',
    tenantMobile: '',
    vehicle2WCount: 0,
    vehicle4WCount: 0,
    vehicle2WNumbers: '',
    vehicle4WNumbers: ''
  }));

  const state: AppState = {
    flats,
    transactions: [],
    financialRecords: [],
    lastReceiptNo: 0, 
  };

  saveData(state);
  return state;
};

/**
 * Saves the application state to local storage and syncs with cloud if enabled.
 */
export const saveData = (state: AppState) => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));

    // Automatic Cloud Sync Logic
    // We try to save to cloud every time data changes locally.
    // If initialization hasn't happened yet, we try to init and then save.
    if (isCloudEnabled()) {
      saveToCloud(state).then(success => {
        if (!success) console.warn("Background cloud upload failed.");
      });
    } else {
        // Attempt lazy initialization
        if (initFirebase()) {
            saveToCloud(state);
        }
    }
  } catch (e) {
    console.error("Failed to save data to localStorage", e);
  }
};

export const uploadCurrentDataToCloud = async (state: AppState): Promise<boolean> => {
  return await saveToCloud(state);
};

