import React, { useRef, useState, useEffect } from 'react';
import { AppState } from '../types';
import { updateFlatsFromCSV, exportDataToExcel, importDataFromExcel, importTransactionsFromCSV, createSystemSnapshot, restoreSystemSnapshot, getSnapshotTimestamp, syncFromCloud, importFinancialRecordsFromCSV, clearFinancialRecords, uploadCurrentDataToCloud, saveCloudConfig, getCloudConfig } from '../services/storageService';
import { downloadSampleCsv, downloadTransactionSampleCsv, downloadFinanceSampleCsv } from '../utils/helpers';
import { Upload, Download, FileText, CheckCircle, AlertTriangle, Database, Save, Receipt, RefreshCw, RotateCcw, History, Smartphone, Cloud, Wallet, Trash2, Lock, ArrowUpCircle, X, ChevronDown, ChevronUp } from 'lucide-react';
import { initFirebase } from '../services/firebaseService';

interface SettingsProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
}

const Settings: React.FC<SettingsProps> = ({ state, refreshState }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const dbInputRef = useRef<HTMLInputElement>(null);
  const txFileInputRef = useRef<HTMLInputElement>(null);
  const financeFileInputRef = useRef<HTMLInputElement>(null);

  const [status, setStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });
  const [snapshotTime, setSnapshotTime] = useState<string | null>(null);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  const [cloudConnected, setCloudConnected] = useState(false);
  const [showConfigForm, setShowConfigForm] = useState(false);

  // Cloud Config State
  const [apiKey, setApiKey] = useState('');
  const [projectId, setProjectId] = useState('');
  const [authDomain, setAuthDomain] = useState('');

  useEffect(() => {
    // Load snapshot time
    const ts = getSnapshotTimestamp();
    if (ts) {
        setSnapshotTime(new Date(ts).toLocaleString());
    }

    // Check saved config
    const savedConfig = getCloudConfig();
    if (savedConfig) {
        setApiKey(savedConfig.apiKey);
        setProjectId(savedConfig.projectId);
        setAuthDomain(savedConfig.authDomain);
        if (initFirebase(savedConfig)) {
            setCloudConnected(true);
        } else {
            // Config exists but failed to init
            setCloudConnected(false);
            setShowConfigForm(true);
        }
    } else {
        setShowConfigForm(true);
    }

    // Listen for PWA install prompt
    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  const handleInstallClick = () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      deferredPrompt.userChoice.then((choiceResult: any) => {
        if (choiceResult.outcome === 'accepted') {
          console.log('User accepted the install prompt');
        }
        setDeferredPrompt(null);
      });
    }
  };

  const handleConnectCloud = () => {
    if (!apiKey || !projectId) {
        setStatus({ type: 'error', message: 'API Key and Project ID are required.' });
        return;
    }

    const config = {
        apiKey,
        projectId,
        authDomain: authDomain || `${projectId}.firebaseapp.com`
    };

    if (initFirebase(config)) {
        saveCloudConfig(config);
        setCloudConnected(true);
        setShowConfigForm(false);
        setStatus({ type: 'success', message: 'Connected to Firebase successfully!' });
    } else {
        setStatus({ type: 'error', message: 'Connection failed. Check your credentials.' });
    }
  };

  const handleDisconnectCloud = () => {
      localStorage.removeItem('firebase_config');
      setCloudConnected(false);
      setShowConfigForm(true);
      setStatus({ type: 'idle', message: 'Disconnected. Please reload if needed.' });
      // Reloading is often safest to clear Firebase instance state
      if(window.confirm("Disconnecting requires a reload. Reload now?")) {
          window.location.reload();
      }
  };

  const handleCloudSync = async () => {
    setStatus({ type: 'idle', message: 'Connecting to Cloud...' });
    try {
      const cloudData = await syncFromCloud();
      if (cloudData) {
        if(window.confirm("Found data on Cloud. This will OVERWRITE your local data. Proceed?")) {
            refreshState(cloudData);
            setStatus({ type: 'success', message: 'Successfully restored data from Cloud!' });
        } else {
            setStatus({ type: 'idle', message: 'Sync cancelled.' });
        }
      } else {
        // If cloud is empty, suggest uploading
        if (window.confirm("Cloud database is empty. Do you want to UPLOAD your current local data to seed the cloud?")) {
            handleCloudUpload();
        } else {
            setStatus({ type: 'error', message: 'No data found on Cloud.' });
        }
      }
    } catch (e) {
       setStatus({ type: 'error', message: 'Failed to connect to Cloud.' });
    }
  };

  const handleCloudUpload = async () => {
    try {
        const success = await uploadCurrentDataToCloud(state);
        if (success) {
            setStatus({ type: 'success', message: 'Data uploaded to Cloud successfully! Auto-sync is now active.' });
        } else {
            setStatus({ type: 'error', message: 'Failed to upload. Check internet connection.' });
        }
    } catch (e) {
        setStatus({ type: 'error', message: 'Error uploading to cloud.' });
    }
  };

  // CSV Bulk Update (Flats)
  const handleCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (text) {
        try {
          const { newState, updatedCount } = updateFlatsFromCSV(state, text);
          refreshState(newState);
          setStatus({
            type: 'success',
            message: `Successfully updated details for ${updatedCount} flats!`
          });
          if (fileInputRef.current) fileInputRef.current.value = '';
        } catch (error) {
           setStatus({
            type: 'error',
            message: 'Failed to process CSV.'
          });
        }
      }
    };
    reader.readAsText(file);
  };

  // CSV Bulk Import (Transactions)
  const handleTxCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (text) {
        try {
          const { newState, count, errors } = importTransactionsFromCSV(state, text);
          refreshState(newState);

          let msg = `Successfully imported ${count} transactions.`;
          if (errors.length > 0) {
            msg += ` ${errors.length} rows failed. Check console.`;
            console.warn("Import Errors:", errors);
          }

          if (count > 0) {
              setStatus({ type: 'success', message: msg });
           } else if (errors.length > 0) {
              setStatus({ type: 'error', message: "Failed to import any transactions. Check file format." });
           } else {
              setStatus({ type: 'idle', message: "" });
           }

          if (txFileInputRef.current) txFileInputRef.current.value = '';
        } catch (error) {
           setStatus({
            type: 'error',
            message: 'Failed to process CSV.'
          });
        }
      }
    };
    reader.readAsText(file);
  };

  // CSV Bulk Import (Financial Records)
  const handleFinanceCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (text) {
        try {
          const { newState, count, errors } = importFinancialRecordsFromCSV(state, text);
          refreshState(newState);

          let msg = `Successfully imported ${count} financial records.`;
          if (errors.length > 0) {
             console.warn("Import Errors:", errors);
             msg += ` (Some rows failed)`;
          }

          if (count > 0) {
              setStatus({ type: 'success', message: msg });
          } else {
              setStatus({ type: 'error', message: "Failed to import records. Check format." });
          }

          if (financeFileInputRef.current) financeFileInputRef.current.value = '';
        } catch (error) {
           setStatus({
            type: 'error',
            message: 'Failed to process CSV.'
          });
        }
      }
    };
    reader.readAsText(file);
  };

  // Excel Database Export
  const handleExportDB = () => {
    try {
      exportDataToExcel(state);
      setStatus({ type: 'success', message: 'Database exported to Excel successfully.' });
    } catch (e) {
      setStatus({ type: 'error', message: 'Failed to export database.' });
    }
  };

  // Excel Database Import
  const handleImportDB = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!window.confirm("WARNING: This will OVERWRITE all current data with the data from the Excel file. Are you sure?")) {
      if (dbInputRef.current) dbInputRef.current.value = '';
      return;
    }

    try {
      const newState = await importDataFromExcel(file);
      refreshState(newState);
      setStatus({ type: 'success', message: 'Database restored from Excel successfully.' });
    } catch (e) {
      console.error(e);
      // Show the specific error message
      const msg = e instanceof Error ? e.message : 'Unknown error occurred during import.';
      setStatus({ type: 'error', message: msg });
    }
    if (dbInputRef.current) dbInputRef.current.value = '';
  };

  const handleClearFinance = () => {
     if (window.confirm("Are you sure you want to DELETE ALL FINANCE RECORDS?\n\nThis will clear the Accounts data (Income/Expense).")) {
        const newState = clearFinancialRecords(state);
        refreshState(newState);
        setStatus({ type: 'success', message: 'All finance records cleared.' });
    }
  };

  const handleCreateSnapshot = () => {
      createSystemSnapshot(state);
      const ts = getSnapshotTimestamp();
      if (ts) setSnapshotTime(new Date(ts).toLocaleString());
      setStatus({ type: 'success', message: 'System Restore Point created successfully.' });
  };

  const handleRestoreSnapshot = () => {
      const ts = getSnapshotTimestamp();
      if (!ts) {
          alert("No restore point found.");
          return;
      }

      const timeStr = new Date(ts).toLocaleString();
      if (window.confirm(`Are you sure you want to restore the system to the state from: ${timeStr}?\n\nCurrent data will be overwritten.`)) {
          const newState = restoreSystemSnapshot();
          if (newState) {
              refreshState(newState);
              setStatus({ type: 'success', message: `System restored to ${timeStr}.` });
          } else {
              setStatus({ type: 'error', message: 'Failed to load restore point.' });
          }
      }
  };

  return (
    <div className="p-4 space-y-8 pb-20">
      <h2 className="text-xl font-bold text-slate-800">Settings & Data</h2>

      {/* STATUS MESSAGE */}
      {status.type !== 'idle' && (
        <div className={`p-4 rounded-lg flex items-start animate-fade-in ${status.type === 'success' ? 'bg-green-50 text-green-800' : 'bg-red-50 text-red-800'}`}>
          {status.type === 'success' ? <CheckCircle size={20} className="mt-0.5 mr-2 shrink-0" /> : <AlertTriangle size={20} className="mt-0.5 mr-2 shrink-0" />}
          <p className="text-sm">{status.message}</p>
        </div>
      )}

      {/* APP INSTALLATION */}
      {deferredPrompt && (
        <section className="bg-blue-600 text-white rounded-xl p-5 shadow-lg shadow-blue-200">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="font-bold text-lg">Install App</h3>
              <p className="text-blue-100 text-sm">Add to home screen for fullscreen experience.</p>
            </div>
            <button 
              onClick={handleInstallClick}
              className="bg-white text-blue-600 px-4 py-2 rounded-lg font-bold text-sm shadow-md"
            >
              <div className="flex items-center space-x-2">
                <Smartphone size={16} />
                <span>Install</span>
              </div>
            </button>
          </div>
        </section>
      )}

      {/* SECTION: CLOUD DATABASE */}
      <section>
        <h3 className="text-sm font-bold text-slate-500 uppercase mb-3 flex items-center">
          <Cloud size={16} className="mr-2" />
          Cloud Database (Firebase)
        </h3>
        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">

           {/* Connection Header */}
           <div className="mb-4">
             <div className="flex items-center justify-between">
                <p className="text-sm text-slate-600">
                  Sync & Backup.
                </p>
                {cloudConnected ? (
                  <span className="text-xs bg-green-100 text-green-700 font-bold px-2 py-1 rounded flex items-center">
                     <Lock size={12} className="mr-1" />
                     Connected
                  </span>
                ) : (
                  <span className="text-xs bg-slate-100 text-slate-500 font-bold px-2 py-1 rounded">
                     Not Connected
                  </span>
                )}
             </div>
           </div>

           {/* Manual Configuration Form */}
           {(!cloudConnected || showConfigForm) && (
              <div className="mb-6 p-4 bg-slate-50 rounded-lg border border-slate-200 animate-in fade-in">
                  <h4 className="text-xs font-bold text-slate-700 uppercase mb-3">Configuration</h4>
                  <div className="space-y-3">
                      <div>
                          <label className="block text-xs font-medium text-slate-500 mb-1">API Key</label>
                          <input 
                            type="text" 
                            value={apiKey}
                            onChange={(e) => setApiKey(e.target.value)}
                            placeholder="AIzaSy..."
                            className="w-full text-sm p-2 border border-slate-300 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                          />
                      </div>
                      <div>
                          <label className="block text-xs font-medium text-slate-500 mb-1">Project ID</label>
                          <input 
                            type="text" 
                            value={projectId}
                            onChange={(e) => setProjectId(e.target.value)}
                            placeholder="my-project-id"
                            className="w-full text-sm p-2 border border-slate-300 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                          />
                      </div>
                      <div>
                          <label className="block text-xs font-medium text-slate-500 mb-1">Auth Domain (Optional)</label>
                          <input 
                            type="text" 
                            value={authDomain}
                            onChange={(e) => setAuthDomain(e.target.value)}
                            placeholder="my-project.firebaseapp.com"
                            className="w-full text-sm p-2 border border-slate-300 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                          />
                      </div>
                      <button 
                        onClick={handleConnectCloud}
                        className="w-full bg-slate-800 text-white font-bold text-sm py-2 rounded hover:bg-slate-900 transition-colors"
                      >
                        Connect
                      </button>
                  </div>
              </div>
           )}

           {/* Actions if Connected */}
           {cloudConnected && !showConfigForm && (
               <div className="space-y-3">
                   <div className="grid grid-cols-2 gap-3">
                        <button 
                            onClick={handleCloudSync}
                            className="flex items-center justify-center space-x-2 bg-blue-600 text-white py-3 rounded-lg font-bold text-sm hover:bg-blue-700 shadow-lg shadow-blue-200 transition-colors"
                        >
                            <RefreshCw size={18} />
                            <span>Sync / Download</span>
                        </button>

                        <button 
                            onClick={() => {
                            if(window.confirm("Force Backup: This will overwrite cloud data with current local data. Continue?")) {
                                handleCloudUpload();
                            }
                            }}
                            className="flex items-center justify-center space-x-2 bg-white border border-slate-200 text-slate-700 py-3 rounded-lg font-bold text-sm hover:bg-slate-50 transition-colors"
                        >
                            <ArrowUpCircle size={18} />
                            <span>Force Backup</span>
                        </button>
                   </div>

                   <button 
                        onClick={handleDisconnectCloud}
                        className="w-full text-xs text-red-500 hover:text-red-700 underline text-center"
                   >
                       Disconnect / Edit Configuration
                   </button>
               </div>
           )}

        </div>
      </section>

      {/* SECTION: SYSTEM RESTORE POINT */}
      <section>
        <h3 className="text-sm font-bold text-slate-500 uppercase mb-3 flex items-center">
          <History size={16} className="mr-2" />
          System Restore Point
        </h3>
        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
            <div className="flex justify-between items-center mb-4">
                <div>
                   <p className="text-sm text-slate-600">Save current state safely.</p>
                   {snapshotTime ? (
                       <p className="text-xs text-green-600 font-medium mt-1">Last Saved: {snapshotTime}</p>
                   ) : (
                       <p className="text-xs text-slate-400 mt-1 italic">No restore point saved.</p>
                   )}
                </div>
            </div>
            <div className="grid grid-cols-2 gap-3">
                 <button 
                    onClick={handleCreateSnapshot}
                    className="flex items-center justify-center space-x-2 bg-slate-800 text-white py-3 rounded-lg font-bold text-sm hover:bg-slate-900"
                 >
                    <Save size={16} />
                    <span>Create Point</span>
                 </button>
                 <button 
                    onClick={handleRestoreSnapshot}
                    disabled={!snapshotTime}
                    className="flex items-center justify-center space-x-2 bg-slate-100 text-slate-700 py-3 rounded-lg font-bold text-sm hover:bg-slate-200 disabled:opacity-50 disabled:cursor-not-allowed"
                 >
                    <RotateCcw size={16} />
                    <span>Restore Point</span>
                 </button>
            </div>
        </div>
      </section>

      {/* SECTION 1: DATABASE MANAGEMENT (EXCEL) */}
      <section>
        <h3 className="text-sm font-bold text-slate-500 uppercase mb-3 flex items-center">
          <Database size={16} className="mr-2" />
          Database Management (Excel)
        </h3>
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden mb-6">
          <div className="p-5 border-b border-slate-100">
            <p className="text-sm text-slate-600">
              Use this to backup your entire system. <br/>
              <span className="text-xs text-slate-400 italic">Note: You can only restore "yesterday's" data if you have an exported file from yesterday.</span>
            </p>
          </div>

          <div className="grid grid-cols-2 divide-x divide-slate-100">
            {/* Export Button */}
            <button 
              onClick={handleExportDB}
              className="p-4 flex flex-col items-center justify-center hover:bg-slate-50 transition-colors active:bg-slate-100"
            >
              <div className="bg-green-100 text-green-600 p-3 rounded-full mb-2">
                <Save size={24} />
              </div>
              <span className="font-bold text-slate-700">Backup DB</span>
              <span className="text-xs text-slate-400 mt-1">Export to .xlsx</span>
            </button>

            {/* Import Button */}
            <div className="relative p-4 flex flex-col items-center justify-center hover:bg-slate-50 transition-colors active:bg-slate-100 cursor-pointer">
              <input
                ref={dbInputRef}
                type="file"
                accept=".xlsx, .xls"
                onChange={handleImportDB}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
              />
              <div className="bg-blue-100 text-blue-600 p-3 rounded-full mb-2">
                <Upload size={24} />
              </div>
              <span className="font-bold text-slate-700">Restore DB</span>
              <span className="text-xs text-slate-400 mt-1">Import from .xlsx</span>
            </div>
          </div>
        </div>
      </section>

      {/* SECTION: ACCOUNTS IMPORT (NEW) */}
      <section>
        <h3 className="text-sm font-bold text-slate-500 uppercase mb-3 flex items-center">
          <Wallet size={16} className="mr-2" />
          Import Accounts Data (CSV)
        </h3>

        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm mb-6">
          <p className="text-sm text-slate-500 mb-4 leading-relaxed">
            Bulk upload income and expenses for the Finance module.
            <br/>
            <span className="text-xs italic">Supports columns: Date, Category, Description, Income, Expenses</span>
          </p>

          <div className="space-y-3">
             <div className="grid grid-cols-2 gap-2">
                 <button 
                  onClick={downloadFinanceSampleCsv}
                  className="flex items-center justify-center space-x-2 w-full py-3 border border-slate-200 rounded-xl text-slate-600 font-medium hover:bg-slate-50 transition-colors text-xs"
                >
                  <Download size={14} />
                  <span>Template</span>
                </button>
                 <button 
                  onClick={handleClearFinance}
                  className="flex items-center justify-center space-x-2 w-full py-3 border border-red-200 bg-red-50 rounded-xl text-red-600 font-medium hover:bg-red-100 transition-colors text-xs"
                >
                  <Trash2 size={14} />
                  <span>Clear Data</span>
                </button>
             </div>

            <div className="relative">
              <input
                ref={financeFileInputRef}
                type="file"
                accept=".csv"
                onChange={handleFinanceCsvUpload}
                className="hidden"
                id="finance-csv-upload"
              />
              <label 
                htmlFor="finance-csv-upload"
                className="flex items-center justify-center space-x-2 w-full py-3 bg-indigo-600 text-white rounded-xl font-medium cursor-pointer hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-200"
              >
                <Upload size={18} />
                <span>Upload Accounts CSV</span>
              </label>
            </div>
          </div>
        </div>
      </section>

      {/* SECTION 3: BULK IMPORT TRANSACTIONS */}
      <section>
        <h3 className="text-sm font-bold text-slate-500 uppercase mb-3 flex items-center">
          <Receipt size={16} className="mr-2" />
          Import Transactions (CSV)
        </h3>

        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm mb-6">
          <p className="text-sm text-slate-500 mb-4 leading-relaxed">
            Bulk upload historical payments. Flats listed in the CSV will be marked as PAID.
          </p>

          <div className="space-y-3">
             <button 
              onClick={downloadTransactionSampleCsv}
              className="flex items-center justify-center space-x-2 w-full py-3 border border-slate-200 rounded-xl text-slate-600 font-medium hover:bg-slate-50 transition-colors text-sm"
            >
              <Download size={16} />
              <span>Download CSV Template</span>
            </button>

            <div className="relative">
              <input
                ref={txFileInputRef}
                type="file"
                accept=".csv"
                onChange={handleTxCsvUpload}
                className="hidden"
                id="tx-csv-upload"
              />
              <label 
                htmlFor="tx-csv-upload"
                className="flex items-center justify-center space-x-2 w-full py-3 bg-blue-600 text-white rounded-xl font-medium cursor-pointer hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200"
              >
                <Upload size={18} />
                <span>Upload Transactions</span>
              </label>
            </div>
          </div>
        </div>
      </section>

      {/* SECTION 4: BULK UPDATE DETAILS */}
      <section>
        <h3 className="text-sm font-bold text-slate-500 uppercase mb-3 flex items-center">
          <FileText size={16} className="mr-2" />
          Bulk Update Details (CSV)
        </h3>

        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm mb-6">
          <p className="text-sm text-slate-500 mb-4 leading-relaxed">
            Update owner names and mobile numbers only. Does not affect payment status.
          </p>

          <div className="space-y-3">
             <button 
              onClick={downloadSampleCsv}
              className="flex items-center justify-center space-x-2 w-full py-3 border border-slate-200 rounded-xl text-slate-600 font-medium hover:bg-slate-50 transition-colors text-sm"
            >
              <Download size={16} />
              <span>Download CSV Template</span>
            </button>

            <div className="relative">
              <input
                ref={fileInputRef}
                type="file"
                accept=".csv"
                onChange={handleCsvUpload}
                className="hidden"
                id="csv-upload"
              />
              <label 
                htmlFor="csv-upload"
                className="flex items-center justify-center space-x-2 w-full py-3 bg-slate-800 text-white rounded-xl font-medium cursor-pointer hover:bg-slate-900 transition-colors shadow-lg shadow-slate-200"
              >
                <Upload size={18} />
                <span>Upload CSV Update</span>
              </label>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
};

export default Settings;

import React, { useRef, useState, useEffect } from 'react';
import { AppState } from '../types';
import { updateFlatsFromCSV, exportDataToExcel, importDataFromExcel, importTransactionsFromCSV, createSystemSnapshot, restoreSystemSnapshot, getSnapshotTimestamp, syncFromCloud, importFinancialRecordsFromCSV, clearFinancialRecords, uploadCurrentDataToCloud, saveCloudConfig, getCloudConfig } from '../services/storageService';
import { downloadSampleCsv, downloadTransactionSampleCsv, downloadFinanceSampleCsv } from '../utils/helpers';
import { Upload, Download, FileText, CheckCircle, AlertTriangle, Database, Save, Receipt, RefreshCw, RotateCcw, History, Smartphone, Cloud, Wallet, Trash2, Lock, ArrowUpCircle, X, ChevronDown, ChevronUp } from 'lucide-react';
import { initFirebase } from '../services/firebaseService';

interface SettingsProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
}

const Settings: React.FC<SettingsProps> = ({ state, refreshState }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const dbInputRef = useRef<HTMLInputElement>(null);
  const txFileInputRef = useRef<HTMLInputElement>(null);
  const financeFileInputRef = useRef<HTMLInputElement>(null);

  const [status, setStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });
  const [snapshotTime, setSnapshotTime] = useState<string | null>(null);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  const [cloudConnected, setCloudConnected] = useState(false);
  const [showConfigForm, setShowConfigForm] = useState(false);

  // Cloud Config State
  const [apiKey, setApiKey] = useState('');
  const [projectId, setProjectId] = useState('');
  const [authDomain, setAuthDomain] = useState('');

  useEffect(() => {
    // Load snapshot time
    const ts = getSnapshotTimestamp();
    if (ts) {
        setSnapshotTime(new Date(ts).toLocaleString());
    }

    // Check saved config
    const savedConfig = getCloudConfig();
    if (savedConfig) {
        setApiKey(savedConfig.apiKey);
        setProjectId(savedConfig.projectId);
        setAuthDomain(savedConfig.authDomain);
        if (initFirebase(savedConfig)) {
            setCloudConnected(true);
        } else {
            // Config exists but failed to init
            setCloudConnected(false);
            setShowConfigForm(true);
        }
    } else {
        setShowConfigForm(true);
    }

    // Listen for PWA install prompt
    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  const handleInstallClick = () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      deferredPrompt.userChoice.then((choiceResult: any) => {
        if (choiceResult.outcome === 'accepted') {
          console.log('User accepted the install prompt');
        }
        setDeferredPrompt(null);
      });
    }
  };

  const handleConnectCloud = () => {
    if (!apiKey || !projectId) {
        setStatus({ type: 'error', message: 'API Key and Project ID are required.' });
        return;
    }

    const config = {
        apiKey,
        projectId,
        authDomain: authDomain || `${projectId}.firebaseapp.com`
    };

    if (initFirebase(config)) {
        saveCloudConfig(config);
        setCloudConnected(true);
        setShowConfigForm(false);
        setStatus({ type: 'success', message: 'Connected to Firebase successfully!' });
    } else {
        setStatus({ type: 'error', message: 'Connection failed. Check your credentials.' });
    }
  };

  const handleDisconnectCloud = () => {
      localStorage.removeItem('firebase_config');
      setCloudConnected(false);
      setShowConfigForm(true);
      setStatus({ type: 'idle', message: 'Disconnected. Please reload if needed.' });
      // Reloading is often safest to clear Firebase instance state
      if(window.confirm("Disconnecting requires a reload. Reload now?")) {
          window.location.reload();
      }
  };

  const handleCloudSync = async () => {
    setStatus({ type: 'idle', message: 'Connecting to Cloud...' });
    try {
      const cloudData = await syncFromCloud();
      if (cloudData) {
        if(window.confirm("Found data on Cloud. This will OVERWRITE your local data. Proceed?")) {
            refreshState(cloudData);
            setStatus({ type: 'success', message: 'Successfully restored data from Cloud!' });
        } else {
            setStatus({ type: 'idle', message: 'Sync cancelled.' });
        }
      } else {
        // If cloud is empty, suggest uploading
        if (window.confirm("Cloud database is empty. Do you want to UPLOAD your current local data to seed the cloud?")) {
            handleCloudUpload();
        } else {
            setStatus({ type: 'error', message: 'No data found on Cloud.' });
        }
      }
    } catch (e) {
       setStatus({ type: 'error', message: 'Failed to connect to Cloud.' });
    }
  };

  const handleCloudUpload = async () => {
    try {
        const success = await uploadCurrentDataToCloud(state);
        if (success) {
            setStatus({ type: 'success', message: 'Data uploaded to Cloud successfully! Auto-sync is now active.' });
        } else {
            setStatus({ type: 'error', message: 'Failed to upload. Check internet connection.' });
        }
    } catch (e) {
        setStatus({ type: 'error', message: 'Error uploading to cloud.' });
    }
  };

  // CSV Bulk Update (Flats)
  const handleCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (text) {
        try {
          const { newState, updatedCount } = updateFlatsFromCSV(state, text);
          refreshState(newState);
          setStatus({
            type: 'success',
            message: `Successfully updated details for ${updatedCount} flats!`
          });
          if (fileInputRef.current) fileInputRef.current.value = '';
        } catch (error) {
           setStatus({
            type: 'error',
            message: 'Failed to process CSV.'
          });
        }
      }
    };
    reader.readAsText(file);
  };

  // CSV Bulk Import (Transactions)
  const handleTxCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (text) {
        try {
          const { newState, count, errors } = importTransactionsFromCSV(state, text);
          refreshState(newState);

          let msg = `Successfully imported ${count} transactions.`;
          if (errors.length > 0) {
            msg += ` ${errors.length} rows failed. Check console.`;
            console.warn("Import Errors:", errors);
          }

          if (count > 0) {
              setStatus({ type: 'success', message: msg });
           } else if (errors.length > 0) {
              setStatus({ type: 'error', message: "Failed to import any transactions. Check file format." });
           } else {
              setStatus({ type: 'idle', message: "" });
           }

          if (txFileInputRef.current) txFileInputRef.current.value = '';
        } catch (error) {
           setStatus({
            type: 'error',
            message: 'Failed to process CSV.'
          });
        }
      }
    };
    reader.readAsText(file);
  };

  // CSV Bulk Import (Financial Records)
  const handleFinanceCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (text) {
        try {
          const { newState, count, errors } = importFinancialRecordsFromCSV(state, text);
          refreshState(newState);

          let msg = `Successfully imported ${count} financial records.`;
          if (errors.length > 0) {
             console.warn("Import Errors:", errors);
             msg += ` (Some rows failed)`;
          }

          if (count > 0) {
              setStatus({ type: 'success', message: msg });
          } else {
              setStatus({ type: 'error', message: "Failed to import records. Check format." });
          }

          if (financeFileInputRef.current) financeFileInputRef.current.value = '';
        } catch (error) {
           setStatus({
            type: 'error',
            message: 'Failed to process CSV.'
          });
        }
      }
    };
    reader.readAsText(file);
  };

  // Excel Database Export
  const handleExportDB = () => {
    try {
      exportDataToExcel(state);
      setStatus({ type: 'success', message: 'Database exported to Excel successfully.' });
    } catch (e) {
      setStatus({ type: 'error', message: 'Failed to export database.' });
    }
  };

  // Excel Database Import
  const handleImportDB = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!window.confirm("WARNING: This will OVERWRITE all current data with the data from the Excel file. Are you sure?")) {
      if (dbInputRef.current) dbInputRef.current.value = '';
      return;
    }

    try {
      const newState = await importDataFromExcel(file);
      refreshState(newState);
      setStatus({ type: 'success', message: 'Database restored from Excel successfully.' });
    } catch (e) {
      console.error(e);
      // Show the specific error message
      const msg = e instanceof Error ? e.message : 'Unknown error occurred during import.';
      setStatus({ type: 'error', message: msg });
    }
    if (dbInputRef.current) dbInputRef.current.value = '';
  };

  const handleClearFinance = () => {
     if (window.confirm("Are you sure you want to DELETE ALL FINANCE RECORDS?\n\nThis will clear the Accounts data (Income/Expense).")) {
        const newState = clearFinancialRecords(state);
        refreshState(newState);
        setStatus({ type: 'success', message: 'All finance records cleared.' });
    }
  };

  const handleCreateSnapshot = () => {
      createSystemSnapshot(state);
      const ts = getSnapshotTimestamp();
      if (ts) setSnapshotTime(new Date(ts).toLocaleString());
      setStatus({ type: 'success', message: 'System Restore Point created successfully.' });
  };

  const handleRestoreSnapshot = () => {
      const ts = getSnapshotTimestamp();
      if (!ts) {
          alert("No restore point found.");
          return;
      }

      const timeStr = new Date(ts).toLocaleString();
      if (window.confirm(`Are you sure you want to restore the system to the state from: ${timeStr}?\n\nCurrent data will be overwritten.`)) {
          const newState = restoreSystemSnapshot();
          if (newState) {
              refreshState(newState);
              setStatus({ type: 'success', message: `System restored to ${timeStr}.` });
          } else {
              setStatus({ type: 'error', message: 'Failed to load restore point.' });
          }
      }
  };

  return (
    <div className="p-4 space-y-8 pb-20">
      <h2 className="text-xl font-bold text-slate-800">Settings & Data</h2>

      {/* STATUS MESSAGE */}
      {status.type !== 'idle' && (
        <div className={`p-4 rounded-lg flex items-start animate-fade-in ${status.type === 'success' ? 'bg-green-50 text-green-800' : 'bg-red-50 text-red-800'}`}>
          {status.type === 'success' ? <CheckCircle size={20} className="mt-0.5 mr-2 shrink-0" /> : <AlertTriangle size={20} className="mt-0.5 mr-2 shrink-0" />}
          <p className="text-sm">{status.message}</p>
        </div>
      )}

      {/* APP INSTALLATION */}
      {deferredPrompt && (
        <section className="bg-blue-600 text-white rounded-xl p-5 shadow-lg shadow-blue-200">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="font-bold text-lg">Install App</h3>
              <p className="text-blue-100 text-sm">Add to home screen for fullscreen experience.</p>
            </div>
            <button 
              onClick={handleInstallClick}
              className="bg-white text-blue-600 px-4 py-2 rounded-lg font-bold text-sm shadow-md"
            >
              <div className="flex items-center space-x-2">
                <Smartphone size={16} />
                <span>Install</span>
              </div>
            </button>
          </div>
        </section>
      )}

      {/* SECTION: CLOUD DATABASE */}
      <section>
        <h3 className="text-sm font-bold text-slate-500 uppercase mb-3 flex items-center">
          <Cloud size={16} className="mr-2" />
          Cloud Database (Firebase)
        </h3>
        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">

           {/* Connection Header */}
           <div className="mb-4">
             <div className="flex items-center justify-between">
                <p className="text-sm text-slate-600">
                  Sync & Backup.
                </p>
                {cloudConnected ? (
                  <span className="text-xs bg-green-100 text-green-700 font-bold px-2 py-1 rounded flex items-center">
                     <Lock size={12} className="mr-1" />
                     Connected
                  </span>
                ) : (
                  <span className="text-xs bg-slate-100 text-slate-500 font-bold px-2 py-1 rounded">
                     Not Connected
                  </span>
                )}
             </div>
           </div>

           {/* Manual Configuration Form */}
           {(!cloudConnected || showConfigForm) && (
              <div className="mb-6 p-4 bg-slate-50 rounded-lg border border-slate-200 animate-in fade-in">
                  <h4 className="text-xs font-bold text-slate-700 uppercase mb-3">Configuration</h4>
                  <div className="space-y-3">
                      <div>
                          <label className="block text-xs font-medium text-slate-500 mb-1">API Key</label>
                          <input 
                            type="text" 
                            value={apiKey}
                            onChange={(e) => setApiKey(e.target.value)}
                            placeholder="AIzaSy..."
                            className="w-full text-sm p-2 border border-slate-300 rounded focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                          />
                      </div>
                      <div>
                          <label className="block text-xs font-medium text-slate-500 mb-1">Project ID</label>
                          <input 
                            type="text" 
                            value={projectId}
                            onChange={(e) => setProjectId(e.target.value)}
                            placeholder="my-project-id"
                            className="w-full text-sm p-2 border border-slate-300 rounded focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                          />
                      </div>
                      <div>
                          <label className="block text-xs font-medium text-slate-500 mb-1">Auth Domain (Optional)</label>
                          <input 
                            type="text" 
                            value={authDomain}
                            onChange={(e) => setAuthDomain(e.target.value)}
                            placeholder="my-project.firebaseapp.com"
                            className="w-full text-sm p-2 border border-slate-300 rounded focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                          />
                      </div>
                      <button 
                        onClick={handleConnectCloud}
                        className="w-full bg-slate-800 text-white font-bold text-sm py-2 rounded hover:bg-slate-900 transition-colors"
                      >
                        Connect
                      </button>
                  </div>
              </div>
           )}

           {/* Actions if Connected */}
           {cloudConnected && !showConfigForm && (
               <div className="space-y-3">
                   <div className="grid grid-cols-2 gap-3">
                        <button 
                            onClick={handleCloudSync}
                            className="flex items-center justify-center space-x-2 bg-blue-600 text-white py-3 rounded-lg font-bold text-sm hover:bg-blue-700 shadow-lg shadow-blue-200 transition-colors"
                        >
                            <RefreshCw size={18} />
                            <span>Sync / Download</span>
                        </button>

                        <button 
                            onClick={() => {
                            if(window.confirm("Force Backup: This will overwrite cloud data with current local data. Continue?")) {
                                handleCloudUpload();
                            }
                            }}
                            className="flex items-center justify-center space-x-2 bg-white border border-slate-200 text-slate-700 py-3 rounded-lg font-bold text-sm hover:bg-slate-50 transition-colors"
                        >
                            <ArrowUpCircle size={18} />
                            <span>Force Backup</span>
                        </button>
                   </div>

                   <button 
                        onClick={handleDisconnectCloud}
                        className="w-full text-xs text-red-500 hover:text-red-700 underline text-center"
                   >
                       Disconnect / Edit Configuration
                   </button>
               </div>
           )}

        </div>
      </section>

      {/* SECTION: SYSTEM RESTORE POINT */}
      <section>
        <h3 className="text-sm font-bold text-slate-500 uppercase mb-3 flex items-center">
          <History size={16} className="mr-2" />
          System Restore Point
        </h3>
        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
            <div className="flex justify-between items-center mb-4">
                <div>
                   <p className="text-sm text-slate-600">Save current state safely.</p>
                   {snapshotTime ? (
                       <p className="text-xs text-green-600 font-medium mt-1">Last Saved: {snapshotTime}</p>
                   ) : (
                       <p className="text-xs text-slate-400 mt-1 italic">No restore point saved.</p>
                   )}
                </div>
            </div>
            <div className="grid grid-cols-2 gap-3">
                 <button 
                    onClick={handleCreateSnapshot}
                    className="flex items-center justify-center space-x-2 bg-slate-800 text-white py-3 rounded-lg font-bold text-sm hover:bg-slate-900"
                 >
                    <Save size={16} />
                    <span>Create Point</span>
                 </button>
                 <button 
                    onClick={handleRestoreSnapshot}
                    disabled={!snapshotTime}
                    className="flex items-center justify-center space-x-2 bg-slate-100 text-slate-700 py-3 rounded-lg font-bold text-sm hover:bg-slate-200 disabled:opacity-50 disabled:cursor-not-allowed"
                 >
                    <RotateCcw size={16} />
                    <span>Restore Point</span>
                 </button>
            </div>
        </div>
      </section>

      {/* SECTION 1: DATABASE MANAGEMENT (EXCEL) */}
      <section>
        <h3 className="text-sm font-bold text-slate-500 uppercase mb-3 flex items-center">
          <Database size={16} className="mr-2" />
          Database Management (Excel)
        </h3>
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden mb-6">
          <div className="p-5 border-b border-slate-100">
            <p className="text-sm text-slate-600">
              Use this to backup your entire system. <br/>
              <span className="text-xs text-slate-400 italic">Note: You can only restore "yesterday's" data if you have an exported file from yesterday.</span>
            </p>
          </div>

          <div className="grid grid-cols-2 divide-x divide-slate-100">
            {/* Export Button */}
            <button 
              onClick={handleExportDB}
              className="p-4 flex flex-col items-center justify-center hover:bg-slate-50 transition-colors active:bg-slate-100"
            >
              <div className="bg-green-100 text-green-600 p-3 rounded-full mb-2">
                <Save size={24} />
