            {/* Import Button */}
            <div className="relative p-4 flex flex-col items-center justify-center hover:bg-slate-50 transition-colors active:bg-slate-100 cursor-pointer">
              <input
                ref={dbInputRef}
                type="file"
                accept=".xlsx, .xls"
                onChange={handleImportDB}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
              />
              <div className="bg-blue-100 text-blue-600 p-3 rounded-full mb-2">
                <Upload size={24} />
              </div>
              <span className="font-bold text-slate-700">Restore DB</span>
              <span className="text-xs text-slate-400 mt-1">Import from .xlsx</span>
            </div>
          </div>
        </div>
      </section>

      {/* SECTION: ACCOUNTS IMPORT (NEW) */}
      <section>
        <h3 className="text-sm font-bold text-slate-500 uppercase mb-3 flex items-center">
          <Wallet size={16} className="mr-2" />
          Import Accounts Data (CSV)
        </h3>

        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm mb-6">
          <p className="text-sm text-slate-500 mb-4 leading-relaxed">
            Bulk upload income and expenses for the Finance module.
            <br/>
            <span className="text-xs italic">Supports columns: Date, Category, Description, Income, Expenses</span>
          </p>

          <div className="space-y-3">
             <div className="grid grid-cols-2 gap-2">
                 <button 
                  onClick={downloadFinanceSampleCsv}
                  className="flex items-center justify-center space-x-2 w-full py-3 border border-slate-200 rounded-xl text-slate-600 font-medium hover:bg-slate-50 transition-colors text-xs"
                >
                  <Download size={14} />
                  <span>Template</span>
                </button>
                 <button 
                  onClick={handleClearFinance}
                  className="flex items-center justify-center space-x-2 w-full py-3 border border-red-200 bg-red-50 rounded-xl text-red-600 font-medium hover:bg-red-100 transition-colors text-xs"
                >
                  <Trash2 size={14} />
                  <span>Clear Data</span>
                </button>
             </div>

            <div className="relative">
              <input
                ref={financeFileInputRef}
                type="file"
                accept=".csv"
                onChange={handleFinanceCsvUpload}
                className="hidden"
                id="finance-csv-upload"
              />
              <label 
                htmlFor="finance-csv-upload"
                className="flex items-center justify-center space-x-2 w-full py-3 bg-indigo-600 text-white rounded-xl font-medium cursor-pointer hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-200"
              >
                <Upload size={18} />
                <span>Upload Accounts CSV</span>
              </label>
            </div>
          </div>
        </div>
