      {/* SECTION 3: BULK IMPORT TRANSACTIONS */}
      <section>
        <h3 className="text-sm font-bold text-slate-500 uppercase mb-3 flex items-center">
          <Receipt size={16} className="mr-2" />
          Import Transactions (CSV)
        </h3>

        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm mb-6">
          <p className="text-sm text-slate-500 mb-4 leading-relaxed">
            Bulk upload historical payments. Flats listed in the CSV will be marked as PAID.
          </p>

          <div className="space-y-3">
             <button 
              onClick={downloadTransactionSampleCsv}
              className="flex items-center justify-center space-x-2 w-full py-3 border border-slate-200 rounded-xl text-slate-600 font-medium hover:bg-slate-50 transition-colors text-sm"
            >
              <Download size={16} />
              <span>Download CSV Template</span>
            </button>

            <div className="relative">
              <input
                ref={txFileInputRef}
                type="file"
                accept=".csv"
                onChange={handleTxCsvUpload}
                className="hidden"
                id="tx-csv-upload"
              />
              <label 
                htmlFor="tx-csv-upload"
                className="flex items-center justify-center space-x-2 w-full py-3 bg-blue-600 text-white rounded-xl font-medium cursor-pointer hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200"
              >
                <Upload size={18} />
                <span>Upload Transactions</span>
              </label>
            </div>
          </div>
        </div>
      </section>

      {/* SECTION 4: BULK UPDATE DETAILS */}
      <section>
        <h3 className="text-sm font-bold text-slate-500 uppercase mb-3 flex items-center">
          <FileText size={16} className="mr-2" />
          Bulk Update Details (CSV)
        </h3>

        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm mb-6">
          <p className="text-sm text-slate-500 mb-4 leading-relaxed">
            Update owner names and mobile numbers only. Does not affect payment status.
          </p>

          <div className="space-y-3">
             <button 
              onClick={downloadSampleCsv}
              className="flex items-center justify-center space-x-2 w-full py-3 border border-slate-200 rounded-xl text-slate-600 font-medium hover:bg-slate-50 transition-colors text-sm"
            >
              <Download size={16} />
              <span>Download CSV Template</span>
            </button>

            <div className="relative">
              <input
                ref={fileInputRef}
                type="file"
                accept=".csv"
                onChange={handleCsvUpload}
                className="hidden"
                id="csv-upload"
              />
              <label 
                htmlFor="csv-upload"
                className="flex items-center justify-center space-x-2 w-full py-3 bg-slate-800 text-white rounded-xl font-medium cursor-pointer hover:bg-slate-900 transition-colors shadow-lg shadow-slate-200"
              >
                <Upload size={18} />
                <span>Upload CSV Update</span>
              </label>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
};

export default Settings;

import React, { useMemo, useState } from 'react';
import { AppState, PaymentStatus, Transaction } from '../types';
import { formatCurrency, formatDate, generateWhatsAppLink, getTodayDateString, generateReminderLink, downloadPDF } from '../utils/helpers';
import { Clock, AlertCircle, Share2, Edit2, Calendar, Download, MessageCircle, FileText, CheckCircle2 } from 'lucide-react';
import { MAINTENANCE_AMOUNT } from '../constants';

interface ReportsProps {
  state: AppState;
  view: 'REPORTS' | 'UNPAID_LIST';
  refreshState?: (newState: AppState) => void;
  onEditTransaction?: (tx: Transaction) => void;
}

const Reports: React.FC<ReportsProps> = ({ state, view, refreshState, onEditTransaction }) => {
  const [activeTab, setActiveTab] = useState<'DAILY' | 'UNPAID'>(view === 'UNPAID_LIST' ? 'UNPAID' : 'DAILY');
  const [selectedDate, setSelectedDate] = useState<string>(getTodayDateString());

  const dailyReport = useMemo(() => {
    if (!selectedDate) return [];
    return state.transactions.filter(t => t.date.startsWith(selectedDate));
  }, [state.transactions, selectedDate]);

  const dailyTotal = dailyReport.reduce((acc, curr) => acc + curr.amount, 0);

  const unpaidFlats = useMemo(() => {
    return state.flats.filter(f => f.status === PaymentStatus.UNPAID);
  }, [state.flats]);

  const handleDownload = () => {
    const fileName = activeTab === 'DAILY' ? `Daily_Report_${selectedDate}.pdf` : `Unpaid_List_${getTodayDateString()}.pdf`;
    downloadPDF('printable-section', fileName);
  };

  const renderDailyReport = () => (
    <div className="space-y-6">
       <div className="flex justify-between items-center no-print">
          <div>
            <h2 className="text-lg font-bold text-slate-800">Daily Collection</h2>
            <p className="text-xs text-slate-500">{formatDate(selectedDate)}</p>
          </div>
          <button onClick={handleDownload} className="flex items-center space-x-2 text-white bg-blue-600 px-3 py-2 rounded-lg text-xs font-bold hover:bg-blue-700 shadow-md transition-colors">
            <Download size={14} />
            <span>PDF</span>
          </button>
        </div>

        <div className="hidden print:block text-center mb-6 border-b border-black pb-4">
            <h1 className="text-2xl font-bold text-black mb-1">CONTINENTAL HEIGHTS B WING</h1>
            <h2 className="text-xl font-semibold text-black uppercase">Daily Collection - {formatDate(selectedDate)}</h2>
        </div>

        <div className="bg-white p-4 rounded-xl border border-slate-200 flex justify-between items-center shadow-sm no-print">
          <div>
             <label className="text-[10px] text-slate-500 uppercase font-bold mb-1 block">Select Date</label>
             <input
                type="date"
                value={selectedDate}
                onChange={(e) => setSelectedDate(e.target.value)}
                className="font-bold text-slate-800 bg-white border border-slate-200 rounded px-2 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
             />
          </div>
          <div className="text-right">
             <p className="text-[10px] text-slate-500 uppercase font-bold mb-1">Total</p>
             <p className="text-lg font-bold text-green-600">{formatCurrency(dailyTotal)}</p>
          </div>
        </div>

        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden print:border-black print:shadow-none">
             <div className="flex items-center bg-slate-900 p-3 border-b border-slate-200 text-xs font-bold text-white uppercase tracking-wider print:bg-black print:text-white">
                <div className="w-12 shrink-0">Rcpt</div>
                <div className="w-16 shrink-0">Flat</div>
                <div className="flex-1 min-w-0 px-2">Owner</div>
                <div className="w-20 shrink-0 text-right">Status</div>
                <div className="w-10 shrink-0 text-center no-print"></div>
             </div>

             <div className="divide-y divide-slate-100 print:divide-black">
                {dailyReport.length === 0 ? (
                   <div className="p-8 text-center text-slate-400 text-sm">No transactions found.</div>
                ) : dailyReport.map((t) => (
                  <div key={t.receiptNo} className="flex items-center p-3 text-xs hover:bg-slate-50 transition-colors">
                    <div className="w-12 shrink-0 font-mono text-slate-500 print:text-black">#{t.receiptNo}</div>
                    <div className="w-16 shrink-0 font-bold text-slate-800 print:text-black">{t.flatNumber}</div>
                    <div className="flex-1 min-w-0 px-2 truncate text-slate-600 print:text-black font-medium">{t.ownerName}</div>
                    <div className="w-20 shrink-0 text-right">
                        <div className="font-black text-emerald-600 uppercase tracking-tighter text-[14px] print:text-black">PAID</div>
                    </div>
                    <div className="w-10 shrink-0 flex justify-end space-x-1 no-print">
                        <a href={generateWhatsAppLink(t.mobile, t.receiptNo, t.ownerName, t.flatNumber, t.amount, formatDate(t.date))} target="_blank" rel="noreferrer" className="text-green-600 p-1.5 hover:bg-green-100 rounded transition-colors">
                            <Share2 size={14} />
                        </a>
                    </div>
                  </div>
                ))}
             </div>
        </div>
    </div>
  );

  const renderUnpaidList = () => (
    <div className="space-y-6">
       <div className="flex justify-between items-center no-print">
        <div className="flex items-center space-x-2">
            <h2 className="text-lg font-bold text-slate-800">Pending Payments</h2>
            <span className="bg-red-100 text-red-700 px-2 py-0.5 rounded-full text-[10px] font-bold">{unpaidFlats.length}</span>
        </div>
        <button onClick={handleDownload} className="flex items-center space-x-2 text-white bg-blue-600 px-3 py-2 rounded-lg text-xs font-bold hover:bg-blue-700 shadow-md transition-colors">
            <Download size={14} />
