                         onChange={(e) => setAmount(Number(e.target.value))}
                         className="w-full px-3 py-3 bg-white border border-slate-300 rounded-lg text-slate-800 focus:ring-2 focus:ring-blue-500 outline-none"
                       />
                    </div>
                </div>

                <button
                  type="submit"
                  className="w-full bg-blue-600 text-white font-bold py-4 rounded-xl shadow-lg shadow-blue-200 active:scale-[0.98] transition-transform mt-4"
                >
                  Confirm Booking
                </button>
             </form>
          </div>
        )}
      </div>
    );
  }

  // --- RENDER DASHBOARD (LIST) ---
  return (
    <div className="flex flex-col h-full bg-slate-50">
       <div className="p-4 bg-white border-b border-slate-200 sticky top-0 z-10 flex items-center justify-between shadow-sm">
           <h2 className="text-xl font-bold text-slate-800">Hall Bookings</h2>
           <button 
             onClick={() => { setMode('NEW_BOOKING'); resetForm(); }}
             className="bg-blue-600 text-white px-3 py-2 rounded-lg text-xs font-bold flex items-center shadow-md hover:bg-blue-700 transition-colors"
           >
             <Plus size={16} className="mr-1" />
             New Booking
           </button>
       </div>

       <div className="flex-1 overflow-y-auto p-4 pb-24 space-y-3">
          {sortedBookings.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-64 text-slate-400">
               <Calendar size={48} className="mb-3 opacity-20" />
               <p>No bookings yet.</p>
            </div>
          ) : (
            sortedBookings.map(booking => {
              const isPast = new Date(booking.bookingDate) < new Date(new Date().toISOString().split('T')[0]);

              return (
                <div key={booking.id} className={`bg-white p-4 rounded-xl border ${isPast ? 'border-slate-100 opacity-70' : 'border-slate-200'} shadow-sm relative overflow-hidden`}>
                   {isPast && <div className="absolute top-0 right-0 bg-slate-100 text-slate-500 text-[10px] font-bold px-2 py-1 rounded-bl-lg">COMPLETED</div>}
                   {!isPast && <div className="absolute top-0 right-0 bg-green-100 text-green-700 text-[10px] font-bold px-2 py-1 rounded-bl-lg">UPCOMING</div>}

                   <div className="flex justify-between items-start mb-3">
