import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import PaymentForm from './components/PaymentForm';
import Reports from './components/Reports';
import Settings from './components/Settings';
import FinanceDashboard from './components/FinanceDashboard';
import FinanceForm from './components/FinanceForm';
import FlatMaster from './components/FlatMaster';
import HallBooking from './components/HallBooking';
import { AppState, ViewState, Transaction, FinancialRecord } from './types';
import { loadData } from './services/storageService';
import { STORAGE_KEY } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [state, setState] = useState<AppState | null>(null);

  // Edit State for Maintenance Transactions
  const [transactionToEdit, setTransactionToEdit] = useState<Transaction | null>(null);

  // State for Finance Module
  const [showFinanceForm, setShowFinanceForm] = useState(false);
  const [financeRecordToEdit, setFinanceRecordToEdit] = useState<FinancialRecord | null>(null);

  useEffect(() => {
    // Load data from local storage on mount
    const data = loadData();
    setState(data);

    // Listen for storage events (cross-tab synchronization)
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === STORAGE_KEY) {
        const newData = loadData();
        setState(newData);
      }
    };

    window.addEventListener('storage', handleStorageChange);
    return () => {
      window.removeEventListener('storage', handleStorageChange);
    };
  }, []);

  const handleStateUpdate = (newState: AppState) => {
    setState(newState);
  };

  const handleEditFromReport = (tx: Transaction) => {
    setTransactionToEdit(tx);
    setView('PAYMENT');
  };

  const clearEditMode = () => {
    setTransactionToEdit(null);
  };

  const handleEditFinanceRecord = (record: FinancialRecord) => {
    setFinanceRecordToEdit(record);
    setShowFinanceForm(true);
  };

  const closeFinanceForm = () => {
    setShowFinanceForm(false);
    setFinanceRecordToEdit(null);
  };

  if (!state) return <div className="flex h-screen items-center justify-center text-slate-500">Loading...</div>;

  return (
    <Layout currentView={view} setView={setView}>
      {view === 'DASHBOARD' && <Dashboard state={state} refreshState={handleStateUpdate} />}

      {view === 'PAYMENT' && (
        <PaymentForm 
          state={state} 
          refreshState={handleStateUpdate} 
          initialTransactionToEdit={transactionToEdit}
          onClearEdit={clearEditMode}
        />
      )}

      {view === 'FLATS' && (
        <FlatMaster 
          state={state} 
          refreshState={handleStateUpdate}
        />
      )}

      {view === 'ACCOUNTS' && (
        <FinanceDashboard 
          state={state} 
          refreshState={handleStateUpdate}
          onAddTransaction={() => setShowFinanceForm(true)}
          onEditTransaction={handleEditFinanceRecord}
        />
      )}

      {view === 'HALL_BOOKING' && (
        <HallBooking 
          state={state} 
          refreshState={handleStateUpdate}
        />
      )}

      {view === 'REPORTS' && (
        <Reports 
          state={state} 
          view="REPORTS" 
          refreshState={handleStateUpdate} 
          onEditTransaction={handleEditFromReport}
        />
      )}

      {view === 'UNPAID_LIST' && <Reports state={state} view="UNPAID_LIST" refreshState={handleStateUpdate} />}

      {view === 'SETTINGS' && <Settings state={state} refreshState={handleStateUpdate} />}

      {/* Modal for Finance Transactions */}
      {showFinanceForm && (
        <FinanceForm 
          state={state}
          refreshState={handleStateUpdate}
          onClose={closeFinanceForm}
          recordToEdit={financeRecordToEdit}
        />
      )}

    </Layout>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { AppState, HallBooking as HallBookingType } from '../types';
import { addHallBooking, deleteHallBooking } from '../services/storageService';
import { formatDate, formatCurrency, getTodayDateString } from '../utils/helpers';
import { Search, Plus, Calendar, Trash2, Share2, ArrowRight, User, Phone, CheckCircle2 } from 'lucide-react';
import { BUILDING_NAME } from '../constants';

interface HallBookingProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
}

type Mode = 'DASHBOARD' | 'NEW_BOOKING';

const HallBooking: React.FC<HallBookingProps> = ({ state, refreshState }) => {
  const [mode, setMode] = useState<Mode>('DASHBOARD');

  // Form State
  const [searchTerm, setSearchTerm] = useState('');
  const [step, setStep] = useState<1 | 2>(1); // 1: Select Flat, 2: Details
  const [selectedFlatId, setSelectedFlatId] = useState<string | null>(null);

  // Booking Person Details
  const [bookingFor, setBookingFor] = useState<'OWNER' | 'TENANT'>('OWNER');
  const [isRentedFlat, setIsRentedFlat] = useState(false);
  const [ownerName, setOwnerName] = useState(''); // Stores the name of whoever is booking
  const [mobile, setMobile] = useState('');

  const [hallType, setHallType] = useState<'BIG' | 'SMALL'>('BIG');
  const [bookingDate, setBookingDate] = useState(getTodayDateString());
  const [amount, setAmount] = useState<number | ''>('');

  const filteredFlats = useMemo(() => {
    if (!searchTerm) return [];
    return state.flats.filter(flat => 
      flat.flatNumber.toLowerCase().includes(searchTerm.toLowerCase()) || 
      flat.ownerName.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [state.flats, searchTerm]);

  // Sort bookings: Future first, then Past (descending date)
  const sortedBookings = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    const upcoming = (state.hallBookings || []).filter(b => b.bookingDate >= today).sort((a,b) => a.bookingDate.localeCompare(b.bookingDate));
    const past = (state.hallBookings || []).filter(b => b.bookingDate < today).sort((a,b) => b.bookingDate.localeCompare(a.bookingDate));
    return [...upcoming, ...past];
  }, [state.hallBookings]);

  const handleSelectFlat = (flatId: string) => {
    const flat = state.flats.find(f => f.id === flatId);
    if (flat) {
      setSelectedFlatId(flatId);
      setIsRentedFlat(!!flat.isRented);

      // Logic: Default to Tenant if rented, otherwise Owner
      if (flat.isRented) {
        setBookingFor('TENANT');
        setOwnerName(flat.tenantName || '');
        setMobile(flat.tenantMobile || '');
      } else {
        setBookingFor('OWNER');
        setOwnerName(flat.ownerName || '');
        setMobile(flat.mobile || '');
      }

      setStep(2);
    }
  };

  const toggleBookingFor = (type: 'OWNER' | 'TENANT') => {
    setBookingFor(type);
    const flat = state.flats.find(f => f.id === selectedFlatId);
    if (!flat) return;

    if (type === 'OWNER') {
      setOwnerName(flat.ownerName || '');
      setMobile(flat.mobile || '');
    } else {
      setOwnerName(flat.tenantName || '');
      setMobile(flat.tenantMobile || '');
    }
  };

  const generateWhatsAppReceipt = (booking: HallBookingType) => {
    const cleanMobile = booking.mobile.replace(/\D/g, '');
    const phone = cleanMobile.length > 10 ? cleanMobile : '91' + cleanMobile;

    const message = `*HALL BOOKING CONFIRMED*\n${BUILDING_NAME}\n\nDear *${booking.ownerName}*,\n\nYour booking for *${booking.hallType} HALL* is confirmed.\n\nFlat: *${booking.flatNumber}*\nDate: *${formatDate(booking.bookingDate)}*\nAmount Paid: *${formatCurrency(booking.amount)}*\n\nThank you!`;

    return `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;
  };

  const handleBookingSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedFlatId || !amount) return;

    const flat = state.flats.find(f => f.id === selectedFlatId);
    if (!flat) return;

    // We store the name in 'ownerName' field regardless if it's tenant or owner
    const newState = addHallBooking(state, {
      flatId: selectedFlatId,
      flatNumber: flat.flatNumber,
      ownerName, 
      mobile,
      hallType,
      bookingDate,
      amount: Number(amount)
    });

    refreshState(newState);
    setMode('DASHBOARD');
    resetForm();
  };

  const handleDelete = (id: string) => {
    if (window.confirm("Are you sure you want to cancel/delete this booking?")) {
      const newState = deleteHallBooking(state, id);
      refreshState(newState);
    }
  };

  const resetForm = () => {
    setStep(1);
    setSearchTerm('');
    setSelectedFlatId(null);
    setOwnerName('');
    setMobile('');
    setHallType('BIG');
    setBookingDate(getTodayDateString());
    setAmount('');
    setIsRentedFlat(false);
    setBookingFor('OWNER');
  };

  // --- RENDER FORM ---
  if (mode === 'NEW_BOOKING') {
    return (
      <div className="flex flex-col h-full bg-slate-50">
        <div className="p-4 bg-white border-b border-slate-200 sticky top-0 z-10 flex items-center justify-between shadow-sm">
           <button onClick={() => { setMode('DASHBOARD'); resetForm(); }} className="text-sm text-blue-600 font-bold">Cancel</button>
           <h2 className="text-lg font-bold text-slate-800">New Hall Booking</h2>
           <div className="w-10"></div>
        </div>

        {step === 1 ? (
          <div className="p-4 flex-1 flex flex-col">
             <div className="relative mb-4">
                <Search className="absolute left-3 top-3 text-slate-400" size={20} />
                <input
                  type="text"
                  placeholder="Search flat number..."
                  className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white text-slate-900"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  autoFocus
                />
             </div>

             <div className="flex-1 overflow-y-auto space-y-2 pb-20">
               {filteredFlats.length === 0 ? (
                 <div className="text-center text-slate-400 mt-10">
                   {searchTerm ? <p>No flats found.</p> : <p>Search for a flat to begin.</p>}
                 </div>
               ) : (
                 filteredFlats.map(flat => (
                   <button
                     key={flat.id}
                     onClick={() => handleSelectFlat(flat.id)}
                     className="w-full flex justify-between items-center p-4 bg-white rounded-xl border border-slate-100 shadow-sm active:bg-slate-50 transition-colors"
                   >
                     <div className="text-left">
                       <span className="text-lg font-bold text-slate-800">{flat.flatNumber}</span>
                       <span className="block text-sm text-slate-500">{flat.ownerName}</span>
                     </div>
                     <ArrowRight size={20} className="text-slate-300" />
                   </button>
                 ))
               )}
             </div>
          </div>
        ) : (
          <div className="p-4 flex-1 overflow-y-auto pb-20">
             <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 mb-6 flex items-center justify-between">
                <div>
                  <p className="text-xs text-blue-600 font-bold uppercase">Booking For</p>
                  <p className="text-xl font-bold text-blue-900">{state.flats.find(f => f.id === selectedFlatId)?.flatNumber}</p>
                </div>
                <button onClick={() => setStep(1)} className="text-xs text-blue-600 underline">Change</button>
             </div>

             <form onSubmit={handleBookingSubmit} className="space-y-5">

                {/* Rented Flat Toggle */}
                {isRentedFlat && (
                  <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-2">Who is booking?</label>
                    <div className="bg-slate-100 p-1 rounded-lg flex mb-1">
                      <button 
                        type="button"
                        onClick={() => toggleBookingFor('OWNER')}
                        className={`flex-1 py-2 text-xs font-bold rounded-md transition-all ${bookingFor === 'OWNER' ? 'bg-white shadow text-slate-800' : 'text-slate-500'}`}
                      >
                        Owner
                      </button>
                      <button 
                        type="button"
                        onClick={() => toggleBookingFor('TENANT')}
                        className={`flex-1 py-2 text-xs font-bold rounded-md transition-all ${bookingFor === 'TENANT' ? 'bg-white shadow text-slate-800' : 'text-slate-500'}`}
                      >
                        Tenant
                      </button>
                    </div>
                    {bookingFor === 'TENANT' && (
                       <p className="text-[10px] text-blue-600 italic">*Please ensure Tenant Name & Mobile are entered below.</p>
                    )}
                  </div>
                )}

                {/* Auto Filled Details */}
                <div className="grid grid-cols-1 gap-4">
                   <div>
                      <label className="block text-sm font-semibold text-slate-700 mb-2">Booked By (Name)</label>
                      <div className="relative">
                         <User size={18} className="absolute left-3 top-3.5 text-slate-400" />
                         <input
                           type="text"
                           required
                           value={ownerName}
                           onChange={(e) => setOwnerName(e.target.value)}
                           className="w-full pl-10 pr-4 py-3 bg-white border border-slate-300 rounded-lg text-slate-800 focus:ring-2 focus:ring-blue-500 outline-none"
                           placeholder={bookingFor === 'TENANT' ? "Enter Tenant Name" : "Enter Owner Name"}
