                      </div>
                   </div>
                   <div>
                      <label className="block text-sm font-semibold text-slate-700 mb-2">Mobile Number</label>
                      <div className="relative">
                         <Phone size={18} className="absolute left-3 top-3.5 text-slate-400" />
                         <input
                           type="tel"
                           required
                           value={mobile}
                           onChange={(e) => setMobile(e.target.value)}
                           className="w-full pl-10 pr-4 py-3 bg-white border border-slate-300 rounded-lg text-slate-800 focus:ring-2 focus:ring-blue-500 outline-none"
                           placeholder="Enter Mobile Number"
                         />
                      </div>
                   </div>
                </div>

                {/* Booking Details */}
                <div>
                   <label className="block text-sm font-semibold text-slate-700 mb-2">Select Hall</label>
                   <div className="grid grid-cols-2 gap-3">
                      <button
                        type="button"
                        onClick={() => setHallType('BIG')}
                        className={`py-3 rounded-lg font-bold border-2 transition-all ${hallType === 'BIG' ? 'border-blue-600 bg-blue-50 text-blue-700' : 'border-slate-200 bg-white text-slate-500'}`}
                      >
                        Big Hall
                      </button>
                      <button
                        type="button"
                        onClick={() => setHallType('SMALL')}
                        className={`py-3 rounded-lg font-bold border-2 transition-all ${hallType === 'SMALL' ? 'border-blue-600 bg-blue-50 text-blue-700' : 'border-slate-200 bg-white text-slate-500'}`}
                      >
                        Small Hall
                      </button>
                   </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div>
                       <label className="block text-sm font-semibold text-slate-700 mb-2">Booking Date</label>
                       <input
                         type="date"
                         required
                         value={bookingDate}
                         onChange={(e) => setBookingDate(e.target.value)}
                         className="w-full px-3 py-3 bg-white border border-slate-300 rounded-lg text-slate-800 focus:ring-2 focus:ring-blue-500 outline-none"
                       />
                    </div>
                    <div>
                       <label className="block text-sm font-semibold text-slate-700 mb-2">Amount (₹)</label>
                       <input
                         type="number"
                         required
                         placeholder="0.00"
                         value={amount}
                         onChange={(e) => setAmount(Number(e.target.value))}
                         className="w-full px-3 py-3 bg-white border border-slate-300 rounded-lg text-slate-800 focus:ring-2 focus:ring-blue-500 outline-none"
                       />
                    </div>
                </div>

                <button
                  type="submit"
                  className="w-full bg-blue-600 text-white font-bold py-4 rounded-xl shadow-lg shadow-blue-200 active:scale-[0.98] transition-transform mt-4"
                >
                  Confirm Booking
                </button>
             </form>
          </div>
        )}
      </div>
    );
  }

  // --- RENDER DASHBOARD (LIST) ---
  return (
    <div className="flex flex-col h-full bg-slate-50">
       <div className="p-4 bg-white border-b border-slate-200 sticky top-0 z-10 flex items-center justify-between shadow-sm">
           <h2 className="text-xl font-bold text-slate-800">Hall Bookings</h2>
           <button 
             onClick={() => { setMode('NEW_BOOKING'); resetForm(); }}
