interface HallBookingProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
}

type Mode = 'DASHBOARD' | 'NEW_BOOKING';

const HallBooking: React.FC<HallBookingProps> = ({ state, refreshState }) => {
  const [mode, setMode] = useState<Mode>('DASHBOARD');

  // Form State
  const [searchTerm, setSearchTerm] = useState('');
  const [step, setStep] = useState<1 | 2>(1); // 1: Select Flat, 2: Details
  const [selectedFlatId, setSelectedFlatId] = useState<string | null>(null);

  // Booking Person Details
  const [bookingFor, setBookingFor] = useState<'OWNER' | 'TENANT'>('OWNER');
  const [isRentedFlat, setIsRentedFlat] = useState(false);
  const [ownerName, setOwnerName] = useState(''); 
  const [mobile, setMobile] = useState('');

  const [hallType, setHallType] = useState<'BIG' | 'SMALL'>('BIG');
  const [bookingDate, setBookingDate] = useState(getTodayDateString());
  const [amount, setAmount] = useState<number | ''>('');

  const filteredFlats = useMemo(() => {
    if (!searchTerm) return [];
    return state.flats.filter(flat => 
      flat.flatNumber.toLowerCase().includes(searchTerm.toLowerCase()) || 
      flat.ownerName.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [state.flats, searchTerm]);

  // Sort bookings: Future first, then Past (descending date)
  const sortedBookings = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    const upcoming = (state.hallBookings || []).filter(b => b.bookingDate >= today).sort((a,b) => a.bookingDate.localeCompare(b.bookingDate));
    const past = (state.hallBookings || []).filter(b => b.bookingDate < today).sort((a,b) => b.bookingDate.localeCompare(a.bookingDate));
    return [...upcoming, ...past];
  }, [state.hallBookings]);

  const handleSelectFlat = (flatId: string) => {
    const flat = state.flats.find(f => f.id === flatId);
    if (flat) {
      setSelectedFlatId(flatId);
      setIsRentedFlat(!!flat.isRented);

      // Logic: Default to Tenant if rented, otherwise Owner
      if (flat.isRented) {
        setBookingFor('TENANT');
        setOwnerName(flat.tenantName || '');
        setMobile(flat.tenantMobile || '');
      } else {
        setBookingFor('OWNER');
        setOwnerName(flat.ownerName || '');
        setMobile(flat.mobile || '');
      }

      setStep(2);
    }
  };

  const toggleBookingFor = (type: 'OWNER' | 'TENANT') => {
    setBookingFor(type);
    const flat = state.flats.find(f => f.id === selectedFlatId);
    if (!flat) return;

    if (type === 'OWNER') {
      setOwnerName(flat.ownerName || '');
      setMobile(flat.mobile || '');
    } else {
      setOwnerName(flat.tenantName || '');
      setMobile(flat.tenantMobile || '');
    }
  };

  const generateWhatsAppReceipt = (booking: HallBookingType) => {
    const cleanMobile = booking.mobile.replace(/\D/g, '');
    const phone = cleanMobile.length > 10 ? cleanMobile : '91' + cleanMobile;

    const message = `*HALL BOOKING CONFIRMED*\n${BUILDING_NAME}\n\nDear *${booking.ownerName}*,\n\nYour booking for *${booking.hallType} HALL* is confirmed.\n\nFlat: *${booking.flatNumber}*\nDate: *${formatDate(booking.bookingDate)}*\nAmount Paid: *${formatCurrency(booking.amount)}*\n\nThank you!`;

    return `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;
  };

  const handleBookingSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedFlatId || !amount) return;

    const flat = state.flats.find(f => f.id === selectedFlatId);
    if (!flat) return;

    const newState = addHallBooking(state, {
      flatId: selectedFlatId,
      flatNumber: flat.flatNumber,
      ownerName, 
      mobile,
      hallType,
      bookingDate,
      amount: Number(amount)
    });

    refreshState(newState);
    setMode('DASHBOARD');
    resetForm();
  };

  const handleDelete = (id: string) => {
    if (window.confirm("Are you sure you want to cancel/delete this booking?")) {
      const newState = deleteHallBooking(state, id);
      refreshState(newState);
    }
  };

  const resetForm = () => {
    setStep(1);
    setSearchTerm('');
    setSelectedFlatId(null);
    setOwnerName('');
    setMobile('');
    setHallType('BIG');
    setBookingDate(getTodayDateString());
    setAmount('');
    setIsRentedFlat(false);
    setBookingFor('OWNER');
  };

  // Helper to extract Day and Month for UI
  const getDateParts = (dateStr: string) => {
      const d = new Date(dateStr);
      if (isNaN(d.getTime())) return { day: '--', month: '---' };
      const day = d.getDate();
      const month = d.toLocaleDateString('en-IN', { month: 'short' });
      return { day, month };
  };

  // --- RENDER FORM ---
  if (mode === 'NEW_BOOKING') {
    return (
      <div className="flex flex-col h-full bg-slate-50">
        {/* Header */}
        <div className="bg-white px-4 py-4 border-b border-slate-200 sticky top-0 z-20 flex justify-between items-center shadow-sm">
           <button onClick={() => { setMode('DASHBOARD'); resetForm(); }} className="p-2 -ml-2 text-slate-500 hover:text-slate-800 rounded-full hover:bg-slate-100">
             <X size={24} />
           </button>
           <h2 className="text-lg font-bold text-slate-800">New Booking</h2>
           <div className="w-8"></div>
        </div>

        {step === 1 ? (
          <div className="p-5 flex-1 flex flex-col">
             <div className="text-center mb-6 mt-2">
                <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-3">
                   <Home size={32} />
                </div>
                <h3 className="text-xl font-bold text-slate-800">Select Flat</h3>
                <p className="text-sm text-slate-500">Search for the flat booking the hall</p>
             </div>

             <div className="relative mb-6">
                <Search className="absolute left-4 top-3.5 text-blue-500" size={20} />
                <input
                  type="text"
                  placeholder="Search flat number (e.g. 101)..."
                  className="w-full pl-11 pr-4 py-3.5 rounded-2xl border border-slate-200 focus:outline-none focus:ring-4 focus:ring-blue-100 focus:border-blue-500 bg-white text-slate-900 shadow-sm transition-all"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  autoFocus
                />
             </div>

             <div className="flex-1 overflow-y-auto space-y-3 pb-20">
               {filteredFlats.length === 0 ? (
                 <div className="text-center text-slate-400 mt-10">
                   {searchTerm ? <p>No flats found matching "{searchTerm}"</p> : null}
                 </div>
               ) : (
                 filteredFlats.map(flat => (
                   <button
                     key={flat.id}
                     onClick={() => handleSelectFlat(flat.id)}
                     className="w-full flex justify-between items-center p-4 bg-white rounded-2xl border border-slate-100 shadow-sm active:scale-[0.98] transition-all hover:border-blue-200 group"
                   >
                     <div className="flex items-center space-x-4">
                        <div className="w-12 h-12 rounded-xl bg-slate-50 text-slate-600 flex items-center justify-center font-bold text-sm group-hover:bg-blue-600 group-hover:text-white transition-colors">
                            {flat.flatNumber.split('-')[1]}
                        </div>
                        <div className="text-left">
                            <span className="text-lg font-bold text-slate-800 block leading-tight">{flat.flatNumber}</span>
                            <span className="text-sm text-slate-500">{flat.ownerName}</span>
                        </div>
                     </div>
                     <div className="bg-slate-50 p-2 rounded-full text-slate-400 group-hover:text-blue-500 group-hover:bg-blue-50">
                        <ArrowRight size={20} />
                     </div>
                   </button>
                 ))
               )}
             </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto pb-20 bg-slate-50">

             {/* Selected Flat Card */}
             <div className="bg-blue-600 text-white p-6 pb-12 rounded-b-[2.5rem] shadow-lg relative overflow-hidden">
                <div className="relative z-10 flex justify-between items-start">
                    <div>
                        <p className="text-blue-100 text-xs font-bold uppercase tracking-wider mb-1">Booking For</p>
                        <h2 className="text-3xl font-bold">{state.flats.find(f => f.id === selectedFlatId)?.flatNumber}</h2>
                    </div>
                    <button onClick={() => setStep(1)} className="bg-blue-500 hover:bg-blue-400 text-white px-3 py-1 rounded-full text-xs font-bold transition-colors">
                        Change
                    </button>
                </div>
                {/* Decorative circles */}
                <div className="absolute top-[-20%] right-[-10%] w-40 h-40 bg-blue-500 rounded-full opacity-30 blur-2xl"></div>
                <div className="absolute bottom-[-10%] left-[-10%] w-32 h-32 bg-indigo-500 rounded-full opacity-30 blur-2xl"></div>
             </div>

             <div className="px-5 -mt-8 relative z-20">
                 <form onSubmit={handleBookingSubmit} className="space-y-6">

                    {/* Main Card */}
                    <div className="bg-white p-5 rounded-2xl shadow-lg border border-slate-100 space-y-6">

                        {/* Role Toggle */}
                        {isRentedFlat && (
                            <div className="bg-slate-100 p-1.5 rounded-xl flex relative">
                                <button 
                                    type="button"
                                    onClick={() => toggleBookingFor('OWNER')}
                                    className={`flex-1 py-2.5 text-sm font-bold rounded-lg transition-all z-10 ${bookingFor === 'OWNER' ? 'text-slate-800 shadow-sm bg-white' : 'text-slate-500'}`}
                                >
                                    Owner
                                </button>
                                <button 
                                    type="button"
                                    onClick={() => toggleBookingFor('TENANT')}
                                    className={`flex-1 py-2.5 text-sm font-bold rounded-lg transition-all z-10 ${bookingFor === 'TENANT' ? 'text-slate-800 shadow-sm bg-white' : 'text-slate-500'}`}
                                >
                                    Tenant
                                </button>
                            </div>
                        )}

                        {/* Hall Selection */}
                        <div>
                           <label className="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Select Hall Type</label>
                           <div className="grid grid-cols-2 gap-3">
                              <button
                                type="button"
                                onClick={() => setHallType('BIG')}
                                className={`relative p-4 rounded-2xl border-2 text-left transition-all overflow-hidden ${hallType === 'BIG' ? 'border-purple-500 bg-purple-50' : 'border-slate-100 bg-white hover:border-slate-200'}`}
                              >
                                <div className={`w-10 h-10 rounded-full flex items-center justify-center mb-3 ${hallType === 'BIG' ? 'bg-purple-500 text-white' : 'bg-slate-100 text-slate-400'}`}>
                                    <PartyPopper size={20} />
                                </div>
                                <span className={`block font-bold ${hallType === 'BIG' ? 'text-purple-900' : 'text-slate-700'}`}>Big Hall</span>
                                <span className="text-[10px] text-slate-500">For large events</span>
                                {hallType === 'BIG' && <div className="absolute top-2 right-2 text-purple-600"><CheckCircle2 size={16} fill="currentColor" className="text-white" /></div>}
                              </button>

                              <button
                                type="button"
                                onClick={() => setHallType('SMALL')}
                                className={`relative p-4 rounded-2xl border-2 text-left transition-all overflow-hidden ${hallType === 'SMALL' ? 'border-amber-500 bg-amber-50' : 'border-slate-100 bg-white hover:border-slate-200'}`}
                              >
                                <div className={`w-10 h-10 rounded-full flex items-center justify-center mb-3 ${hallType === 'SMALL' ? 'bg-amber-500 text-white' : 'bg-slate-100 text-slate-400'}`}>
                                    <Home size={20} />
                                </div>
                                <span className={`block font-bold ${hallType === 'SMALL' ? 'text-amber-900' : 'text-slate-700'}`}>Small Hall</span>
                                <span className="text-[10px] text-slate-500">For small gatherings</span>
                                {hallType === 'SMALL' && <div className="absolute top-2 right-2 text-amber-600"><CheckCircle2 size={16} fill="currentColor" className="text-white" /></div>}
                              </button>
                           </div>
                        </div>

                        {/* Inputs */}
                        <div className="space-y-4">
                             <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 ml-1">Name</label>
                                <div className="relative group">
                                    <User size={18} className="absolute left-3 top-3.5 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                                    <input
                                        type="text"
                                        required
                                        value={ownerName}
                                        onChange={(e) => setOwnerName(e.target.value)}
                                        className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-slate-800 focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none transition-all font-medium"
                                        placeholder={bookingFor === 'TENANT' ? "Tenant Name" : "Owner Name"}
                                    />
                                </div>
                             </div>

                             <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1 ml-1">Mobile</label>
                                <div className="relative group">
                                    <Phone size={18} className="absolute left-3 top-3.5 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                                    <input
                                        type="tel"
                                        required
                                        value={mobile}
                                        onChange={(e) => setMobile(e.target.value)}
                                        className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-slate-800 focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none transition-all font-medium"
                                        placeholder="Mobile Number"
                                    />
                                </div>
                             </div>

                             <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1 ml-1">Date</label>
                                    <div className="relative group">
                                        <CalendarDays size={18} className="absolute left-3 top-3.5 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                                        <input
                                            type="date"
                                            required
                                            value={bookingDate}
                                            onChange={(e) => setBookingDate(e.target.value)}
                                            className="w-full pl-10 pr-2 py-3 bg-slate-50 border border-slate-200 rounded-xl text-slate-800 focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none transition-all font-medium text-sm"
                                        />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1 ml-1">Amount</label>
                                    <div className="relative group">
                                        <span className="absolute left-3 top-3 text-slate-400 font-bold">₹</span>
                                        <input
                                            type="number"
                                            required
                                            placeholder="0"
                                            value={amount}
                                            onChange={(e) => setAmount(Number(e.target.value))}
                                            className="w-full pl-8 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-slate-800 focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none transition-all font-bold"
                                        />
                                    </div>
                                </div>
                             </div>
                        </div>

                        <button
                          type="submit"
                          className="w-full bg-slate-900 text-white font-bold py-4 rounded-xl shadow-xl shadow-slate-300 active:scale-[0.98] transition-transform flex items-center justify-center"
                        >
                          <CheckCircle2 size={20} className="mr-2" />
                          Confirm Booking
                        </button>

                    </div>
                 </form>
             </div>
          </div>
        )}
      </div>
    );
  }

  // --- RENDER DASHBOARD (LIST) ---
  return (
    <div className="flex flex-col h-full bg-slate-50">
       <div className="px-5 py-4 bg-white border-b border-slate-200 sticky top-0 z-10 flex items-center justify-between shadow-sm">
           <h2 className="text-xl font-bold text-slate-800">Hall Bookings</h2>
           <button 
             onClick={() => { setMode('NEW_BOOKING'); resetForm(); }}
             className="bg-blue-600 text-white px-4 py-2 rounded-full text-xs font-bold flex items-center shadow-lg shadow-blue-200 hover:bg-blue-700 hover:scale-105 transition-all"
           >
             <Plus size={16} className="mr-1" />
             New
           </button>
       </div>

       <div className="flex-1 overflow-y-auto p-4 pb-24 space-y-4">
          {sortedBookings.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-[60vh] text-center p-6">
               <div className="w-24 h-24 bg-slate-100 rounded-full flex items-center justify-center mb-4">
                  <Calendar size={40} className="text-slate-300" />
               </div>
               <h3 className="text-lg font-bold text-slate-700 mb-1">No Bookings Found</h3>
               <p className="text-sm text-slate-400 max-w-[200px]">Tap the "New" button to book the hall for an event.</p>
            </div>
          ) : (
            sortedBookings.map(booking => {
              const isPast = new Date(booking.bookingDate) < new Date(new Date().toISOString().split('T')[0]);
              const { day, month } = getDateParts(booking.bookingDate);

              return (
                <div key={booking.id} className={`bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden flex relative group ${isPast ? 'opacity-70 grayscale-[0.5]' : ''}`}>

                   {/* Left Date Strip */}
                   <div className={`w-20 flex flex-col items-center justify-center p-2 border-r border-dashed border-slate-200 ${booking.hallType === 'BIG' ? 'bg-purple-50' : 'bg-amber-50'}`}>
                      <span className={`text-[10px] font-black uppercase tracking-widest ${booking.hallType === 'BIG' ? 'text-purple-400' : 'text-amber-400'}`}>{month}</span>
                      <span className={`text-2xl font-black ${booking.hallType === 'BIG' ? 'text-purple-700' : 'text-amber-700'}`}>{day}</span>
                   </div>

                   {/* Main Content */}
                   <div className="flex-1 p-4 relative">
                      {/* Status Badge */}
                      <div className="absolute top-3 right-3">
                          {isPast ? (
                              <span className="bg-slate-100 text-slate-500 text-[10px] font-bold px-2 py-1 rounded-full">DONE</span>
                          ) : (
                              <span className="bg-green-100 text-green-700 text-[10px] font-bold px-2 py-1 rounded-full animate-pulse">UPCOMING</span>
                          )}
                      </div>

                      <div className="mb-3">
                          <div className="flex items-center gap-2 mb-1">
                             <span className={`text-[10px] font-bold px-2 py-0.5 rounded border uppercase tracking-wider ${booking.hallType === 'BIG' ? 'bg-purple-100 text-purple-700 border-purple-200' : 'bg-amber-100 text-amber-700 border-amber-200'}`}>
                                {booking.hallType} HALL
                             </span>
                          </div>
                          <h3 className="text-lg font-bold text-slate-800">{booking.flatNumber}</h3>

                          <div className="flex flex-col gap-1 mt-1">
                             <div className="flex items-center text-xs text-slate-500 font-medium">
                                <User size={12} className="mr-1.5 text-slate-400" />
                                {booking.ownerName}
                             </div>
                             {booking.mobile && (
                                <div className="flex items-center text-xs text-slate-500">
                                    <Phone size={12} className="mr-1.5 text-slate-400" />
                                    {booking.mobile}
                                </div>
                             )}
                          </div>
                      </div>

                      <div className="flex items-center justify-between pt-3 border-t border-slate-50 mt-2">
                          <span className="font-bold text-slate-700">{formatCurrency(booking.amount)}</span>

                          <div className="flex space-x-2">
                             {booking.mobile && (
                               <a 
                                 href={generateWhatsAppReceipt(booking)}
                                 target="_blank"
                                 rel="noreferrer"
                                 className="w-8 h-8 flex items-center justify-center bg-green-50 text-green-600 rounded-full hover:bg-green-500 hover:text-white transition-all shadow-sm"
                               >
                                  <Share2 size={14} />
                               </a>
                             )}
                             <button 
                               onClick={() => handleDelete(booking.id)}
                               className="w-8 h-8 flex items-center justify-center bg-red-50 text-red-600 rounded-full hover:bg-red-500 hover:text-white transition-all shadow-sm"
                             >
                                <Trash2 size={14} />
                             </button>
                          </div>
                      </div>
                   </div>

                   {/* Decorative circle notches for ticket effect */}
                   <div className="absolute top-[-6px] left-[76px] w-3 h-3 bg-slate-50 rounded-full shadow-inner z-10"></div>
                   <div className="absolute bottom-[-6px] left-[76px] w-3 h-3 bg-slate-50 rounded-full shadow-inner z-10"></div>

                </div>
              );
            })
          )}
       </div>
    </div>
  );
};

export default HallBooking;

import React, { useState, useMemo } from 'react';
import { AppState, HallBooking as HallBookingType } from '../types';
import { addHallBooking, deleteHallBooking } from '../services/storageService';
import { formatDate, formatCurrency, getTodayDateString } from '../utils/helpers';
import { Search, Plus, Calendar, Trash2, Share2, ArrowRight, User, Phone, MapPin, PartyPopper, Home, Users, CalendarDays, X, CheckCircle2 } from 'lucide-react';
import { BUILDING_NAME } from '../constants';

interface HallBookingProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
}

type Mode = 'DASHBOARD' | 'NEW_BOOKING';

const HallBooking: React.FC<HallBookingProps> = ({ state, refreshState }) => {
  const [mode, setMode] = useState<Mode>('DASHBOARD');

  // Form State
  const [searchTerm, setSearchTerm] = useState('');
  const [step, setStep] = useState<1 | 2>(1); // 1: Select Flat, 2: Details
  const [selectedFlatId, setSelectedFlatId] = useState<string | null>(null);

  // Booking Person Details
  const [bookingFor, setBookingFor] = useState<'OWNER' | 'TENANT'>('OWNER');
  const [isRentedFlat, setIsRentedFlat] = useState(false);
  const [ownerName, setOwnerName] = useState(''); 
  const [mobile, setMobile] = useState('');

  const [hallType, setHallType] = useState<'BIG' | 'SMALL'>('BIG');
  const [bookingDate, setBookingDate] = useState(getTodayDateString());
  const [amount, setAmount] = useState<number | ''>('');

  const filteredFlats = useMemo(() => {
    if (!searchTerm) return [];
    return state.flats.filter(flat => 
      flat.flatNumber.toLowerCase().includes(searchTerm.toLowerCase()) || 
      flat.ownerName.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [state.flats, searchTerm]);

  // Sort bookings: Future first, then Past (descending date)
  const sortedBookings = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    const upcoming = (state.hallBookings || []).filter(b => b.bookingDate >= today).sort((a,b) => a.bookingDate.localeCompare(b.bookingDate));
    const past = (state.hallBookings || []).filter(b => b.bookingDate < today).sort((a,b) => b.bookingDate.localeCompare(a.bookingDate));
    return [...upcoming, ...past];
  }, [state.hallBookings]);

  const handleSelectFlat = (flatId: string) => {
    const flat = state.flats.find(f => f.id === flatId);
    if (flat) {
      setSelectedFlatId(flatId);
      setIsRentedFlat(!!flat.isRented);

      // Logic: Default to Tenant if rented, otherwise Owner
      if (flat.isRented) {
        setBookingFor('TENANT');
        setOwnerName(flat.tenantName || '');
        setMobile(flat.tenantMobile || '');
      } else {
        setBookingFor('OWNER');
        setOwnerName(flat.ownerName || '');
        setMobile(flat.mobile || '');
      }

      setStep(2);
    }
  };

  const toggleBookingFor = (type: 'OWNER' | 'TENANT') => {
    setBookingFor(type);
    const flat = state.flats.find(f => f.id === selectedFlatId);
    if (!flat) return;

    if (type === 'OWNER') {
      setOwnerName(flat.ownerName || '');
      setMobile(flat.mobile || '');
    } else {
      setOwnerName(flat.tenantName || '');
      setMobile(flat.tenantMobile || '');
    }
  };

  const generateWhatsAppReceipt = (booking: HallBookingType) => {
    const cleanMobile = booking.mobile.replace(/\D/g, '');
    const phone = cleanMobile.length > 10 ? cleanMobile : '91' + cleanMobile;

