      // html2pdf reads the element. We can clone it or just temporarily show it.
      // The class 'hidden' hides it. Let's rely on a separate container that is absolutely positioned off-screen or handled by styling.
      // Actually html2pdf needs the element to be rendered.
      // We will remove 'hidden' class temporarily or use a specific print style.

      // Best approach: Use a specific container visible only to the PDF generator logic or temporarily displayed.
      // Since we are using React, let's toggle a class.

      const worker = (window as any).html2pdf().from(element).set(opt).save();
      worker.then(() => {
