      <button 
        onClick={onAddTransaction}
        className="fixed bottom-24 right-4 bg-blue-600 text-white p-4 rounded-full shadow-lg shadow-blue-300 hover:bg-blue-700 active:scale-95 transition-transform z-20 flex items-center justify-center"
      >
        <Plus size={24} />
      </button>

      {/* HIDDEN PDF REPORT TEMPLATE */}
      <div id="financial-report-template" className={`${isGeneratingPdf ? 'block' : 'hidden'} bg-white p-8 text-black max-w-[800px] mx-auto`}>
          <style dangerouslySetInnerHTML={{__html: `
            .pdf-table { width: 100%; border-collapse: collapse; margin-bottom: 20px; font-size: 12px; }
