                <td className="amount">{formatCurrency(reportData.globalCash)}</td>
                <td style={{ textAlign: 'center' }}>{reportData.totalLiquid > 0 ? ((reportData.globalCash / reportData.totalLiquid) * 100).toFixed(1) : 0}%</td>
              </tr>
              <tr style={{ fontWeight: 'bold' }}>
                <td>Total Liquid Funds</td>
                <td className="amount">{formatCurrency(reportData.totalLiquid)}</td>
                <td style={{ textAlign: 'center' }}>100%</td>
              </tr>
            </tbody>
          </table>

          <div style={{ textAlign: 'center', marginTop: '30px', fontSize: '12px', fontWeight: 'bold' }}>
             For any further details or clarification, you are requested to visit the Society Office at P7.
          </div>
      </div>
    </div>
  );
};

