import React, { useMemo, useState, useEffect } from 'react';
import { AppState, FinancialRecord } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { formatCurrency, formatDate, amountToWords } from '../utils/helpers';
import { Wallet, Plus, Trash2, Edit2, ChevronLeft, ChevronRight, TrendingUp, TrendingDown, IndianRupee, ArrowUpRight, ArrowDownRight, Building2, Sparkles, AlertCircle, Banknote, Landmark, ArrowRightLeft, FileText, Download, Calendar, Filter, PieChart as PieIcon, BarChart3 } from 'lucide-react';
import { deleteFinancialRecord, updateInsight } from '../services/storageService';
import { generateFinancialInsight } from '../services/geminiService';
import { MAINTENANCE_AMOUNT, TOTAL_FLATS } from '../constants';

interface FinanceDashboardProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
  onAddTransaction: () => void;
  onEditTransaction: (record: FinancialRecord) => void;
}

const FinanceDashboard: React.FC<FinanceDashboardProps> = ({ state, refreshState, onAddTransaction, onEditTransaction }) => {
  // Default to current month, but allow auto-switching
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [loadingInsight, setLoadingInsight] = useState(false);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  // Auto-switch to most recent month with data on load if current month is empty
  useEffect(() => {
    const currentMonth = new Date().toISOString().slice(0, 7);
    const hasCurrentData = state.financialRecords.some(r => r.date.startsWith(currentMonth));

    if (!hasCurrentData && state.financialRecords.length > 0) {
      // Find the latest record
      const sorted = [...state.financialRecords].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      if (sorted[0]) {
        setSelectedMonth(sorted[0].date.slice(0, 7));
      }
    }
  }, [state.financialRecords]);

  // Navigation Handlers
  const handlePrevMonth = () => {
    const d = new Date(selectedMonth + '-01');
    d.setMonth(d.getMonth() - 1);
    setSelectedMonth(d.toISOString().slice(0, 7));
  };

  const handleNextMonth = () => {
    const d = new Date(selectedMonth + '-01');
    d.setMonth(d.getMonth() + 1);
    setSelectedMonth(d.toISOString().slice(0, 7));
  };

  const formatMonthDisplay = (yyyyMm: string) => {
    if (!yyyyMm) return '';
    const d = new Date(yyyyMm + '-01');
    return d.toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });
  };

  // Process Data for Selected Month AND Running Balances
  const balanceData = useMemo(() => {
    let cashInHand = 0;
    let cashAtBank = 0;

    // Sort all records chronologically
    const allRecords = [...state.financialRecords].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    allRecords.forEach(r => {
      // Default undefined paymentMode to CASH for backward compatibility
      const mode = r.paymentMode || 'CASH';

      if (r.type === 'INCOME') {
        if (mode === 'CASH') cashInHand += r.amount;
        else cashAtBank += r.amount;
      } else if (r.type === 'EXPENSE') {
        if (mode === 'CASH') cashInHand -= r.amount;
        else cashAtBank -= r.amount;
      } else if (r.type === 'TRANSFER') {
        // Transfer logic: mode is SOURCE
        if (mode === 'CASH') {
           // Cash -> Bank
           cashInHand -= r.amount;
           cashAtBank += r.amount;
        } else {
           // Bank -> Cash (Withdrawal)
           cashAtBank -= r.amount;
           cashInHand += r.amount;
        }
      }
    });

    return { cashInHand, cashAtBank };
  }, [state.financialRecords]);

  // Report Specific Calculations
  const reportData = useMemo(() => {
     const startOfMonthStr = selectedMonth + '-01';
     const startOfNextMonth = new Date(selectedMonth + '-01');
     startOfNextMonth.setMonth(startOfNextMonth.getMonth() + 1);
     const endOfMonthStr = startOfNextMonth.toISOString().slice(0, 10);

     // 1. Opening Balance (Everything before startOfMonth)
     let openingBalance = 0;

     // Maintenance before this month
     const maintenanceBefore = state.transactions
        .filter(t => t.date < startOfMonthStr)
        .reduce((sum, t) => sum + t.amount, 0);

     // Financial Records before this month
     state.financialRecords.forEach(r => {
         if (r.date < startOfMonthStr) {
             if (r.type === 'INCOME') openingBalance += r.amount;
             if (r.type === 'EXPENSE') openingBalance -= r.amount;
         }
     });

     openingBalance += maintenanceBefore; // Add maintenance income

     // 2. Current Month Data
     const maintenanceThisMonth = state.transactions
        .filter(t => t.date >= startOfMonthStr && t.date < endOfMonthStr)
        .reduce((sum, t) => sum + t.amount, 0);

     const maintenanceCount = state.transactions
        .filter(t => t.date >= startOfMonthStr && t.date < endOfMonthStr).length;

     const incomeRecords = state.financialRecords
        .filter(r => r.type === 'INCOME' && r.date >= startOfMonthStr && r.date < endOfMonthStr);

     const totalOtherIncome = incomeRecords.reduce((sum, r) => sum + r.amount, 0);

     const expenseRecords = state.financialRecords
        .filter(r => r.type === 'EXPENSE' && r.date >= startOfMonthStr && r.date < endOfMonthStr);

     const totalExpenses = expenseRecords.reduce((sum, r) => sum + r.amount, 0);

     const totalIncome = maintenanceThisMonth + totalOtherIncome;
     const closingBalance = openingBalance + totalIncome - totalExpenses;

     // 3. Current Fund Position (Global)
     let globalCash = 0;
     let globalBank = 0;

     const totalMaintenanceAllTime = state.transactions.reduce((sum, t) => sum + t.amount, 0);

     globalCash = balanceData.cashInHand + totalMaintenanceAllTime; 
     globalBank = balanceData.cashAtBank;

     return {
         openingBalance,
         maintenanceThisMonth,
         maintenanceCount,
         incomeRecords,
         totalOtherIncome,
         expenseRecords,
         totalExpenses,
         totalIncome,
         closingBalance,
         globalCash,
         globalBank,
         totalLiquid: globalCash + globalBank
     };

  }, [state, selectedMonth, balanceData]);

  const monthlyData = useMemo(() => {
    const records = state.financialRecords.filter(r => r.date.startsWith(selectedMonth));
    const expenses = records.filter(r => r.type === 'EXPENSE').reduce((acc, r) => acc + r.amount, 0);
    const income = records.filter(r => r.type === 'INCOME').reduce((acc, r) => acc + r.amount, 0);
    const netChange = income - expenses;
    const combinedList = [...records].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    return { income, expenses, netChange, records: combinedList };
  }, [state.financialRecords, selectedMonth]);

  // Chart Data
  const chartData = [
    { name: 'Income', value: monthlyData.income, fill: '#10b981' }, 
    { name: 'Expense', value: monthlyData.expenses, fill: '#f43f5e' }, 
  ];

  // Expense Breakdown Pie Data
  const expenseBreakdown = useMemo(() => {
     const catMap = new Map<string, number>();
     state.financialRecords
       .filter(r => r.date.startsWith(selectedMonth) && r.type === 'EXPENSE')
       .forEach(r => {
          const cat = r.category || 'Uncategorized';
          catMap.set(cat, (catMap.get(cat) || 0) + r.amount);
       });
     return Array.from(catMap.entries()).map(([name, value]) => ({ name, value }));
  }, [state.financialRecords, selectedMonth]);

  const PIE_COLORS = ['#3b82f6', '#f59e0b', '#10b981', '#ef4444', '#8b5cf6', '#ec4899'];

  const handleDelete = (record: FinancialRecord) => {
    if(window.confirm(`Delete record: "${record.description || record.category}" (${formatCurrency(record.amount)})?`)) {
      const newState = deleteFinancialRecord(state, record.id);
      refreshState(newState);
    }
  };

  const handleGenerateInsight = async () => {
      setLoadingInsight(true);
      const text = await generateFinancialInsight(state);
      const newState = updateInsight(state, text);
      refreshState(newState);
      setLoadingInsight(false);
  };

  const generatePDF = () => {
    setIsGeneratingPdf(true);
    setTimeout(() => {
      const element = document.getElementById('financial-report-template');
      if (!element) return;

      const opt = {
        margin: 0.5,
        filename: `Financial_Report_${selectedMonth}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2 },
        jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' }
      };

      const worker = (window as any).html2pdf().from(element).set(opt).save();
      worker.then(() => {
          setIsGeneratingPdf(false);
      });
    }, 100);
  };

  const insight = state.aiInsight?.text;

  // Date Helpers for Report
  const reportDate = new Date(selectedMonth + '-01');
  const lastDayOfMonth = new Date(reportDate.getFullYear(), reportDate.getMonth() + 1, 0);
  const formattedReportDate = lastDayOfMonth.toLocaleDateString('en-GB').replace(/\//g, '-'); // DD-MM-YYYY
  const startOfMonthDate = new Date(reportDate.getFullYear(), reportDate.getMonth(), 1).toLocaleDateString('en-GB').replace(/\//g, '-');

  return (
    <div className="flex flex-col h-full bg-slate-50 relative">
      {/* Date Navigation Header - Sticky */}
      <div className="sticky top-0 z-30 bg-white border-b border-slate-200 shadow-sm px-5 py-3 flex items-center justify-between">

        <div className="flex items-center space-x-2 bg-slate-100 rounded-full p-1">
            <button 
              onClick={handlePrevMonth}
              className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-white text-slate-500 hover:text-slate-800 transition-all shadow-sm"
            >
              <ChevronLeft size={16} />
            </button>
            <span className="text-sm font-bold text-slate-800 px-2 min-w-[100px] text-center">
              {formatMonthDisplay(selectedMonth)}
            </span>
            <button 
              onClick={handleNextMonth}
              className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-white text-slate-500 hover:text-slate-800 transition-all shadow-sm"
            >
              <ChevronRight size={16} />
            </button>
        </div>

        <button 
            onClick={generatePDF}
            className="flex items-center space-x-2 px-3 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-900 transition-colors shadow-lg active:scale-95"
            title="Download PDF Report"
        >
            <Download size={14} />
            <span className="text-xs font-bold hidden sm:inline">Report</span>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-5 pb-24 space-y-6">

          {/* ACCOUNT BALANCES GRID */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

              {/* CASH IN HAND */}
              <div className="bg-gradient-to-br from-emerald-500 to-teal-600 p-6 rounded-2xl shadow-lg shadow-emerald-200 text-white relative overflow-hidden group">
                 <div className="relative z-10">
                    <div className="flex justify-between items-start mb-4">
                        <div className="p-2 bg-white/20 rounded-lg backdrop-blur-sm">
                            <Banknote size={24} className="text-white" />
                        </div>
                        <span className="text-[10px] bg-emerald-400/30 px-2 py-1 rounded text-white font-bold backdrop-blur-sm">CASH</span>
                    </div>
                    <p className="text-emerald-100 text-xs font-bold uppercase tracking-wider mb-1">Available Cash</p>
                    <h3 className="text-3xl font-bold tracking-tight">{formatCurrency(balanceData.cashInHand)}</h3>
                 </div>
                 <div className="absolute -right-6 -bottom-6 opacity-10 rotate-12 group-hover:scale-110 transition-transform duration-500">
                    <Banknote size={120} />
                 </div>
              </div>

              {/* CASH AT BANK */}
