    const parts = line.split(',').map(s => s?.trim());
    const [date, type, amountStr, category, description, mode] = parts;
    if (!type || !amountStr) return;

    const amount = parseFloat(amountStr);
    if (!isNaN(amount)) {
      const record: FinancialRecord = {
        id: `fin-${Date.now()}-${count}`,
        type: (type.toUpperCase() as any), 
        amount,
        date: date || new Date().toISOString().split('T')[0],
        category: category || 'General',
        description: description || '',
        paymentMode: (mode?.toUpperCase() === 'BANK') ? 'BANK' : 'CASH',
        timestamp: Date.now()
      };
      newState.financialRecords = [record, ...newState.financialRecords];
      count++;
    } else {
      errors.push(`Invalid amount at line ${index + 1}`);
    }
  });

  saveData(newState);
  return { newState, count, errors };
};

export const updateInsight = (state: AppState, text: string) => {
  const newState = {
    ...state,
    aiInsight: {
      text,
      timestamp: Date.now()
    }
  };
  saveData(newState);
  return newState;
};

// --- HALL BOOKING FUNCTIONS ---

export const addHallBooking = (state: AppState, booking: Omit<HallBooking, 'id' | 'timestamp'>) => {
  const newState = {
    ...state,
    hallBookings: [...(state.hallBookings || [])]
  };

  const newBooking: HallBooking = {
    ...booking,
    id: `hall-${Date.now()}`,
    timestamp: Date.now()
  };

  // Sort by date descending
  newState.hallBookings = [newBooking, ...newState.hallBookings].sort((a,b) => new Date(b.bookingDate).getTime() - new Date(a.bookingDate).getTime());

  saveData(newState);
  return newState;
};

export const deleteHallBooking = (state: AppState, bookingId: string) => {
  const newState = {
    ...state,
    hallBookings: (state.hallBookings || []).filter(b => b.id !== bookingId)
  };
  saveData(newState);
  return newState;
};

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import PaymentForm from './components/PaymentForm';
import Reports from './components/Reports';
import Settings from './components/Settings';
import FinanceDashboard from './components/FinanceDashboard';
import FinanceForm from './components/FinanceForm';
import FlatMaster from './components/FlatMaster';
import HallBooking from './components/HallBooking';
import { AppState, ViewState, Transaction, FinancialRecord } from './types';
import { loadData } from './services/storageService';
import { STORAGE_KEY } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [state, setState] = useState<AppState | null>(null);

  // Edit State for Maintenance Transactions
  const [transactionToEdit, setTransactionToEdit] = useState<Transaction | null>(null);

  // State for Finance Module
  const [showFinanceForm, setShowFinanceForm] = useState(false);
  const [financeRecordToEdit, setFinanceRecordToEdit] = useState<FinancialRecord | null>(null);

  useEffect(() => {
    // Load data from local storage on mount
    const data = loadData();
    setState(data);

    // Apply theme
    if (data.theme === 'DARK') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }

    // Listen for storage events (cross-tab synchronization)
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === STORAGE_KEY) {
        const newData = loadData();
        setState(newData);
        // Apply theme on storage change too
        if (newData.theme === 'DARK') {
          document.documentElement.classList.add('dark');
        } else {
          document.documentElement.classList.remove('dark');
        }
      }
    };

    window.addEventListener('storage', handleStorageChange);
    return () => {
      window.removeEventListener('storage', handleStorageChange);
    };
  }, []);

  // Update DOM when state theme changes
  useEffect(() => {
    if (state?.theme === 'DARK') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [state?.theme]);

  const handleStateUpdate = (newState: AppState) => {
    setState(newState);
  };

  const handleEditFromReport = (tx: Transaction) => {
    setTransactionToEdit(tx);
    setView('PAYMENT');
  };

  const clearEditMode = () => {
    setTransactionToEdit(null);
  };

  const handleEditFinanceRecord = (record: FinancialRecord) => {
    setFinanceRecordToEdit(record);
    setShowFinanceForm(true);
  };

  const closeFinanceForm = () => {
    setShowFinanceForm(false);
    setFinanceRecordToEdit(null);
  };

  if (!state) return <div className="flex h-screen items-center justify-center text-slate-500 dark:text-slate-400 bg-slate-50 dark:bg-slate-950">Loading...</div>;

  return (
    <Layout currentView={view} setView={setView}>
      {view === 'DASHBOARD' && <Dashboard state={state} refreshState={handleStateUpdate} />}

      {view === 'PAYMENT' && (
        <PaymentForm 
          state={state} 
          refreshState={handleStateUpdate} 
          initialTransactionToEdit={transactionToEdit}
          onClearEdit={clearEditMode}
        />
      )}

      {view === 'FLATS' && (
        <FlatMaster 
          state={state} 
          refreshState={handleStateUpdate}
        />
      )}

      {view === 'ACCOUNTS' && (
        <FinanceDashboard 
          state={state} 
          refreshState={handleStateUpdate}
          onAddTransaction={() => setShowFinanceForm(true)}
          onEditTransaction={handleEditFinanceRecord}
        />
      )}

      {view === 'HALL_BOOKING' && (
        <HallBooking 
          state={state} 
          refreshState={handleStateUpdate}
        />
      )}

      {view === 'REPORTS' && (
        <Reports 
          state={state} 
          view="REPORTS" 
          refreshState={handleStateUpdate} 
          onEditTransaction={handleEditFromReport}
        />
      )}

      {view === 'UNPAID_LIST' && <Reports state={state} view="UNPAID_LIST" refreshState={handleStateUpdate} />}

      {view === 'SETTINGS' && <Settings state={state} refreshState={handleStateUpdate} />}

      {/* Modal for Finance Transactions */}
      {showFinanceForm && (
        <FinanceForm 
          state={state}
          refreshState={handleStateUpdate}
          onClose={closeFinanceForm}
          recordToEdit={financeRecordToEdit}
        />
      )}

    </Layout>
  );
};

export default App;

import React, { useRef, useState, useEffect } from 'react';
import { AppState } from '../types';
import { updateFlatsFromCSV, exportDataToExcel, importDataFromExcel, importTransactionsFromCSV, createSystemSnapshot, restoreSystemSnapshot, getSnapshotTimestamp, syncFromCloud, importFinancialRecordsFromCSV, clearFinancialRecords, uploadCurrentDataToCloud, saveCloudConfig, getCloudConfig, updateTheme } from '../services/storageService';
import { downloadSampleCsv, downloadTransactionSampleCsv, downloadFinanceSampleCsv } from '../utils/helpers';
import { Upload, Download, FileText, CheckCircle, AlertTriangle, Database, Save, Receipt, RefreshCw, RotateCcw, History, Smartphone, Cloud, Wallet, Trash2, Lock, ArrowUpCircle, X, ChevronDown, ChevronUp, Moon, Sun } from 'lucide-react';
import { initFirebase } from '../services/firebaseService';

interface SettingsProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
}

const Settings: React.FC<SettingsProps> = ({ state, refreshState }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const dbInputRef = useRef<HTMLInputElement>(null);
  const txFileInputRef = useRef<HTMLInputElement>(null);
  const financeFileInputRef = useRef<HTMLInputElement>(null);

  const [status, setStatus] = useState<{ type: 'success' | 'error' | 'idle', message: string }>({ type: 'idle', message: '' });
  const [snapshotTime, setSnapshotTime] = useState<string | null>(null);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  const [cloudConnected, setCloudConnected] = useState(false);
  const [showConfigForm, setShowConfigForm] = useState(false);

  // Cloud Config State
  const [apiKey, setApiKey] = useState('');
  const [projectId, setProjectId] = useState('');
  const [authDomain, setAuthDomain] = useState('');

  useEffect(() => {
    // Load snapshot time
    const ts = getSnapshotTimestamp();
    if (ts) {
        setSnapshotTime(new Date(ts).toLocaleString());
    }

    // Check saved config
    const savedConfig = getCloudConfig();
    if (savedConfig) {
        setApiKey(savedConfig.apiKey);
        setProjectId(savedConfig.projectId);
        setAuthDomain(savedConfig.authDomain);
        if (initFirebase(savedConfig)) {
            setCloudConnected(true);
        } else {
            // Config exists but failed to init
            setCloudConnected(false);
            setShowConfigForm(true);
        }
    } else {
        setShowConfigForm(true);
    }

    // Listen for PWA install prompt
    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  const handleInstallClick = () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      deferredPrompt.userChoice.then((choiceResult: any) => {
        if (choiceResult.outcome === 'accepted') {
          console.log('User accepted the install prompt');
        }
        setDeferredPrompt(null);
      });
    }
  };

  const handleConnectCloud = () => {
    if (!apiKey || !projectId) {
        setStatus({ type: 'error', message: 'API Key and Project ID are required.' });
        return;
    }

    const config = {
        apiKey,
        projectId,
        authDomain: authDomain || `${projectId}.firebaseapp.com`
    };

    if (initFirebase(config)) {
        saveCloudConfig(config);
        setCloudConnected(true);
        setShowConfigForm(false);
        setStatus({ type: 'success', message: 'Connected to Firebase successfully!' });
    } else {
        setStatus({ type: 'error', message: 'Connection failed. Check your credentials.' });
    }
  };

  const handleDisconnectCloud = () => {
      localStorage.removeItem('firebase_config');
      setCloudConnected(false);
      setShowConfigForm(true);
      setStatus({ type: 'idle', message: 'Disconnected. Please reload if needed.' });
      // Reloading is often safest to clear Firebase instance state
      if(window.confirm("Disconnecting requires a reload. Reload now?")) {
          window.location.reload();
      }
  };

  const handleCloudSync = async () => {
    setStatus({ type: 'idle', message: 'Connecting to Cloud...' });
    try {
      const cloudData = await syncFromCloud();
      if (cloudData) {
        if(window.confirm("Found data on Cloud. This will OVERWRITE your local data. Proceed?")) {
            refreshState(cloudData);
            setStatus({ type: 'success', message: 'Successfully restored data from Cloud!' });
        } else {
            setStatus({ type: 'idle', message: 'Sync cancelled.' });
        }
      } else {
        // If cloud is empty, suggest uploading
        if (window.confirm("Cloud database is empty. Do you want to UPLOAD your current local data to seed the cloud?")) {
            handleCloudUpload();
        } else {
            setStatus({ type: 'error', message: 'No data found on Cloud.' });
        }
      }
    } catch (e) {
       setStatus({ type: 'error', message: 'Failed to connect to Cloud.' });
    }
  };

  const handleCloudUpload = async () => {
    try {
        const success = await uploadCurrentDataToCloud(state);
        if (success) {
            setStatus({ type: 'success', message: 'Data uploaded to Cloud successfully! Auto-sync is now active.' });
        } else {
            setStatus({ type: 'error', message: 'Failed to upload. Check internet connection.' });
        }
    } catch (e) {
        setStatus({ type: 'error', message: 'Error uploading to cloud.' });
    }
  };

  // CSV Bulk Update (Flats)
  const handleCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (text) {
        try {
          const { newState, updatedCount } = updateFlatsFromCSV(state, text);
          refreshState(newState);
          setStatus({
            type: 'success',
            message: `Successfully updated details for ${updatedCount} flats!`
          });
          if (fileInputRef.current) fileInputRef.current.value = '';
        } catch (error) {
           setStatus({
            type: 'error',
            message: 'Failed to process CSV.'
          });
        }
      }
    };
    reader.readAsText(file);
  };

  // CSV Bulk Import (Transactions)
  const handleTxCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (text) {
        try {
          const { newState, count, errors } = importTransactionsFromCSV(state, text);
          refreshState(newState);

          let msg = `Successfully imported ${count} transactions.`;
          if (errors.length > 0) {
            msg += ` ${errors.length} rows failed. Check console.`;
            console.warn("Import Errors:", errors);
          }

          if (count > 0) {
              setStatus({ type: 'success', message: msg });
           } else if (errors.length > 0) {
              setStatus({ type: 'error', message: "Failed to import any transactions. Check file format." });
           } else {
              setStatus({ type: 'idle', message: "" });
           }

          if (txFileInputRef.current) txFileInputRef.current.value = '';
        } catch (error) {
           setStatus({
            type: 'error',
            message: 'Failed to process CSV.'
          });
        }
      }
    };
    reader.readAsText(file);
  };

  // CSV Bulk Import (Financial Records)
  const handleFinanceCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (text) {
        try {
          const { newState, count, errors } = importFinancialRecordsFromCSV(state, text);
          refreshState(newState);

          let msg = `Successfully imported ${count} financial records.`;
          if (errors.length > 0) {
             console.warn("Import Errors:", errors);
             msg += ` (Some rows failed)`;
          }

          if (count > 0) {
              setStatus({ type: 'success', message: msg });
          } else {
              setStatus({ type: 'error', message: "Failed to import records. Check format." });
          }

          if (financeFileInputRef.current) financeFileInputRef.current.value = '';
        } catch (error) {
           setStatus({
            type: 'error',
            message: 'Failed to process CSV.'
          });
        }
      }
    };
    reader.readAsText(file);
  };

  // Excel Database Export
  const handleExportDB = () => {
    try {
      exportDataToExcel(state);
      setStatus({ type: 'success', message: 'Database exported to Excel successfully.' });
    } catch (e) {
      setStatus({ type: 'error', message: 'Failed to export database.' });
    }
  };

  // Excel Database Import
  const handleImportDB = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!window.confirm("WARNING: This will OVERWRITE all current data with the data from the Excel file. Are you sure?")) {
      if (dbInputRef.current) dbInputRef.current.value = '';
      return;
    }

    try {
      const newState = await importDataFromExcel(file);
      refreshState(newState);
      setStatus({ type: 'success', message: 'Database restored from Excel successfully.' });
    } catch (e) {
      console.error(e);
      // Show the specific error message
      const msg = e instanceof Error ? e.message : 'Unknown error occurred during import.';
      setStatus({ type: 'error', message: msg });
    }
    if (dbInputRef.current) dbInputRef.current.value = '';
  };

  const handleClearFinance = () => {
     if (window.confirm("Are you sure you want to DELETE ALL FINANCE RECORDS?\n\nThis will clear the Accounts data (Income/Expense).")) {
        const newState = clearFinancialRecords(state);
        refreshState(newState);
        setStatus({ type: 'success', message: 'All finance records cleared.' });
    }
  };

  const handleCreateSnapshot = () => {
      createSystemSnapshot(state);
      const ts = getSnapshotTimestamp();
      if (ts) setSnapshotTime(new Date(ts).toLocaleString());
      setStatus({ type: 'success', message: 'System Restore Point created successfully.' });
  };

  const handleRestoreSnapshot = () => {
      const ts = getSnapshotTimestamp();
      if (!ts) {
          alert("No restore point found.");
          return;
      }

      const timeStr = new Date(ts).toLocaleString();
      if (window.confirm(`Are you sure you want to restore the system to the state from: ${timeStr}?\n\nCurrent data will be overwritten.`)) {
          const newState = restoreSystemSnapshot();
          if (newState) {
              refreshState(newState);
              setStatus({ type: 'success', message: `System restored to ${timeStr}.` });
          } else {
              setStatus({ type: 'error', message: 'Failed to load restore point.' });
          }
      }
  };

  const toggleTheme = (theme: 'LIGHT' | 'DARK') => {
    const newState = updateTheme(state, theme);
    refreshState(newState);
  };

  return (
    <div className="p-4 space-y-8 pb-20 bg-slate-50 dark:bg-slate-950 min-h-screen">
      <h2 className="text-xl font-bold text-slate-800 dark:text-white">Settings & Data</h2>

