import React, { useState } from 'react';
import { AppState, PaymentStatus } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Legend, BarChart, Bar, XAxis, YAxis } from 'recharts';
import { formatCurrency, formatDate } from '../utils/helpers';
import { Sparkles, TrendingUp, Users, IndianRupee, AlertCircle, Percent, Clock, BarChart3 } from 'lucide-react';
import { generateFinancialInsight } from '../services/geminiService';
import { updateInsight } from '../services/storageService';

interface DashboardProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ state, refreshState }) => {
  const [loadingInsight, setLoadingInsight] = useState(false);

  const paidCount = state.flats.filter(f => f.status === PaymentStatus.PAID).length;
  const unpaidCount = state.flats.filter(f => f.status === PaymentStatus.UNPAID).length;
  const totalCollected = state.transactions.reduce((acc, curr) => acc + curr.amount, 0);

  // Today's stats
  const todayStr = new Date().toISOString().split('T')[0];
  const todayCollected = state.transactions
    .filter(t => t.date.startsWith(todayStr))
    .reduce((acc, curr) => acc + curr.amount, 0);

  const percentPaid = state.flats.length > 0 ? Math.round((paidCount / state.flats.length) * 100) : 0;

  const pieData = [
    { name: 'Paid', value: paidCount },
    { name: 'Unpaid', value: unpaidCount },
  ];

  const PIE_COLORS = ['#22c55e', '#ef4444'];

  // --- Weekly Trend Data Calculation ---
  const last7Days = [...Array(7)].map((_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - (6 - i)); // Reverse order to get oldest to newest
    return d.toISOString().split('T')[0];
  });

  const trendData = last7Days.map(dateStr => {
    const dailySum = state.transactions
      .filter(t => t.date.startsWith(dateStr))
      .reduce((sum, t) => sum + t.amount, 0);

    return {
      name: new Date(dateStr).toLocaleDateString('en-IN', { weekday: 'short' }), // Mon, Tue
      fullDate: new Date(dateStr).toLocaleDateString('en-IN', { day: '2-digit', month: 'short' }),
      amount: dailySum
    };
  });

  // --- Recent Transactions ---
  const recentTransactions = state.transactions.slice(0, 3);

  const handleGenerateInsight = async () => {
    setLoadingInsight(true);
    const text = await generateFinancialInsight(state);
    const newState = updateInsight(state, text);
    refreshState(newState);
    setLoadingInsight(false);
  };

  const insight = state.aiInsight?.text;
  const lastUpdated = state.aiInsight?.timestamp 
    ? new Date(state.aiInsight.timestamp).toLocaleString() 
    : null;

  return (
    <div className="p-4 space-y-6 bg-slate-50 dark:bg-slate-950 min-h-full">

      {/* Financial Stats - Side by Side Grid */}
      <div className="grid grid-cols-2 gap-4">

        {/* Card 1: Total Collected */}
        <div className="bg-blue-600 dark:bg-blue-700 p-5 rounded-2xl shadow-lg shadow-blue-200 dark:shadow-none text-white relative overflow-hidden text-center">
            <div className="relative z-10 flex flex-col items-center justify-center">
                <p className="text-blue-100 text-xs font-medium mb-1 flex items-center justify-center whitespace-nowrap">
                    <IndianRupee size={14} className="mr-1" />
                    Total Amount Collected
                </p>
                <h2 className="text-2xl font-bold truncate tracking-tight">{formatCurrency(totalCollected)}</h2>
            </div>
            {/* Decorative circle */}
            <div className="absolute -right-6 -top-6 w-20 h-20 bg-blue-500 rounded-full opacity-50 blur-xl"></div>
        </div>

        {/* Card 2: Collected Today */}
        <div className="bg-emerald-500 dark:bg-emerald-600 p-5 rounded-2xl shadow-lg shadow-emerald-200 dark:shadow-none text-white relative overflow-hidden text-center">
             <div className="relative z-10 flex flex-col items-center justify-center">
                <p className="text-emerald-100 text-xs font-medium mb-1 flex items-center justify-center whitespace-nowrap">
                    <TrendingUp size={14} className="mr-1" />
                    Today's Collection
                </p>
                <h2 className="text-2xl font-bold truncate tracking-tight">{formatCurrency(todayCollected)}</h2>
             </div>
             {/* Decorative circle */}
            <div className="absolute -right-6 -top-6 w-20 h-20 bg-emerald-400 rounded-full opacity-50 blur-xl"></div>
        </div>

      </div>

      {/* Counts Grid with Percentage in between */}
      <div className="grid grid-cols-3 gap-3">

        {/* Paid */}
        <div className="bg-white dark:bg-slate-900 p-3 rounded-xl shadow-sm border border-slate-100 dark:border-slate-800 flex flex-col items-center text-center">
           <div className="flex items-center justify-center space-x-1 text-slate-500 dark:text-slate-400 mb-1">
            <Users size={14} />
            <span className="text-[10px] font-bold uppercase tracking-wider">Paid</span>
          </div>
          <p className="text-xl font-bold text-green-700 dark:text-green-500 leading-tight">{paidCount}</p>
          <p className="text-[10px] text-slate-400">/ {state.flats.length}</p>
        </div>

        {/* Percentage */}
        <div className="bg-white dark:bg-slate-900 p-3 rounded-xl shadow-sm border border-slate-100 dark:border-slate-800 relative overflow-hidden flex flex-col items-center text-center">
           <div className="flex items-center justify-center space-x-1 text-slate-500 dark:text-slate-400 mb-1 relative z-10">
            <Percent size={14} />
            <span className="text-[10px] font-bold uppercase tracking-wider leading-tight">Collection Done</span>
          </div>
          <p className="text-xl font-bold text-blue-600 dark:text-blue-400 leading-tight relative z-10">{percentPaid}%</p>
          <p className="text-[10px] text-slate-400 relative z-10">complete</p>

          {/* Progress bar at bottom */}
