                      <TrendingUp size={16} />
                   </div>
                   <div>
                      <p className="text-[10px] text-slate-400 dark:text-slate-500 font-bold uppercase">Income</p>
                      <p className="text-sm font-bold text-emerald-600 dark:text-emerald-400">{formatCurrency(reportData.totalIncome)}</p>
                   </div>
              </div>

              <div className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-100 dark:border-slate-800 shadow-sm flex flex-col items-center justify-center text-center space-y-2">
                   <div className="w-8 h-8 rounded-full bg-red-50 dark:bg-red-900/30 text-red-600 dark:text-red-400 flex items-center justify-center mb-1">
                      <TrendingDown size={16} />
                   </div>
                   <div>
                      <p className="text-[10px] text-slate-400 dark:text-slate-500 font-bold uppercase">Expense</p>
                      <p className="text-sm font-bold text-red-600 dark:text-red-400">{formatCurrency(reportData.totalExpenses)}</p>
                   </div>
              </div>

              <div className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-100 dark:border-slate-800 shadow-sm flex flex-col items-center justify-center text-center space-y-2">
                   <div className="w-8 h-8 rounded-full bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 flex items-center justify-center mb-1">
                      <Wallet size={16} />
                   </div>
                   <div>
                      <p className="text-[10px] text-slate-400 dark:text-slate-500 font-bold uppercase">Closing</p>
                      <p className={`text-sm font-bold ${reportData.closingBalance >= 0 ? 'text-blue-600 dark:text-blue-400' : 'text-red-600 dark:text-red-400'}`}>{formatCurrency(reportData.closingBalance)}</p>
                   </div>
              </div>
          </div>

          {/* Charts Grid */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
               {/* Financial Overview (Bar Chart) */}
               <div className="bg-white dark:bg-slate-900 p-5 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm">
                    <div className="flex justify-between items-center mb-4">
                        <h3 className="text-sm font-bold text-slate-800 dark:text-white flex items-center">
