                 <span className="text-xs bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 px-2 py-1 rounded-full font-bold">{monthlyData.records.length}</span>
             </div>

             <div className="space-y-3">
                 {monthlyData.records.length > 0 ? monthlyData.records.map(record => (
                     <div key={record.id} className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-100 dark:border-slate-800 shadow-sm flex flex-col gap-3 hover:border-blue-100 dark:hover:border-blue-900/50 transition-colors group">
