                            <button 
                                onClick={() => handleDelete(record)} 
                                className="p-2 text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-900/20 rounded-lg hover:bg-red-100 dark:hover:bg-red-900/40 transition-colors"
                            >
                                <Trash2 size={14} />
                            </button>
                         </div>
                     </div>
                 )) : (
                     <div className="text-center py-12 bg-white dark:bg-slate-900 rounded-xl border border-slate-100 dark:border-slate-800 border-dashed">
                         <div className="w-12 h-12 bg-slate-50 dark:bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-3">
                            <Calendar size={20} className="text-slate-400" />
                         </div>
                         <p className="text-sm text-slate-500 font-medium">No transactions this month</p>
                         <p className="text-xs text-slate-400 mt-1">Tap + to add one</p>
                     </div>
                 )}
             </div>
          </div>

      </div>

      {/* Floating Action Button */}
      <button 
        onClick={onAddTransaction}
        className="fixed bottom-24 right-4 bg-slate-900 dark:bg-white text-white dark:text-black p-4 rounded-full shadow-xl shadow-slate-400 dark:shadow-none hover:scale-105 active:scale-95 transition-all z-20 flex items-center justify-center group"
      >
        <Plus size={24} className="group-hover:rotate-90 transition-transform duration-300" />
      </button>

      {/* HIDDEN PDF REPORT TEMPLATE */}
      <div id="financial-report-template" className={`${isGeneratingPdf ? 'block' : 'hidden'} bg-white p-8 text-black max-w-[800px] mx-auto`}>
          <style dangerouslySetInnerHTML={{__html: `
            .pdf-table { width: 100%; border-collapse: collapse; margin-bottom: 20px; font-size: 12px; }
            .pdf-table th, .pdf-table td { border: 1px solid black; padding: 6px; text-align: left; }
            .pdf-table th { background-color: #e5e7eb; font-weight: bold; text-align: center; }
            .pdf-table td.amount { text-align: right; }
            .pdf-header { text-align: center; margin-bottom: 20px; text-decoration: underline; font-weight: bold; font-size: 18px; }
            .pdf-sub-header { text-align: center; margin-bottom: 30px; font-weight: bold; font-size: 14px; }
            .section-title { font-weight: bold; text-decoration: underline; margin-bottom: 10px; font-size: 14px; margin-top: 20px; }
            .note { font-size: 11px; margin-top: 10px; font-style: italic; }
            .red-text { color: red; }
          `}} />

          <div className="pdf-header">CONTINENTAL HEIGHTS B WING</div>
          <div className="pdf-sub-header">FINANCIAL REPORT AS ON {formattedReportDate}</div>

          {/* 1. INCOME & EXPENSE SUMMARY */}
          <div className="section-title">INCOME & EXPENSE SUMMARY</div>
          <table className="pdf-table">
            <thead>
              <tr>
                <th>Particulars</th>
                <th>Amount</th>
                <th>Notes</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td>Opening Balance ({startOfMonthDate})</td>
                <td className="amount">{formatCurrency(reportData.openingBalance)}</td>
                <td>Previous month carry forward</td>
              </tr>
              <tr>
                <td>Total Income for {reportDate.toLocaleDateString('en-IN', {month: 'long', year: 'numeric'})}</td>
                <td className="amount">{formatCurrency(reportData.totalIncome)}</td>
                <td>Including maintenance & other income</td>
              </tr>
              <tr>
                <td>Total Expenses for {reportDate.toLocaleDateString('en-IN', {month: 'long', year: 'numeric'})}</td>
                <td className="amount red-text">({formatCurrency(reportData.totalExpenses)})</td>
                <td>Operational & maintenance costs</td>
              </tr>
              <tr>
                <td>Closing Fund Balance ({formattedReportDate})</td>
                <td className="amount font-bold">{formatCurrency(reportData.closingBalance)}</td>
                <td>Total Amount Available</td>
              </tr>
            </tbody>
          </table>

          {/* 2. DETAILED INCOME ANALYSIS */}
          <div className="section-title">DETAILED INCOME ANALYSIS</div>

          {/* Maintenance Summary Box */}
          <div style={{ marginBottom: '15px', border: '1px solid black', padding: '10px' }}>
            <div className="section-title" style={{ marginTop: 0 }}>MAINTENANCE COLLECTION DETAILS FOR {reportDate.toLocaleDateString('en-IN', {month: 'long', year: 'numeric'}).toUpperCase()}</div>
            <div style={{ fontSize: '12px', lineHeight: '1.6' }}>
                <div>Total Members: <strong>{TOTAL_FLATS}</strong></div>
                <div>Members Paid: <strong>{reportData.maintenanceCount} ({Math.round((reportData.maintenanceCount/TOTAL_FLATS)*100)}%)</strong></div>
                <div>Members Unpaid: <strong>{TOTAL_FLATS - reportData.maintenanceCount} ({Math.round(((TOTAL_FLATS - reportData.maintenanceCount)/TOTAL_FLATS)*100)}%)</strong></div>
                <div>Unpaid Reason: Flats are Closed or Builders Unsold Flats</div>
                <div>Amount Collected: <strong>{formatCurrency(reportData.maintenanceThisMonth)}</strong></div>
                <div>Estimated Outstanding: <strong>{formatCurrency((TOTAL_FLATS - reportData.maintenanceCount) * MAINTENANCE_AMOUNT)}</strong></div>
            </div>
          </div>

          <table className="pdf-table">
            <thead>
              <tr>
                <th>Date</th>
                <th>Source</th>
                <th>Particulars</th>
                <th>Amount</th>
              </tr>
            </thead>
            <tbody>
              {/* Aggregated Maintenance Row */}
              <tr>
                <td style={{ textAlign: 'center' }}>{formattedReportDate}</td>
                <td>Maintenance</td>
                <td>Monthly Maintenance ({reportData.maintenanceCount} Flats @ {MAINTENANCE_AMOUNT} per Flat)</td>
                <td className="amount">{formatCurrency(reportData.maintenanceThisMonth)}</td>
              </tr>

              {/* Other Income Rows */}
              {reportData.incomeRecords.map((r, i) => (
                 <tr key={i}>
                    <td style={{ textAlign: 'center' }}>{formatDate(r.date)}</td>
                    <td>Income</td>
                    <td>{r.category} - {r.description}</td>
                    <td className="amount">{formatCurrency(r.amount)}</td>
                 </tr>
              ))}

              <tr style={{ fontWeight: 'bold' }}>
                 <td></td>
                 <td></td>
                 <td style={{ textAlign: 'right' }}>TOTAL INCOME</td>
                 <td className="amount">{formatCurrency(reportData.totalIncome)}</td>
              </tr>
            </tbody>
          </table>

          {/* Page Break for Expenses usually, but CSS might handle flow */}
          <div style={{ pageBreakBefore: 'always' }}></div>

          {/* 3. DETAILED EXPENSE ANALYSIS */}
          <div className="section-title">DETAILED EXPENSE ANALYSIS</div>
          <table className="pdf-table">
            <thead>
              <tr>
                <th>Date</th>
                <th>Category</th>
                <th>Particulars</th>
                <th>Amount (₹)</th>
              </tr>
            </thead>
            <tbody>
              {reportData.expenseRecords.map((r, i) => (
                 <tr key={i}>
                    <td style={{ textAlign: 'center' }}>{formatDate(r.date)}</td>
                    <td>{r.category}</td>
                    <td>{r.description}</td>
                    <td className="amount">{formatCurrency(r.amount)}</td>
                 </tr>
              ))}
              {reportData.expenseRecords.length === 0 && (
                  <tr><td colSpan={4} style={{textAlign: 'center'}}>No expenses recorded.</td></tr>
              )}
              <tr style={{ fontWeight: 'bold' }}>
                 <td></td>
                 <td></td>
                 <td style={{ textAlign: 'right' }}>TOTAL EXPENSES</td>
                 <td className="amount">{formatCurrency(reportData.totalExpenses)}</td>
