            </tbody>
          </table>

          {/* 4. NOTE */}
          <div className="section-title">NOTE:</div>
          <ul style={{ fontSize: '12px', paddingLeft: '20px' }}>
             <li>Vendor Payment Includes Payment for Security Guards, Cleaning Services, Waterman & Plumber Service.</li>
             <li>Electricity Bills and Common Area Bills are paid as received.</li>
