                <td>Cash in Hand</td>
                <td className="amount">{formatCurrency(reportData.globalCash)}</td>
                <td style={{ textAlign: 'center' }}>{reportData.totalLiquid > 0 ? ((reportData.globalCash / reportData.totalLiquid) * 100).toFixed(1) : 0}%</td>
