              </div>
              {flat.isRented && <span className="bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400 text-[10px] font-bold px-2 py-1 rounded-full">RENTED</span>}
            </button>
          ))}
       </div>
    </div>
  );

  // --- EDIT VIEW ---
  if (selectedFlatId) {
    return (
