import React, { useState, useMemo } from 'react';
import { AppState, HallBooking as HallBookingType } from '../types';
import { addHallBooking, deleteHallBooking } from '../services/storageService';
import { formatDate, formatCurrency, getTodayDateString } from '../utils/helpers';
import { Search, Plus, Calendar, Trash2, Share2, ArrowRight, User, Phone, MapPin, PartyPopper, Home, Users, CalendarDays, X, CheckCircle2 } from 'lucide-react';
import { BUILDING_NAME } from '../constants';

interface HallBookingProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
}

type Mode = 'DASHBOARD' | 'NEW_BOOKING';

const HallBooking: React.FC<HallBookingProps> = ({ state, refreshState }) => {
  const [mode, setMode] = useState<Mode>('DASHBOARD');

  // Form State
  const [searchTerm, setSearchTerm] = useState('');
  const [step, setStep] = useState<1 | 2>(1); // 1: Select Flat, 2: Details
  const [selectedFlatId, setSelectedFlatId] = useState<string | null>(null);

  // Booking Person Details
  const [bookingFor, setBookingFor] = useState<'OWNER' | 'TENANT'>('OWNER');
  const [isRentedFlat, setIsRentedFlat] = useState(false);
  const [ownerName, setOwnerName] = useState(''); 
  const [mobile, setMobile] = useState('');

  const [hallType, setHallType] = useState<'BIG' | 'SMALL'>('BIG');
  const [bookingDate, setBookingDate] = useState(getTodayDateString());
  const [amount, setAmount] = useState<number | ''>('');

  const filteredFlats = useMemo(() => {
    if (!searchTerm) return [];
    return state.flats.filter(flat => 
      flat.flatNumber.toLowerCase().includes(searchTerm.toLowerCase()) || 
      flat.ownerName.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [state.flats, searchTerm]);

  // Sort bookings: Future first, then Past (descending date)
  const sortedBookings = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    const upcoming = (state.hallBookings || []).filter(b => b.bookingDate >= today).sort((a,b) => a.bookingDate.localeCompare(b.bookingDate));
    const past = (state.hallBookings || []).filter(b => b.bookingDate < today).sort((a,b) => b.bookingDate.localeCompare(a.bookingDate));
    return [...upcoming, ...past];
  }, [state.hallBookings]);

  const handleSelectFlat = (flatId: string) => {
    const flat = state.flats.find(f => f.id === flatId);
    if (flat) {
      setSelectedFlatId(flatId);
      setIsRentedFlat(!!flat.isRented);

      // Logic: Default to Tenant if rented, otherwise Owner
      if (flat.isRented) {
        setBookingFor('TENANT');
        setOwnerName(flat.tenantName || '');
        setMobile(flat.tenantMobile || '');
      } else {
        setBookingFor('OWNER');
        setOwnerName(flat.ownerName || '');
        setMobile(flat.mobile || '');
      }

      setStep(2);
    }
  };

  const toggleBookingFor = (type: 'OWNER' | 'TENANT') => {
    setBookingFor(type);
    const flat = state.flats.find(f => f.id === selectedFlatId);
    if (!flat) return;

    if (type === 'OWNER') {
      setOwnerName(flat.ownerName || '');
      setMobile(flat.mobile || '');
    } else {
      setOwnerName(flat.tenantName || '');
      setMobile(flat.tenantMobile || '');
    }
  };

  const generateWhatsAppReceipt = (booking: HallBookingType) => {
    const cleanMobile = booking.mobile.replace(/\D/g, '');
    const phone = cleanMobile.length > 10 ? cleanMobile : '91' + cleanMobile;

    const message = `*HALL BOOKING CONFIRMED*\n${BUILDING_NAME}\n\nDear *${booking.ownerName}*,\n\nYour booking for *${booking.hallType} HALL* is confirmed.\n\nFlat: *${booking.flatNumber}*\nDate: *${formatDate(booking.bookingDate)}*\nAmount Paid: *${formatCurrency(booking.amount)}*\n\nThank you!`;

    return `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;
  };

  const handleBookingSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedFlatId || !amount) return;

    const flat = state.flats.find(f => f.id === selectedFlatId);
    if (!flat) return;

    const newState = addHallBooking(state, {
      flatId: selectedFlatId,
      flatNumber: flat.flatNumber,
      ownerName, 
      mobile,
      hallType,
      bookingDate,
      amount: Number(amount)
    });

    refreshState(newState);
    setMode('DASHBOARD');
    resetForm();
  };

  const handleDelete = (id: string) => {
    if (window.confirm("Are you sure you want to cancel/delete this booking?")) {
      const newState = deleteHallBooking(state, id);
      refreshState(newState);
    }
  };

  const resetForm = () => {
    setStep(1);
    setSearchTerm('');
    setSelectedFlatId(null);
    setOwnerName('');
    setMobile('');
    setHallType('BIG');
    setBookingDate(getTodayDateString());
    setAmount('');
    setIsRentedFlat(false);
    setBookingFor('OWNER');
  };

  // Helper to extract Day and Month for UI
  const getDateParts = (dateStr: string) => {
      const d = new Date(dateStr);
      if (isNaN(d.getTime())) return { day: '--', month: '---' };
      const day = d.getDate();
      const month = d.toLocaleDateString('en-IN', { month: 'short' });
      return { day, month };
  };

  // --- RENDER FORM ---
  if (mode === 'NEW_BOOKING') {
    return (
      <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-950">
        {/* Header */}
        <div className="bg-white dark:bg-slate-900 px-4 py-4 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-20 flex justify-between items-center shadow-sm">
           <button onClick={() => { setMode('DASHBOARD'); resetForm(); }} className="p-2 -ml-2 text-slate-500 hover:text-slate-800 dark:hover:text-white rounded-full hover:bg-slate-100 dark:hover:bg-slate-800">
             <X size={24} />
           </button>
           <h2 className="text-lg font-bold text-slate-800 dark:text-white">New Booking</h2>
           <div className="w-8"></div>
        </div>

        {step === 1 ? (
          <div className="p-5 flex-1 flex flex-col">
             <div className="text-center mb-6 mt-2">
                <div className="w-16 h-16 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-full flex items-center justify-center mx-auto mb-3">
                   <Home size={32} />
                </div>
                <h3 className="text-xl font-bold text-slate-800 dark:text-white">Select Flat</h3>
                <p className="text-sm text-slate-500 dark:text-slate-400">Search for the flat booking the hall</p>
             </div>

             <div className="relative mb-6">
                <Search className="absolute left-4 top-3.5 text-blue-500" size={20} />
                <input
                  type="text"
                  placeholder="Search flat number (e.g. 101)..."
                  className="w-full pl-11 pr-4 py-3.5 rounded-2xl border border-slate-200 dark:border-slate-700 focus:outline-none focus:ring-4 focus:ring-blue-100 dark:focus:ring-blue-900 bg-white dark:bg-slate-800 text-slate-900 dark:text-white shadow-sm transition-all"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  autoFocus
                />
             </div>

             <div className="flex-1 overflow-y-auto space-y-3 pb-20">
               {filteredFlats.length === 0 ? (
                 <div className="text-center text-slate-400 dark:text-slate-500 mt-10">
                   {searchTerm ? <p>No flats found matching "{searchTerm}"</p> : null}
                 </div>
               ) : (
                 filteredFlats.map(flat => (
                   <button
                     key={flat.id}
                     onClick={() => handleSelectFlat(flat.id)}
                     className="w-full flex justify-between items-center p-4 bg-white dark:bg-slate-900 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm active:scale-[0.98] transition-all hover:border-blue-200 dark:hover:border-slate-700 group"
                   >
                     <div className="flex items-center space-x-4">
                        <div className="w-12 h-12 rounded-xl bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-400 flex items-center justify-center font-bold text-sm group-hover:bg-blue-600 group-hover:text-white transition-colors">
                            {flat.flatNumber.split('-')[1]}
                        </div>
                        <div className="text-left">
                            <span className="text-lg font-bold text-slate-800 dark:text-white block leading-tight">{flat.flatNumber}</span>
                            <span className="text-sm text-slate-500 dark:text-slate-400">{flat.ownerName}</span>
                        </div>
                     </div>
                     <div className="bg-slate-50 dark:bg-slate-800 p-2 rounded-full text-slate-400 group-hover:text-blue-500 group-hover:bg-blue-50">
                        <ArrowRight size={20} />
                     </div>
                   </button>
                 ))
               )}
             </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto pb-20 bg-slate-50 dark:bg-slate-950">

             {/* Selected Flat Card */}
             <div className="bg-blue-600 dark:bg-blue-800 text-white p-6 pb-12 rounded-b-[2.5rem] shadow-lg relative overflow-hidden">
                <div className="relative z-10 flex justify-between items-start">
                    <div>
                        <p className="text-blue-100 text-xs font-bold uppercase tracking-wider mb-1">Booking For</p>
                        <h2 className="text-3xl font-bold">{state.flats.find(f => f.id === selectedFlatId)?.flatNumber}</h2>
                    </div>
                    <button onClick={() => setStep(1)} className="bg-blue-500 hover:bg-blue-400 text-white px-3 py-1 rounded-full text-xs font-bold transition-colors">
                        Change
                    </button>
                </div>
                {/* Decorative circles */}
                <div className="absolute top-[-20%] right-[-10%] w-40 h-40 bg-blue-500 rounded-full opacity-30 blur-2xl"></div>
                <div className="absolute bottom-[-10%] left-[-10%] w-32 h-32 bg-indigo-500 rounded-full opacity-30 blur-2xl"></div>
             </div>

             <div className="px-5 -mt-8 relative z-20">
                 <form onSubmit={handleBookingSubmit} className="space-y-6">

                    {/* Main Card */}
                    <div className="bg-white dark:bg-slate-900 p-5 rounded-2xl shadow-lg border border-slate-100 dark:border-slate-800 space-y-6">

                        {/* Role Toggle */}
                        {isRentedFlat && (
                            <div className="bg-slate-100 dark:bg-slate-800 p-1.5 rounded-xl flex relative">
                                <button 
                                    type="button"
                                    onClick={() => toggleBookingFor('OWNER')}
                                    className={`flex-1 py-2.5 text-sm font-bold rounded-lg transition-all z-10 ${bookingFor === 'OWNER' ? 'text-slate-800 dark:text-slate-900 shadow-sm bg-white' : 'text-slate-500 dark:text-slate-400'}`}
                                >
                                    Owner
                                </button>
                                <button 
                                    type="button"
                                    onClick={() => toggleBookingFor('TENANT')}
                                    className={`flex-1 py-2.5 text-sm font-bold rounded-lg transition-all z-10 ${bookingFor === 'TENANT' ? 'text-slate-800 dark:text-slate-900 shadow-sm bg-white' : 'text-slate-500 dark:text-slate-400'}`}
                                >
                                    Tenant
                                </button>
                            </div>
                        )}

                        {/* Hall Selection */}
                        <div>
                           <label className="block text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider mb-3">Select Hall Type</label>
                           <div className="grid grid-cols-2 gap-3">
                              <button
                                type="button"
                                onClick={() => setHallType('BIG')}
                                className={`relative p-4 rounded-2xl border-2 text-left transition-all overflow-hidden ${hallType === 'BIG' ? 'border-purple-500 bg-purple-50 dark:bg-purple-900/20 dark:border-purple-500' : 'border-slate-100 dark:border-slate-700 bg-white dark:bg-slate-800 hover:border-slate-200 dark:hover:border-slate-600'}`}
                              >
                                <div className={`w-10 h-10 rounded-full flex items-center justify-center mb-3 ${hallType === 'BIG' ? 'bg-purple-500 text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-400 dark:text-slate-500'}`}>
                                    <PartyPopper size={20} />
                                </div>
                                <span className={`block font-bold ${hallType === 'BIG' ? 'text-purple-900 dark:text-purple-300' : 'text-slate-700 dark:text-slate-300'}`}>Big Hall</span>
                                <span className="text-[10px] text-slate-500 dark:text-slate-400">For large events</span>
                                {hallType === 'BIG' && <div className="absolute top-2 right-2 text-purple-600 dark:text-purple-400"><CheckCircle2 size={16} fill="currentColor" className="text-white dark:text-black" /></div>}
                              </button>

                              <button
                                type="button"
                                onClick={() => setHallType('SMALL')}
                                className={`relative p-4 rounded-2xl border-2 text-left transition-all overflow-hidden ${hallType === 'SMALL' ? 'border-amber-500 bg-amber-50 dark:bg-amber-900/20 dark:border-amber-500' : 'border-slate-100 dark:border-slate-700 bg-white dark:bg-slate-800 hover:border-slate-200 dark:hover:border-slate-600'}`}
                              >
                                <div className={`w-10 h-10 rounded-full flex items-center justify-center mb-3 ${hallType === 'SMALL' ? 'bg-amber-500 text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-400 dark:text-slate-500'}`}>
                                    <Home size={20} />
                                </div>
                                <span className={`block font-bold ${hallType === 'SMALL' ? 'text-amber-900 dark:text-amber-300' : 'text-slate-700 dark:text-slate-300'}`}>Small Hall</span>
                                <span className="text-[10px] text-slate-500 dark:text-slate-400">For small gatherings</span>
                                {hallType === 'SMALL' && <div className="absolute top-2 right-2 text-amber-600 dark:text-amber-400"><CheckCircle2 size={16} fill="currentColor" className="text-white dark:text-black" /></div>}
                              </button>
                           </div>
                        </div>

                        {/* Inputs */}
                        <div className="space-y-4">
                             <div>
                                <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-1 ml-1">Name</label>
                                <div className="relative group">
                                    <User size={18} className="absolute left-3 top-3.5 text-slate-400" />
                                    <input
                                        type="text"
                                        required
                                        value={ownerName}
                                        onChange={(e) => setOwnerName(e.target.value)}
                                        className="w-full pl-10 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-800 dark:text-white focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-700 outline-none transition-all font-medium"
                                        placeholder={bookingFor === 'TENANT' ? "Tenant Name" : "Owner Name"}
                                    />
                                </div>
                             </div>

                             <div>
                                <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-1 ml-1">Mobile</label>
                                <div className="relative group">
                                    <Phone size={18} className="absolute left-3 top-3.5 text-slate-400" />
                                    <input
                                        type="tel"
                                        required
                                        value={mobile}
                                        onChange={(e) => setMobile(e.target.value)}
                                        className="w-full pl-10 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-800 dark:text-white focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-700 outline-none transition-all font-medium"
                                        placeholder="Mobile Number"
                                    />
                                </div>
                             </div>

                             <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-1 ml-1">Date</label>
                                    <div className="relative group">
                                        <CalendarDays size={18} className="absolute left-3 top-3.5 text-slate-400" />
                                        <input
                                            type="date"
                                            required
                                            value={bookingDate}
                                            onChange={(e) => setBookingDate(e.target.value)}
                                            className="w-full pl-10 pr-2 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-800 dark:text-white focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-700 outline-none transition-all font-medium text-sm"
                                        />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-1 ml-1">Amount</label>
                                    <div className="relative group">
                                        <span className="absolute left-3 top-3 text-slate-400 font-bold">₹</span>
                                        <input
                                            type="number"
                                            required
                                            placeholder="0"
                                            value={amount}
                                            onChange={(e) => setAmount(Number(e.target.value))}
                                            className="w-full pl-8 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-800 dark:text-white focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-700 outline-none transition-all font-bold"
                                        />
                                    </div>
                                </div>
                             </div>
                        </div>

                        <button
                          type="submit"
                          className="w-full bg-slate-900 dark:bg-white text-white dark:text-black font-bold py-4 rounded-xl shadow-xl shadow-slate-300 dark:shadow-none active:scale-[0.98] transition-transform flex items-center justify-center"
                        >
                          <CheckCircle2 size={20} className="mr-2" />
                          Confirm Booking
                        </button>

                    </div>
                 </form>
             </div>
          </div>
        )}
      </div>
    );
  }

  // --- RENDER DASHBOARD (LIST) ---
  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-950">
       <div className="px-5 py-4 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-10 flex items-center justify-between shadow-sm transition-colors">
           <h2 className="text-xl font-bold text-slate-800 dark:text-white">Hall Bookings</h2>
           <button 
             onClick={() => { setMode('NEW_BOOKING'); resetForm(); }}
             className="bg-blue-600 text-white px-4 py-2 rounded-full text-xs font-bold flex items-center shadow-lg shadow-blue-200 dark:shadow-none hover:bg-blue-700 hover:scale-105 transition-all"
           >
             <Plus size={16} className="mr-1" />
             New
           </button>
       </div>

       <div className="flex-1 overflow-y-auto p-4 pb-24 space-y-4">
          {sortedBookings.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-[60vh] text-center p-6">
               <div className="w-24 h-24 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4">
                  <Calendar size={40} className="text-slate-300 dark:text-slate-600" />
               </div>
               <h3 className="text-lg font-bold text-slate-700 dark:text-slate-300 mb-1">No Bookings Found</h3>
               <p className="text-sm text-slate-400 max-w-[200px]">Tap the "New" button to book the hall for an event.</p>
            </div>
          ) : (
            sortedBookings.map(booking => {
              const isPast = new Date(booking.bookingDate) < new Date(new Date().toISOString().split('T')[0]);
              const { day, month } = getDateParts(booking.bookingDate);

              return (
                <div key={booking.id} className={`bg-white dark:bg-slate-900 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-800 overflow-hidden flex relative group ${isPast ? 'opacity-70 grayscale-[0.5]' : ''}`}>

                   {/* Left Date Strip */}
                   <div className={`w-20 flex flex-col items-center justify-center p-2 border-r border-dashed border-slate-200 dark:border-slate-800 ${booking.hallType === 'BIG' ? 'bg-purple-50 dark:bg-purple-900/20' : 'bg-amber-50 dark:bg-amber-900/20'}`}>
                      <span className={`text-[10px] font-black uppercase tracking-widest ${booking.hallType === 'BIG' ? 'text-purple-400' : 'text-amber-400'}`}>{month}</span>
                      <span className={`text-2xl font-black ${booking.hallType === 'BIG' ? 'text-purple-700 dark:text-purple-400' : 'text-amber-700 dark:text-amber-400'}`}>{day}</span>
                   </div>

                   {/* Main Content */}
                   <div className="flex-1 p-4 relative">
                      {/* Status Badge */}
                      <div className="absolute top-3 right-3">
                          {isPast ? (
                              <span className="bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 text-[10px] font-bold px-2 py-1 rounded-full">DONE</span>
                          ) : (
                              <span className="bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 text-[10px] font-bold px-2 py-1 rounded-full animate-pulse">UPCOMING</span>
                          )}
                      </div>

                      <div className="mb-3">
                          <div className="flex items-center gap-2 mb-1">
                             <span className={`text-[10px] font-bold px-2 py-0.5 rounded border uppercase tracking-wider ${booking.hallType === 'BIG' ? 'bg-purple-100 dark:bg-purple-900/30 text-purple-700 dark:text-purple-400 border-purple-200 dark:border-purple-800' : 'bg-amber-100 dark:bg-amber-900/30 text-amber-700 dark:text-amber-400 border-amber-200 dark:border-amber-800'}`}>
                                {booking.hallType} HALL
                             </span>
                          </div>
                          <h3 className="text-lg font-bold text-slate-800 dark:text-white">{booking.flatNumber}</h3>

                          <div className="flex flex-col gap-1 mt-1">
                             <div className="flex items-center text-xs text-slate-500 dark:text-slate-400 font-medium">
                                <User size={12} className="mr-1.5 text-slate-400 dark:text-slate-500" />
                                {booking.ownerName}
                             </div>
                             {booking.mobile && (
                                <div className="flex items-center text-xs text-slate-500 dark:text-slate-400">
                                    <Phone size={12} className="mr-1.5 text-slate-400 dark:text-slate-500" />
                                    {booking.mobile}
                                </div>
                             )}
                          </div>
                      </div>

                      <div className="flex items-center justify-between pt-3 border-t border-slate-50 dark:border-slate-800 mt-2">
                          <span className="font-bold text-slate-700 dark:text-slate-300">{formatCurrency(booking.amount)}</span>

                          <div className="flex space-x-2">
                             {booking.mobile && (
                               <a 
                                 href={generateWhatsAppReceipt(booking)}
                                 target="_blank"
                                 rel="noreferrer"
                                 className="w-8 h-8 flex items-center justify-center bg-green-50 dark:bg-green-900/30 text-green-600 dark:text-green-400 rounded-full hover:bg-green-500 hover:text-white transition-all shadow-sm"
                               >
                                  <Share2 size={14} />
                               </a>
                             )}
                             <button 
                               onClick={() => handleDelete(booking.id)}
                               className="w-8 h-8 flex items-center justify-center bg-red-50 dark:bg-red-900/30 text-red-600 dark:text-red-400 rounded-full hover:bg-red-500 hover:text-white transition-all shadow-sm"
                             >
                                <Trash2 size={14} />
                             </button>
                          </div>
                      </div>
                   </div>

                   {/* Decorative circle notches for ticket effect */}
                   <div className="absolute top-[-6px] left-[76px] w-3 h-3 bg-slate-50 dark:bg-slate-950 rounded-full shadow-inner z-10"></div>
                   <div className="absolute bottom-[-6px] left-[76px] w-3 h-3 bg-slate-50 dark:bg-slate-950 rounded-full shadow-inner z-10"></div>

                </div>
              );
            })
          )}
       </div>
    </div>
  );
};

export default HallBooking;

import React, { useState, useEffect } from 'react';
import { AppState, FinancialRecord } from '../types';
import { addFinancialRecord, updateFinancialRecord } from '../services/storageService';
import { parseFinancialText } from '../services/geminiService';
import { Sparkles, X, Plus, ArrowRightLeft } from 'lucide-react';
import { getTodayDateString } from '../utils/helpers';

interface FinanceFormProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
  onClose: () => void;
  recordToEdit?: FinancialRecord | null;
}

const FinanceForm: React.FC<FinanceFormProps> = ({ state, refreshState, onClose, recordToEdit }) => {
  const [type, setType] = useState<'INCOME' | 'EXPENSE' | 'TRANSFER'>('EXPENSE');
  const [paymentMode, setPaymentMode] = useState<'CASH' | 'BANK'>('CASH');
  const [date, setDate] = useState(getTodayDateString());
  const [amount, setAmount] = useState<number | ''>('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');

  // AI State
  const [aiInput, setAiInput] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  useEffect(() => {
    if (recordToEdit) {
      setType(recordToEdit.type);
      setPaymentMode(recordToEdit.paymentMode || 'CASH');
      try {
        setDate(new Date(recordToEdit.date).toISOString().split('T')[0]);
      } catch(e) {
        setDate(getTodayDateString());
      }
      setAmount(recordToEdit.amount);
      setCategory(recordToEdit.category);
      setDescription(recordToEdit.description);
    }
  }, [recordToEdit]);

  const handleAiQuickFill = async () => {
    if (!aiInput.trim()) return;
    setIsAiLoading(true);
    const result = await parseFinancialText(aiInput);
    setIsAiLoading(false);

    if (result) {
      if (result.type) setType(result.type.toUpperCase() as any);
      if (result.amount) setAmount(result.amount);
      if (result.date) setDate(result.date);
      if (result.category) setCategory(result.category);
      if (result.description) setDescription(result.description);
      if (result.paymentMode) setPaymentMode(result.paymentMode.toUpperCase() as any);
    } else {
      alert("Could not understand the text. Please try again.");
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!amount) return;

    if (recordToEdit) {
      const newState = updateFinancialRecord(state, recordToEdit.id, {
        type,
        paymentMode,
        date,
        amount: Number(amount),
        category: type === 'TRANSFER' ? 'Internal Transfer' : category,
        description
      });
      refreshState(newState);
    } else {
      const newState = addFinancialRecord(state, {
        type,
        paymentMode,
        date,
        amount: Number(amount),
        category: type === 'TRANSFER' ? 'Internal Transfer' : category,
        description
      });
      refreshState(newState);
    }
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white dark:bg-slate-900 w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom duration-300">

        {/* Header */}
        <div className="px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center">
           <h3 className="font-bold text-xl text-slate-800 dark:text-white">{recordToEdit ? 'Edit Record' : 'New Transaction'}</h3>
           <button onClick={onClose} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 transition-colors"><X size={24} /></button>
        </div>

        <div className="p-6 space-y-6">

           {/* AI Quick Fill Section */}
           {!recordToEdit && (
             <div className="bg-blue-50 dark:bg-blue-900/20 p-4 rounded-xl border border-blue-100 dark:border-blue-900/30">
                <label className="text-sm font-semibold text-blue-800 dark:text-blue-300 flex items-center mb-2">
                   <Sparkles size={16} className="mr-2 text-blue-600 dark:text-blue-400" />
                   AI Quick Fill
                </label>
                <div className="flex gap-2">
                   <input 
                      type="text" 
                      value={aiInput}
                      onChange={(e) => setAiInput(e.target.value)}
                      placeholder='e.g., "Paid 5000 Cash for repairs"'
                      className="flex-1 text-sm px-3 py-2.5 rounded-lg border border-blue-200 dark:border-blue-800 focus:outline-none focus:border-blue-500 bg-white dark:bg-slate-800 dark:text-white placeholder:text-slate-400"
                   />
                   <button 
                      onClick={handleAiQuickFill}
                      disabled={isAiLoading}
                      className="bg-blue-500 text-white text-sm font-semibold px-4 py-2 rounded-lg shadow-sm hover:bg-blue-600 disabled:opacity-50 transition-colors whitespace-nowrap"
                   >
                      {isAiLoading ? '...' : 'Auto-Fill'}
                   </button>
                </div>
             </div>
           )}

           <form onSubmit={handleSubmit} className="space-y-5">

              {/* Type Selection */}
              <div>
                 <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Transaction Type</label>
                 <div className="flex rounded-lg border border-slate-200 dark:border-slate-700 p-1 bg-white dark:bg-slate-800">
                    <button
                       type="button"
                       onClick={() => setType('INCOME')}
                       className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${
                          type === 'INCOME' 
                          ? 'bg-emerald-50 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800 shadow-sm' 
                          : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                       }`}
                    >
                       Income
                    </button>
                    <button
                       type="button"
                       onClick={() => setType('EXPENSE')}
                       className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ml-1 ${
                          type === 'EXPENSE' 
                          ? 'bg-red-50 dark:bg-red-900/30 text-red-700 dark:text-red-300 border border-red-200 dark:border-red-800 shadow-sm' 
                          : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                       }`}
                    >
                       Expense
                    </button>
                    <button
                       type="button"
                       onClick={() => setType('TRANSFER')}
                       className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ml-1 ${
                          type === 'TRANSFER' 
                          ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 border border-blue-200 dark:border-blue-800 shadow-sm' 
                          : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                       }`}
                    >
                       Transfer
                    </button>
                 </div>
              </div>

              {/* Payment Mode (or Source for Transfer) */}
              <div>
                 <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">
                    {type === 'TRANSFER' ? 'Transfer From (Source)' : 'Payment Mode'}
                 </label>
                 <div className="flex rounded-lg border border-slate-200 dark:border-slate-700 p-1 bg-white dark:bg-slate-800">
                    <button
                       type="button"
                       onClick={() => setPaymentMode('CASH')}
                       className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${
                          paymentMode === 'CASH' 
                          ? 'bg-slate-800 dark:bg-slate-200 text-white dark:text-black shadow-sm' 
                          : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                       }`}
                    >
                       CASH
                    </button>
                    <button
                       type="button"
                       onClick={() => setPaymentMode('BANK')}
                       className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ml-1 ${
                          paymentMode === 'BANK' 
                          ? 'bg-slate-800 dark:bg-slate-200 text-white dark:text-black shadow-sm' 
                          : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                       }`}
                    >
                       BANK
                    </button>
                 </div>
                 {type === 'TRANSFER' && (
                     <div className="mt-2 text-xs text-center text-slate-500 dark:text-slate-400 flex items-center justify-center">
                        <ArrowRightLeft size={12} className="mr-1" />
                        Transferring to <strong>{paymentMode === 'CASH' ? 'BANK' : 'CASH'}</strong>
                     </div>
                 )}
              </div>

              {/* Amount & Date */}
              <div className="grid grid-cols-2 gap-6">
                 <div>
                    <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Date</label>
                    <input 
                      type="date"
                      required
                      value={date}
                      onChange={(e) => setDate(e.target.value)}
                      className="w-full px-3 py-2.5 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg text-slate-800 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none transition-all" 
                    />
                 </div>
                 <div>
                    <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Amount (₹)</label>
                    <input 
                      type="number"
                      required
                      placeholder="0.00"
                      value={amount}
                      onChange={(e) => setAmount(e.target.value ? Number(e.target.value) : '')}
                      className="w-full px-3 py-2.5 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg text-slate-800 dark:text-white placeholder:text-slate-400 dark:placeholder:text-slate-500 focus:ring-2 focus:ring-blue-500 outline-none transition-all" 
                    />
                 </div>
              </div>

              {/* Category (Hidden for Transfer) */}
              {type !== 'TRANSFER' && (
                 <div>
                    <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Category</label>
                    <input 
                      type="text"
                      required={type !== 'TRANSFER'}
                      list="categories"
                      placeholder="Select or type category"
                      value={category}
                      onChange={(e) => setCategory(e.target.value)}
                      className="w-full px-3 py-3 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg text-slate-800 dark:text-white placeholder:text-slate-400 dark:placeholder:text-slate-500 focus:ring-2 focus:ring-blue-500 outline-none transition-all" 
                    />
                    <datalist id="categories">
                       <option value="Maintenance" />
                       <option value="Water Tanker" />
                       <option value="Electricity" />
                       <option value="Security Salary" />
                       <option value="Cleaning" />
                       <option value="Repairs" />
                       <option value="Festival" />
                       <option value="Stationery" />
                       <option value="Legal" />
                       <option value="Miscellaneous" />
                    </datalist>
                 </div>
              )}

              {/* Description */}
              <div>
                 <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Description</label>
                 <input 
                   type="text"
                   placeholder={type === 'TRANSFER' ? "e.g., Deposit to Bank" : "Brief description"}
                   value={description}
                   onChange={(e) => setDescription(e.target.value)}
                   className="w-full px-3 py-3 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg text-slate-800 dark:text-white placeholder:text-slate-400 dark:placeholder:text-slate-500 focus:ring-2 focus:ring-blue-500 outline-none transition-all" 
                 />
              </div>

              {/* Footer Buttons */}
              <div className="flex items-center justify-end gap-3 pt-4 border-t border-slate-50 dark:border-slate-800 mt-2">
                 <button
                    type="button"
                    onClick={onClose}
                    className="px-6 py-3 rounded-lg border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-300 font-semibold hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors"
                 >
                    Cancel
                 </button>
                 <button 
                    type="submit"
                    className="px-6 py-3 bg-blue-600 text-white font-semibold rounded-lg shadow-md shadow-blue-200 dark:shadow-none hover:bg-blue-700 active:scale-95 transition-all flex items-center"
                 >
                    <Plus size={18} className="mr-2" />
                    {recordToEdit ? 'Update' : type === 'TRANSFER' ? 'Transfer Funds' : 'Add Transaction'}
                 </button>
              </div>

           </form>
        </div>

      </div>
    </div>
  );
};

