                        <input type="tel" required value={mobile} onChange={(e) => setMobile(e.target.value)} placeholder="Mobile" className="w-full px-4 py-3.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl dark:text-white focus:ring-2 focus:ring-blue-500 outline-none" />
                        <div className="grid grid-cols-2 gap-4">
