                            <input type="number" required placeholder="Amount" value={amount} onChange={(e) => setAmount(Number(e.target.value))} className="w-full px-3 py-3.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-bold" />
