import React, { useState, useMemo, useEffect } from 'react';
import { AppState, HallBooking as HallBookingType } from '../types';
import { addHallBooking, deleteHallBooking, updateHallBookingDetails } from '../services/storageService';
import { formatDate, formatCurrency, getTodayDateString } from '../utils/helpers';
import { Search, Plus, Calendar, Trash2, Share2, ArrowRight, User, Phone, PartyPopper, Home, CheckCircle2, X, Edit2, CalendarDays } from 'lucide-react';
import { BUILDING_NAME } from '../constants';

interface HallBookingProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
}

type Mode = 'DASHBOARD' | 'FORM';

const HallBooking: React.FC<HallBookingProps> = ({ state, refreshState }) => {
  const [mode, setMode] = useState<Mode>('DASHBOARD');

  // Form State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [step, setStep] = useState<1 | 2>(1);
  const [selectedFlatId, setSelectedFlatId] = useState<string | null>(null);

  const [ownerName, setOwnerName] = useState(''); 
  const [mobile, setMobile] = useState('');
  const [hallType, setHallType] = useState<'BIG' | 'SMALL'>('BIG');
  const [bookingDate, setBookingDate] = useState(getTodayDateString());
  const [amount, setAmount] = useState<number | ''>('');

  const filteredFlats = useMemo(() => {
    if (!searchTerm) return [];
    return state.flats.filter(flat => 
      flat.flatNumber.toLowerCase().includes(searchTerm.toLowerCase()) || 
      flat.ownerName.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [state.flats, searchTerm]);

  const sortedBookings = useMemo(() => {
    return [...(state.hallBookings || [])].sort((a,b) => b.bookingDate.localeCompare(a.bookingDate));
  }, [state.hallBookings]);

  const handleSelectFlat = (flatId: string) => {
    const flat = state.flats.find(f => f.id === flatId);
    if (flat) {
      setSelectedFlatId(flatId);
      setOwnerName(flat.ownerName || '');
      setMobile(flat.mobile || '');
      setStep(2);
    }
  };

  const startEdit = (booking: HallBookingType) => {
    setEditingId(booking.id);
    setSelectedFlatId(booking.flatId);
    setOwnerName(booking.ownerName);
    setMobile(booking.mobile);
    setHallType(booking.hallType);
    setBookingDate(booking.bookingDate);
    setAmount(booking.amount);
    setStep(2);
    setMode('FORM');
  };

  const handleBookingSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedFlatId || amount === '') return;

    const flat = state.flats.find(f => f.id === selectedFlatId);
    if (!flat) return;

    if (editingId) {
      const newState = updateHallBookingDetails(state, editingId, {
        ownerName,
        mobile,
        hallType,
        bookingDate,
        amount: Number(amount)
      });
      refreshState(newState);
    } else {
      const newState = addHallBooking(state, {
        flatId: selectedFlatId,
        flatNumber: flat.flatNumber,
        ownerName, 
        mobile,
        hallType,
        bookingDate,
        amount: Number(amount)
      });
      refreshState(newState);
    }

    setMode('DASHBOARD');
    resetForm();
  };

  const handleDelete = (id: string) => {
    if (window.confirm("Are you sure you want to delete this booking entry?")) {
      const newState = deleteHallBooking(state, id);
      refreshState(newState);
    }
  };

  const resetForm = () => {
    setStep(1);
    setSearchTerm('');
    setSelectedFlatId(null);
    setEditingId(null);
    setOwnerName('');
    setMobile('');
    setHallType('BIG');
    setBookingDate(getTodayDateString());
    setAmount('');
  };

  const generateWhatsAppReceipt = (booking: HallBookingType) => {
    const cleanMobile = booking.mobile.replace(/\D/g, '');
    const phone = cleanMobile.length === 10 ? '91' + cleanMobile : cleanMobile;
    const message = `*HALL BOOKING CONFIRMED*\n${BUILDING_NAME}\n\nDear *${booking.ownerName}*,\n\nYour booking for *${booking.hallType} HALL* is confirmed.\n\nFlat: *${booking.flatNumber}*\nDate: *${formatDate(booking.bookingDate)}*\nAmount: *${formatCurrency(booking.amount)}*\n\nThank you!`;
    return `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;
  };

  if (mode === 'FORM') {
    return (
      <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-950 transition-colors">
        <div className="bg-white dark:bg-slate-900 px-4 py-4 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-20 flex justify-between items-center shadow-sm">
           <button onClick={() => { setMode('DASHBOARD'); resetForm(); }} className="text-slate-500 hover:text-slate-800 dark:hover:text-white p-1">
             <X size={24} />
           </button>
           <h2 className="text-lg font-bold text-slate-800 dark:text-white">{editingId ? 'Edit Booking' : 'New Booking'}</h2>
           <div className="w-8"></div>
        </div>

        {step === 1 ? (
          <div className="p-5 flex-1 overflow-y-auto">
             <div className="relative mb-6">
                <Search className="absolute left-4 top-3.5 text-blue-500" size={20} />
                <input
                  type="text"
                  placeholder="Search flat..."
                  className="w-full pl-11 pr-4 py-3.5 rounded-2xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
             <div className="space-y-3 pb-24">
               {filteredFlats.map(flat => (
                 <button key={flat.id} onClick={() => handleSelectFlat(flat.id)} className="w-full flex justify-between items-center p-4 bg-white dark:bg-slate-900 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm active:scale-[0.98] transition-all">
                    <div className="text-left">
                        <span className="text-lg font-bold text-slate-800 dark:text-white block leading-tight">{flat.flatNumber}</span>
                        <span className="text-xs text-slate-500 dark:text-slate-400 mt-1">{flat.ownerName}</span>
                    </div>
                    <ArrowRight size={20} className="text-slate-300" />
                 </button>
               ))}
             </div>
          </div>
        ) : (
          <div className="p-5 flex-1 overflow-y-auto pb-24">
             <form onSubmit={handleBookingSubmit} className="space-y-6">
                <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl shadow-lg border border-slate-100 dark:border-slate-800 space-y-6 transition-colors">
                    <div className="flex justify-between items-center bg-blue-50 dark:bg-blue-900/20 p-5 rounded-xl border border-blue-100 dark:border-blue-800/50">
                        <div>
                            <p className="text-[10px] text-blue-600 dark:text-blue-400 font-black uppercase tracking-widest mb-1">Target Unit</p>
                            <p className="text-3xl font-black text-blue-900 dark:text-blue-100 leading-none">
                              {state.flats.find(f => f.id === selectedFlatId)?.flatNumber}
                            </p>
                        </div>
                        {!editingId && <button type="button" onClick={() => setStep(1)} className="text-xs font-bold text-blue-600 dark:text-blue-400 underline decoration-2 underline-offset-4">Change</button>}
                    </div>

                    <div>
                       <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Facility Choice</label>
                       <div className="grid grid-cols-2 gap-3">
                          <button type="button" onClick={() => setHallType('BIG')} className={`p-4 rounded-2xl border-2 transition-all flex flex-col items-center justify-center ${hallType === 'BIG' ? 'border-purple-500 bg-purple-50 dark:bg-purple-900/30' : 'border-slate-100 dark:border-slate-800 grayscale opacity-60'}`}>
                            <PartyPopper size={28} className={hallType === 'BIG' ? 'text-purple-600' : 'text-slate-400'} />
                            <span className="block font-bold mt-2 dark:text-white text-sm">Big Hall</span>
                          </button>
                          <button type="button" onClick={() => setHallType('SMALL')} className={`p-4 rounded-2xl border-2 transition-all flex flex-col items-center justify-center ${hallType === 'SMALL' ? 'border-amber-500 bg-amber-50 dark:bg-amber-900/30' : 'border-slate-100 dark:border-slate-800 grayscale opacity-60'}`}>
                            <Home size={28} className={hallType === 'SMALL' ? 'text-amber-600' : 'text-slate-400'} />
                            <span className="block font-bold mt-2 dark:text-white text-sm">Small Hall</span>
                          </button>
                       </div>
                    </div>

                    <div className="space-y-4">
                        <div className="space-y-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Contact Person</label>
                          <input type="text" required value={ownerName} onChange={(e) => setOwnerName(e.target.value)} placeholder="Full Name" className="w-full px-4 py-3.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-medium" />
                        </div>
                        <div className="space-y-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Mobile Number</label>
                          <input type="tel" required value={mobile} onChange={(e) => setMobile(e.target.value)} placeholder="10 Digit Mobile" className="w-full px-4 py-3.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-medium" />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Event Date</label>
                              <input type="date" required value={bookingDate} onChange={(e) => setBookingDate(e.target.value)} className="w-full px-3 py-3.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl dark:text-white focus:ring-2 focus:ring-blue-500 outline-none text-sm font-bold" />
                            </div>
                            <div className="space-y-2">
                              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Booking Fee</label>
                              <input type="number" required placeholder="Amount" value={amount} onChange={(e) => setAmount(e.target.value === '' ? '' : Number(e.target.value))} className="w-full px-3 py-3.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-bold" />
                            </div>
                        </div>
                    </div>

                    <button type="submit" className="w-full bg-slate-900 dark:bg-white text-white dark:text-black font-black py-4 rounded-xl active:scale-[0.98] transition-transform flex items-center justify-center shadow-lg uppercase tracking-widest text-sm">
                      <CheckCircle2 size={20} className="mr-2" />
                      {editingId ? 'Update Booking' : 'Confirm Reservation'}
                    </button>
                </div>
             </form>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-950 transition-colors">
       <div className="px-6 py-4 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-10 flex items-center justify-between shadow-sm">
           <h2 className="text-xl font-bold text-slate-800 dark:text-white">Hall Bookings</h2>
           <button onClick={() => { setMode('FORM'); resetForm(); }} className="bg-blue-600 text-white px-5 py-2.5 rounded-full text-xs font-black uppercase tracking-widest flex items-center shadow-lg transition-transform active:scale-95">
             <Plus size={16} className="mr-1" strokeWidth={3} /> Book
           </button>
       </div>

       <div className="flex-1 overflow-y-auto p-4 pb-24 space-y-4">
          {sortedBookings.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-[60vh] text-center p-6">
               <div className="w-16 h-16 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4">
                  <Calendar size={32} className="text-slate-300" />
               </div>
               <p className="text-slate-400 text-sm font-medium">No facility reservations found.</p>
            </div>
          ) : (
            sortedBookings.map(booking => (
                <div key={booking.id} className="bg-white dark:bg-slate-900 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-800 overflow-hidden flex relative transition-colors">
                   <div className={`w-1.5 flex-shrink-0 ${booking.hallType === 'BIG' ? 'bg-purple-500' : 'bg-amber-500'}`}></div>
                   <div className="flex-1 p-5">
                      <div className="flex justify-between items-start mb-3">
                          <span className={`text-[9px] font-black px-2 py-0.5 rounded-full border tracking-widest uppercase ${booking.hallType === 'BIG' ? 'bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400 border-purple-200 dark:border-purple-800' : 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400 border-amber-200 dark:border-amber-800'}`}>
                             {booking.hallType} HALL
                          </span>
                          <div className="flex items-center text-xs font-bold text-slate-400">
                             <CalendarDays size={12} className="mr-1" />
                             {formatDate(booking.bookingDate)}
                          </div>
                      </div>

                      <div className="mb-4">
                        <h3 className="text-2xl font-black text-slate-800 dark:text-white leading-none mb-1">{booking.flatNumber}</h3>
                        <p className="text-sm font-medium text-slate-500 dark:text-slate-400">{booking.ownerName}</p>
                      </div>

                      <div className="flex items-center justify-between pt-4 border-t border-slate-50 dark:border-slate-800">
                          <div className="flex flex-col">
                             <span className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Amount Paid</span>
                             <span className="text-lg font-black text-slate-700 dark:text-slate-200">{formatCurrency(booking.amount)}</span>
                          </div>
                          <div className="flex space-x-3">
                             {/* EDIT BUTTON */}
                             <button onClick={() => startEdit(booking)} className="w-9 h-9 flex items-center justify-center bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-xl hover:bg-blue-500 hover:text-white transition-all shadow-sm active:scale-90" title="Edit Booking">
                                <Edit2 size={16} strokeWidth={2.5} />
                             </button>

                             {/* WHATSAPP BUTTON */}
                             {booking.mobile && (
                               <a href={generateWhatsAppReceipt(booking)} target="_blank" rel="noreferrer" className="w-9 h-9 flex items-center justify-center bg-green-50 dark:bg-green-900/20 text-green-600 dark:text-green-400 rounded-xl hover:bg-green-500 hover:text-white transition-all shadow-sm active:scale-90" title="Share Receipt">
                                  <Share2 size={16} strokeWidth={2.5} />
                               </a>
                             )}

                             {/* DELETE BUTTON */}
                             <button onClick={() => handleDelete(booking.id)} className="w-9 h-9 flex items-center justify-center bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded-xl hover:bg-red-500 hover:text-white transition-all shadow-sm active:scale-90" title="Delete Entry">
                                <Trash2 size={16} strokeWidth={2.5} />
                             </button>
                          </div>
                      </div>
                   </div>
                </div>
            ))
          )}
       </div>
    </div>
  );
};

export default HallBooking;

import React, { useState, useMemo } from 'react';
import { AppState, HallBooking as HallBookingType } from '../types';
import { addHallBooking, deleteHallBooking, updateHallBookingDetails } from '../services/storageService';
import { formatDate, formatCurrency, getTodayDateString } from '../utils/helpers';
import { Search, Plus, Calendar, Trash2, Share2, ArrowRight, PartyPopper, Home, CheckCircle2, X, Edit2, CalendarDays } from 'lucide-react';
import { BUILDING_NAME } from '../constants';

interface HallBookingProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
}

type Mode = 'DASHBOARD' | 'FORM';

const HallBooking: React.FC<HallBookingProps> = ({ state, refreshState }) => {
  const [mode, setMode] = useState<Mode>('DASHBOARD');

  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [step, setStep] = useState<1 | 2>(1);
  const [selectedFlatId, setSelectedFlatId] = useState<string | null>(null);

  const [ownerName, setOwnerName] = useState(''); 
  const [mobile, setMobile] = useState('');
  const [hallType, setHallType] = useState<'BIG' | 'SMALL'>('BIG');
  const [bookingDate, setBookingDate] = useState(getTodayDateString());
  const [amount, setAmount] = useState<number | ''>('');

  const filteredFlats = useMemo(() => {
    if (!searchTerm) return [];
    return state.flats.filter(flat => 
      flat.flatNumber.toLowerCase().includes(searchTerm.toLowerCase()) || 
      flat.ownerName.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [state.flats, searchTerm]);

  const sortedBookings = useMemo(() => {
    return [...(state.hallBookings || [])].sort((a,b) => b.bookingDate.localeCompare(a.bookingDate));
  }, [state.hallBookings]);

  const handleSelectFlat = (flatId: string) => {
    const flat = state.flats.find(f => f.id === flatId);
    if (flat) {
      setSelectedFlatId(flatId);
      setOwnerName(flat.ownerName || '');
      setMobile(flat.mobile || '');
      setStep(2);
    }
  };

  const startEdit = (booking: HallBookingType) => {
    setEditingId(booking.id);
    setSelectedFlatId(booking.flatId);
    setOwnerName(booking.ownerName);
    setMobile(booking.mobile);
    setHallType(booking.hallType);
    setBookingDate(booking.bookingDate);
    setAmount(booking.amount);
    setStep(2);
    setMode('FORM');
  };

  const handleBookingSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedFlatId || amount === '') return;

    const flat = state.flats.find(f => f.id === selectedFlatId);
    if (!flat) return;

    if (editingId) {
      const newState = updateHallBookingDetails(state, editingId, {
        ownerName,
        mobile,
        hallType,
        bookingDate,
        amount: Number(amount)
      });
      refreshState(newState);
    } else {
      const newState = addHallBooking(state, {
        flatId: selectedFlatId,
        flatNumber: flat.flatNumber,
        ownerName, 
        mobile,
        hallType,
        bookingDate,
        amount: Number(amount)
      });
      refreshState(newState);
    }

    setMode('DASHBOARD');
    resetForm();
  };

  const handleDelete = (id: string) => {
    if (window.confirm("Are you sure you want to delete this booking entry?")) {
      const newState = deleteHallBooking(state, id);
      refreshState(newState);
    }
  };

  const resetForm = () => {
    setStep(1);
    setSearchTerm('');
    setSelectedFlatId(null);
    setEditingId(null);
    setOwnerName('');
    setMobile('');
    setHallType('BIG');
    setBookingDate(getTodayDateString());
    setAmount('');
  };

  const generateWhatsAppReceipt = (booking: HallBookingType) => {
    const cleanMobile = booking.mobile.replace(/\D/g, '');
    const phone = cleanMobile.length === 10 ? '91' + cleanMobile : cleanMobile;
    const message = `*HALL BOOKING CONFIRMED*\n${BUILDING_NAME}\n\nDear *${booking.ownerName}*,\n\nYour booking for *${booking.hallType} HALL* is confirmed.\n\nFlat: *${booking.flatNumber}*\nDate: *${formatDate(booking.bookingDate)}*\nAmount: *${formatCurrency(booking.amount)}*\n\nThank you!`;
    return `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;
  };

  const getEventStatus = (dateStr: string) => {
    const today = getTodayDateString();
    return dateStr >= today ? 'SCHEDULED' : 'FINISHED';
  };

  const parseDateParts = (dateStr: string) => {
    const date = new Date(dateStr);
    return {
      day: date.getDate(),
      month: date.toLocaleDateString('en-IN', { month: 'short' }).toUpperCase(),
      year: date.getFullYear()
    };
  };

  if (mode === 'FORM') {
    return (
      <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-950 transition-colors">
        <div className="bg-white dark:bg-slate-900 px-4 py-4 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-20 flex justify-between items-center shadow-sm">
           <button onClick={() => { setMode('DASHBOARD'); resetForm(); }} className="text-slate-500 hover:text-slate-800 dark:hover:text-white p-1">
             <X size={24} />
           </button>
           <h2 className="text-lg font-bold text-slate-800 dark:text-white">{editingId ? 'Edit Booking' : 'New Booking'}</h2>
           <div className="w-8"></div>
        </div>

        {step === 1 ? (
          <div className="p-5 flex-1 overflow-y-auto">
             <div className="relative mb-6">
                <Search className="absolute left-4 top-3.5 text-blue-500" size={20} />
                <input
                  type="text"
                  placeholder="Search flat..."
                  className="w-full pl-11 pr-4 py-3.5 rounded-2xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500 shadow-sm transition-all"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
             <div className="space-y-3 pb-24">
               {filteredFlats.map(flat => (
                 <button key={flat.id} onClick={() => handleSelectFlat(flat.id)} className="w-full flex justify-between items-center p-4 bg-white dark:bg-slate-900 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm active:scale-[0.98] transition-all">
                    <div className="text-left">
                        <span className="text-lg font-bold text-slate-800 dark:text-white block leading-tight">{flat.flatNumber}</span>
                        <span className="text-xs text-slate-500 dark:text-slate-400 mt-1">{flat.ownerName}</span>
                    </div>
                    <ArrowRight size={20} className="text-slate-300" />
                 </button>
               ))}
             </div>
          </div>
        ) : (
          <div className="p-5 flex-1 overflow-y-auto pb-24">
             <form onSubmit={handleBookingSubmit} className="space-y-6">
                <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl shadow-lg border border-slate-100 dark:border-slate-800 space-y-6 transition-colors">
                    <div className="flex justify-between items-center bg-blue-50 dark:bg-blue-900/20 p-5 rounded-xl border border-blue-100 dark:border-blue-800/50">
                        <div>
                            <p className="text-[10px] text-blue-600 dark:text-blue-400 font-black uppercase tracking-widest mb-1">Target Unit</p>
                            <p className="text-3xl font-black text-blue-900 dark:text-blue-100 leading-none">
                              {state.flats.find(f => f.id === selectedFlatId)?.flatNumber}
                            </p>
                        </div>
                        {!editingId && <button type="button" onClick={() => setStep(1)} className="text-xs font-bold text-blue-600 dark:text-blue-400 underline decoration-2 underline-offset-4">Change</button>}
                    </div>

                    <div>
                       <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Facility Choice</label>
                       <div className="grid grid-cols-2 gap-3">
                          <button type="button" onClick={() => setHallType('BIG')} className={`p-4 rounded-2xl border-2 transition-all flex flex-col items-center justify-center ${hallType === 'BIG' ? 'border-purple-500 bg-purple-50 dark:bg-purple-900/30' : 'border-slate-100 dark:border-slate-800 grayscale opacity-60'}`}>
                            <PartyPopper size={28} className={hallType === 'BIG' ? 'text-purple-600' : 'text-slate-400'} />
                            <span className="block font-bold mt-2 dark:text-white text-sm">Big Hall</span>
                          </button>
                          <button type="button" onClick={() => setHallType('SMALL')} className={`p-4 rounded-2xl border-2 transition-all flex flex-col items-center justify-center ${hallType === 'SMALL' ? 'border-amber-500 bg-amber-50 dark:bg-amber-900/30' : 'border-slate-100 dark:border-slate-800 grayscale opacity-60'}`}>
                            <Home size={28} className={hallType === 'SMALL' ? 'text-amber-600' : 'text-slate-400'} />
                            <span className="block font-bold mt-2 dark:text-white text-sm">Small Hall</span>
                          </button>
                       </div>
                    </div>

                    <div className="space-y-4">
                        <div className="space-y-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Contact Person</label>
                          <input type="text" required value={ownerName} onChange={(e) => setOwnerName(e.target.value)} placeholder="Full Name" className="w-full px-4 py-3.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-medium" />
                        </div>
                        <div className="space-y-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Mobile Number</label>
                          <input type="tel" required value={mobile} onChange={(e) => setMobile(e.target.value)} placeholder="10 Digit Mobile" className="w-full px-4 py-3.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-medium" />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Event Date</label>
                              <input type="date" required value={bookingDate} onChange={(e) => setBookingDate(e.target.value)} className="w-full px-3 py-3.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl dark:text-white focus:ring-2 focus:ring-blue-500 outline-none text-sm font-bold" />
                            </div>
                            <div className="space-y-2">
                              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Booking Fee</label>
                              <input type="number" required placeholder="Amount" value={amount} onChange={(e) => setAmount(e.target.value === '' ? '' : Number(e.target.value))} className="w-full px-3 py-3.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-bold" />
                            </div>
                        </div>
                    </div>

                    <button type="submit" className="w-full bg-slate-900 dark:bg-white text-white dark:text-black font-black py-4 rounded-xl active:scale-[0.98] transition-transform flex items-center justify-center shadow-lg uppercase tracking-widest text-sm">
                      <CheckCircle2 size={20} className="mr-2" />
                      {editingId ? 'Update Booking' : 'Confirm Reservation'}
                    </button>
                </div>
             </form>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-950 transition-colors">
       <div className="px-6 py-4 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-10 flex items-center justify-between shadow-sm">
           <h2 className="text-xl font-bold text-slate-800 dark:text-white">Hall Bookings</h2>
           <button onClick={() => { setMode('FORM'); resetForm(); }} className="bg-blue-600 text-white px-5 py-2.5 rounded-full text-xs font-black uppercase tracking-widest flex items-center shadow-lg transition-transform active:scale-95">
             <Plus size={16} className="mr-1" strokeWidth={3} /> Book
           </button>
       </div>

       <div className="flex-1 overflow-y-auto p-4 pb-24 space-y-4">
          {sortedBookings.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-[60vh] text-center p-6">
               <div className="w-16 h-16 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4">
                  <Calendar size={32} className="text-slate-300" />
               </div>
               <p className="text-slate-400 text-sm font-medium">No facility reservations found.</p>
            </div>
          ) : (
            sortedBookings.map(booking => {
                const status = getEventStatus(booking.bookingDate);
                const isFinished = status === 'FINISHED';
                const dateParts = parseDateParts(booking.bookingDate);

                return (
                    <div key={booking.id} className={`bg-white dark:bg-slate-900 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-800 overflow-hidden flex transition-all ${isFinished ? 'opacity-70 grayscale-[0.5]' : ''}`}>
                       {/* Left Side Bold Date Block */}
                       <div className={`w-20 flex-shrink-0 flex flex-col items-center justify-center border-r border-slate-50 dark:border-slate-800 ${isFinished ? 'bg-slate-50 dark:bg-slate-800/50' : booking.hallType === 'BIG' ? 'bg-purple-50 dark:bg-purple-900/10' : 'bg-amber-50 dark:bg-amber-900/10'}`}>
                          <span className={`text-xs font-black uppercase tracking-tighter ${isFinished ? 'text-slate-400' : booking.hallType === 'BIG' ? 'text-purple-400' : 'text-amber-400'}`}>
                            {dateParts.month}
                          </span>
                          <span className={`text-3xl font-black leading-none my-1 ${isFinished ? 'text-slate-500' : 'text-slate-900 dark:text-white'}`}>
                            {dateParts.day}
                          </span>
                          <span className="text-[10px] font-bold text-slate-400">
                            {dateParts.year}
                          </span>
                       </div>

                       {/* Right Content Area */}
                       <div className="flex-1 p-4 relative">
                          <div className="flex justify-between items-start mb-2">
                             <div className="flex flex-col">
                                <span className={`text-[9px] font-black px-2 py-0.5 rounded-full border tracking-widest uppercase w-fit mb-1 ${booking.hallType === 'BIG' ? 'bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400 border-purple-200 dark:border-purple-800' : 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400 border-amber-200 dark:border-amber-800'}`}>
                                   {booking.hallType} HALL
                                </span>
                                <h3 className="text-xl font-black text-slate-800 dark:text-white leading-none">{booking.flatNumber}</h3>
                             </div>

                             <div className={`flex items-center px-2 py-0.5 rounded-md text-[9px] font-black uppercase tracking-wider border shadow-sm ${isFinished ? 'bg-slate-100 text-slate-500 border-slate-200 dark:bg-slate-800 dark:border-slate-700 dark:text-slate-400' : 'bg-blue-600 text-white border-blue-700'}`}>
                                {status}
                             </div>
                          </div>

                          <p className="text-xs font-bold text-slate-500 dark:text-slate-400 mb-4">{booking.ownerName}</p>

                          <div className="flex items-center justify-between pt-3 border-t border-slate-50 dark:border-slate-800">
                             <div className="flex flex-col">
                                <span className="text-[9px] text-slate-400 uppercase font-black tracking-widest">Amount</span>
                                <span className="text-md font-black text-slate-700 dark:text-slate-200">{formatCurrency(booking.amount)}</span>
                             </div>

                             <div className="flex space-x-2">
                                <button onClick={() => startEdit(booking)} className="w-8 h-8 flex items-center justify-center bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-lg hover:bg-blue-500 hover:text-white transition-all active:scale-90" title="Edit Booking">
                                   <Edit2 size={14} strokeWidth={2.5} />
                                </button>

                                {booking.mobile && (
                                  <a href={generateWhatsAppReceipt(booking)} target="_blank" rel="noreferrer" className="w-8 h-8 flex items-center justify-center bg-green-50 dark:bg-green-900/20 text-green-600 dark:text-green-400 rounded-lg hover:bg-green-500 hover:text-white transition-all active:scale-90" title="Share Receipt">
                                     <Share2 size={14} strokeWidth={2.5} />
                                  </a>
                                )}

                                <button onClick={() => handleDelete(booking.id)} className="w-8 h-8 flex items-center justify-center bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded-lg hover:bg-red-500 hover:text-white transition-all active:scale-90" title="Delete Entry">
                                   <Trash2 size={14} strokeWidth={2.5} />
                                </button>
                             </div>
                          </div>
                       </div>
                    </div>
                );
            })
          )}
       </div>
    </div>
  );
};

