        {activeTab === 'TRANSACTIONS' && (
          <div className="space-y-3">
             {state.financialRecords.filter(r => r.date.startsWith(selectedMonth)).sort((a,b) => b.date.localeCompare(a.date)).map(record => (
                <div key={record.id} className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-100 dark:border-slate-800 flex justify-between items-center group">
                    <div className="flex items-center space-x-3">
                        <div className={`w-10 h-10 rounded-full flex items-center justify-center ${record.type === 'INCOME' ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'}`}>
                            {record.type === 'INCOME' ? <ArrowUpRight size={20} /> : <ArrowDownRight size={20} />}
                        </div>
                        <div>
                            <p className="text-sm font-black text-slate-800 dark:text-white leading-tight">{record.description || record.category}</p>
                            <p className="text-[10px] text-slate-400 uppercase font-bold mt-1">{formatDate(record.date)} • {record.paymentMode}</p>
                        </div>
                    </div>
                    <div className="text-right flex flex-col items-end">
                        <p className={`text-sm font-black ${record.type === 'INCOME' ? 'text-green-600' : 'text-red-600'}`}>{record.type === 'INCOME' ? '+' : '-'}{formatCurrency(record.amount)}</p>
                        <div className="flex space-x-1 opacity-0 group-hover:opacity-100 transition-opacity mt-1">
                            <button onClick={() => onEditTransaction(record)} className="p-1 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded"><Edit2 size={12} /></button>
                            <button onClick={() => handleDelete(record)} className="p-1 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 rounded"><Trash2 size={12} /></button>
