                            {filteredLedger.map(r => (
                               <tr key={r.id} className="hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors group">
                                  <td className="p-3 text-slate-500 font-medium">{formatDate(r.date).split(',')[0]}</td>
                                  <td className="p-3">
                                     <p className="font-bold text-slate-800 dark:text-white leading-tight">{r.description || r.category}</p>
                                     <p className="text-[9px] text-slate-400 uppercase font-black">{r.paymentMode}</p>
                                  </td>
                                  <td className={`p-3 text-right font-black ${r.type === 'EXPENSE' ? 'text-red-600' : 'text-green-600'}`}>
                                     {formatCurrency(r.amount)}
                                  </td>
                                  <td className="p-3">
                                     <div className="flex flex-col space-y-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button onClick={() => onEditTransaction(r)} className="text-blue-500 hover:text-blue-700">
                                            <Edit2 size={12} />
                                        </button>
                                        <button onClick={() => handleDelete(r)} className="text-red-500 hover:text-red-700">
                                            <Trash2 size={12} />
                                        </button>
                                     </div>
                                  </td>
                               </tr>
                            ))}
                            {filteredLedger.length === 0 && (
                               <tr><td colSpan={4} className="p-10 text-center text-slate-400 italic">No payments found for this vendor.</td></tr>
                            )}
                         </tbody>
                      </table>
                   </div>
                </div>
             ) : (
                <div className="text-center py-20 text-slate-400">
                   <Search size={40} className="mx-auto mb-3 opacity-20" />
                   <p className="font-bold">Search vendor name to view/edit ledger.</p>
