                  value={ledgerSearch}
                  onChange={(e) => setLedgerSearch(e.target.value)}
                />
             </div>

             {ledgerSearch ? (
                <div className="space-y-4">
                   <div className="bg-blue-600 p-4 rounded-2xl text-white flex justify-between items-center shadow-lg">
                      <div>
                        <p className="text-[10px] font-black uppercase opacity-70">Total Net Flow</p>
                        <h4 className="text-xl font-black">{formatCurrency(ledgerTotal)}</h4>
                        <p className="text-[8px] opacity-60 uppercase mt-0.5">(Expense - Income)</p>
                      </div>
                      <BookOpen size={24} className="opacity-30" />
                   </div>

                   <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-100 dark:border-slate-800 overflow-hidden shadow-sm">
                      <table className="w-full text-left text-xs">
                         <thead className="bg-slate-50 dark:bg-slate-800 text-slate-400 font-black uppercase tracking-widest border-b border-slate-100 dark:border-slate-800">
                            <tr>
                               <th className="p-3">Date</th>
                               <th className="p-3">Account / Narration</th>
                               <th className="p-3 text-right">Amount</th>
                               <th className="p-3 w-10"></th>
                            </tr>
                         </thead>
                         <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                            {filteredLedger.map(r => (
                               <tr key={r.id} className="hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors group">
                                  <td className="p-3 text-slate-500 font-medium whitespace-nowrap">{formatDate(r.date).split(',')[0]}</td>
                                  <td className="p-3">
                                     <div className="flex items-center space-x-1 mb-0.5">
                                        <span className="text-[9px] font-black px-1.5 py-0.5 rounded bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 uppercase">
                                           {r.category || 'General'}
                                        </span>
                                     </div>
                                     <p className="font-bold text-slate-800 dark:text-white leading-tight">{r.description || 'No description'}</p>
                                     <p className="text-[9px] text-slate-400 uppercase font-black mt-1">{r.paymentMode}</p>
                                  </td>
                                  <td className={`p-3 text-right font-black ${r.type === 'EXPENSE' ? 'text-red-600 dark:text-red-400' : 'text-green-600 dark:text-green-400'}`}>
                                     {r.type === 'INCOME' ? '+' : '-'}{formatCurrency(r.amount)}
                                  </td>
                                  <td className="p-3">
                                     <div className="flex flex-col space-y-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button onClick={() => onEditTransaction(r)} className="text-blue-500 hover:text-blue-700 p-1">
                                            <Edit2 size={12} />
                                        </button>
                                        <button onClick={() => handleDelete(r)} className="text-red-500 hover:text-red-700 p-1">
                                            <Trash2 size={12} />
                                        </button>
                                     </div>
                                  </td>
                               </tr>
                            ))}
                            {filteredLedger.length === 0 && (
                               <tr><td colSpan={4} className="p-10 text-center text-slate-400 italic">No matching records found.</td></tr>
                            )}
                         </tbody>
                      </table>
                   </div>
                </div>
             ) : (
                <div className="text-center py-20 text-slate-400">
                   <Search size={40} className="mx-auto mb-3 opacity-20" />
                   <p className="font-bold">Search vendor or account category to view ledger.</p>
                </div>
             )}
          </div>
        )}
      </div>

      <button onClick={onAddTransaction} className="fixed bottom-24 right-4 bg-slate-900 dark:bg-white text-white dark:text-black p-4 rounded-full shadow-xl z-20 active:scale-90 transition-transform"><Plus size={24} /></button>

      {/* PDF TEMPLATE */}
      <div id="financial-report-template" className={`${isGeneratingPdf ? 'block' : 'hidden'} bg-white p-8 text-black text-xs leading-relaxed`}>
          <div className="text-center mb-6">
              <h1 className="text-xl font-black uppercase">CONTINENTAL HEIGHTS B WING</h1>
              <h2 className="text-sm font-bold uppercase mt-1">Financial Report: {new Date(selectedMonth + '-01').toLocaleDateString('en-IN', {month: 'long', year: 'numeric'})}</h2>
          </div>
          <div className="grid grid-cols-2 gap-8 mb-6 border p-4">
              <div>
                  <p className="font-bold text-slate-500 uppercase">Cash Flow Summary</p>
                  <p className="flex justify-between mt-2">Opening Balance: <span className="font-bold">{formatCurrency(reportData.openingBalance)}</span></p>
                  <p className="flex justify-between">Total Income: <span className="font-bold text-green-600">+{formatCurrency(reportData.totalIncome)}</span></p>
                  <p className="flex justify-between">Total Expenses: <span className="font-bold text-red-600">-{formatCurrency(reportData.totalExpenses)}</span></p>
                  <p className="flex justify-between border-t mt-1 pt-1 font-bold">Closing Balance: <span>{formatCurrency(reportData.closingBalance)}</span></p>
              </div>
              <div>
                  <p className="font-bold text-slate-500 uppercase">Current Funds</p>
                  <p className="flex justify-between mt-2">Cash In Hand: <span className="font-bold">{formatCurrency(balanceData.cashInHand)}</span></p>
                  <p className="flex justify-between">Bank Balance: <span className="font-bold">{formatCurrency(balanceData.cashAtBank)}</span></p>
              </div>
          </div>
          <p className="font-black text-[10px] uppercase mb-2 border-b">Expense Details</p>
          <table className="w-full border-collapse">
              <thead>
                  <tr className="bg-slate-100"><th className="p-1 border text-left">Date</th><th className="p-1 border text-left">Category</th><th className="p-1 border text-left">Description</th><th className="p-1 border text-right">Amount</th></tr>
              </thead>
              <tbody>
                  {state.financialRecords.filter(r => r.date.startsWith(selectedMonth) && r.type === 'EXPENSE').map(r => (
                      <tr key={r.id}><td className="p-1 border">{formatDate(r.date).split(',')[0]}</td><td className="p-1 border">{r.category}</td><td className="p-1 border">{r.description}</td><td className="p-1 border text-right">{formatCurrency(r.amount)}</td></tr>
                  ))}
              </tbody>
          </table>
      </div>
    </div>
  );
};

export default FinanceDashboard;

import React, { useMemo, useState, useEffect } from 'react';
import { AppState, FinancialRecord } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { formatCurrency, formatDate, getTodayDateString } from '../utils/helpers';
import { Wallet, Plus, Trash2, Edit2, ChevronLeft, ChevronRight, IndianRupee, ArrowUpRight, ArrowDownRight, Download, Search, BookOpen, Tags, ChevronRight as ChevronRightIcon, ArrowLeft } from 'lucide-react';
import { deleteFinancialRecord } from '../services/storageService';

interface FinanceDashboardProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
  onAddTransaction: () => void;
  onEditTransaction: (record: FinancialRecord) => void;
}

type FinanceTab = 'OVERVIEW' | 'TRANSACTIONS' | 'LEDGER';

const FinanceDashboard: React.FC<FinanceDashboardProps> = ({ state, refreshState, onAddTransaction, onEditTransaction }) => {
  const [activeTab, setActiveTab] = useState<FinanceTab>('OVERVIEW');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);
  const [ledgerSearch, setLedgerSearch] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

  useEffect(() => {
    const currentMonth = new Date().toISOString().slice(0, 7);
    const hasCurrentData = state.financialRecords.some(r => r.date.startsWith(currentMonth));
    if (!hasCurrentData && state.financialRecords.length > 0) {
      const sorted = [...state.financialRecords].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      if (sorted[0]) setSelectedMonth(sorted[0].date.slice(0, 7));
    }
  }, [state.financialRecords]);

  const handlePrevMonth = () => {
    const d = new Date(selectedMonth + '-01');
    d.setMonth(d.getMonth() - 1);
    setSelectedMonth(d.toISOString().slice(0, 7));
  };

  const handleNextMonth = () => {
    const d = new Date(selectedMonth + '-01');
    d.setMonth(d.getMonth() + 1);
    setSelectedMonth(d.toISOString().slice(0, 7));
  };

  const balanceData = useMemo(() => {
    let cashInHand = 0;
    let cashAtBank = 0;
    const allRecords = [...state.financialRecords].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    allRecords.forEach(r => {
      const mode = r.paymentMode || 'CASH';
      if (r.type === 'INCOME') {
        if (mode === 'CASH') cashInHand += r.amount; else cashAtBank += r.amount;
      } else if (r.type === 'EXPENSE') {
        if (mode === 'CASH') cashInHand -= r.amount; else cashAtBank -= r.amount;
      } else if (r.type === 'TRANSFER') {
        if (mode === 'CASH') { cashInHand -= r.amount; cashAtBank += r.amount; }
        else { cashAtBank -= r.amount; cashInHand += r.amount; }
      }
    });
    return { cashInHand, cashAtBank };
  }, [state.financialRecords]);

  const reportData = useMemo(() => {
     const startOfMonthStr = selectedMonth + '-01';
     const startOfNextMonth = new Date(selectedMonth + '-01');
     startOfNextMonth.setMonth(startOfNextMonth.getMonth() + 1);
     const endOfMonthStr = startOfNextMonth.toISOString().slice(0, 10);
     let openingBalance = 0;
     const maintenanceBefore = state.transactions.filter(t => t.date < startOfMonthStr).reduce((sum, t) => sum + t.amount, 0);
     state.financialRecords.forEach(r => {
         if (r.date < startOfMonthStr) {
             if (r.type === 'INCOME') openingBalance += r.amount;
             if (r.type === 'EXPENSE') openingBalance -= r.amount;
         }
     });
     openingBalance += maintenanceBefore;
     const maintenanceThisMonth = state.transactions.filter(t => t.date >= startOfMonthStr && t.date < endOfMonthStr).reduce((sum, t) => sum + t.amount, 0);
     const incomeRecords = state.financialRecords.filter(r => r.type === 'INCOME' && r.date >= startOfMonthStr && r.date < endOfMonthStr);
     const totalOtherIncome = incomeRecords.reduce((sum, r) => sum + r.amount, 0);
     const expenseRecords = state.financialRecords.filter(r => r.type === 'EXPENSE' && r.date >= startOfMonthStr && r.date < endOfMonthStr);
     const totalExpenses = expenseRecords.reduce((sum, r) => sum + r.amount, 0);
     const totalIncome = maintenanceThisMonth + totalOtherIncome;
     const closingBalance = openingBalance + totalIncome - totalExpenses;
     const totalMaintenanceAllTime = state.transactions.reduce((sum, t) => sum + t.amount, 0);
     const globalCash = balanceData.cashInHand + totalMaintenanceAllTime; 
     const globalBank = balanceData.cashAtBank;
     return { openingBalance, maintenanceThisMonth, totalOtherIncome, totalExpenses, totalIncome, closingBalance, globalCash, globalBank, totalLiquid: globalCash + globalBank };
  }, [state, selectedMonth, balanceData]);

  // Ledger Categorization Logic
  const categorizedLedger = useMemo(() => {
    const categories: Record<string, { total: number; count: number; type: string }> = {};
    state.financialRecords.forEach(r => {
      const cat = r.category || 'Uncategorized';
      if (!categories[cat]) {
        categories[cat] = { total: 0, count: 0, type: r.type };
      }
      categories[cat].total += r.amount;
      categories[cat].count += 1;
    });

    return Object.entries(categories)
      .map(([name, data]) => ({ name, ...data }))
      .filter(c => c.name.toLowerCase().includes(ledgerSearch.toLowerCase()))
      .sort((a, b) => b.total - a.total);
  }, [state.financialRecords, ledgerSearch]);

  const detailRecords = useMemo(() => {
    if (!selectedCategory) return [];
    return state.financialRecords
      .filter(r => r.category === selectedCategory)
      .sort((a, b) => b.date.localeCompare(a.date));
  }, [state.financialRecords, selectedCategory]);

  const generatePDF = () => {
    setIsGeneratingPdf(true);
    setTimeout(() => {
      const element = document.getElementById('financial-report-template');
      if (!element) return;
      const opt = { margin: 0.5, filename: `Financial_Report_${selectedMonth}.pdf`, image: { type: 'jpeg', quality: 0.98 }, html2canvas: { scale: 2 }, jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' } };
      (window as any).html2pdf().from(element).set(opt).save().then(() => setIsGeneratingPdf(false));
    }, 100);
  };

  const handleDelete = (record: FinancialRecord) => {
    if(window.confirm(`Delete record: "${record.description || record.category}" (${formatCurrency(record.amount)})?`)) {
      const newState = deleteFinancialRecord(state, record.id);
      refreshState(newState);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-950">
      {/* Navigation & Tabs */}
      <div className="sticky top-0 z-30 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 shadow-sm transition-colors">
        <div className="px-5 py-3 flex items-center justify-between">
            <div className="flex items-center space-x-2 bg-slate-100 dark:bg-slate-800 rounded-full p-1">
                <button onClick={handlePrevMonth} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-white dark:hover:bg-slate-700 text-slate-500 transition-all shadow-sm"><ChevronLeft size={16} /></button>
                <span className="text-sm font-bold text-slate-800 dark:text-white px-2 min-w-[100px] text-center">{new Date(selectedMonth + '-01').toLocaleDateString('en-IN', { month: 'short', year: 'numeric' })}</span>
                <button onClick={handleNextMonth} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-white dark:hover:bg-slate-700 text-slate-500 transition-all shadow-sm"><ChevronRight size={16} /></button>
            </div>
            <button onClick={generatePDF} className="flex items-center space-x-2 px-3 py-2 bg-slate-800 dark:bg-black text-white rounded-lg shadow-lg active:scale-95"><Download size={14} /><span className="text-xs font-bold">PDF</span></button>
        </div>
        <div className="flex px-4 pb-2 space-x-4">
            <button onClick={() => { setActiveTab('OVERVIEW'); setSelectedCategory(null); }} className={`text-xs font-black uppercase tracking-widest pb-2 border-b-2 transition-all ${activeTab === 'OVERVIEW' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400'}`}>Overview</button>
            <button onClick={() => { setActiveTab('TRANSACTIONS'); setSelectedCategory(null); }} className={`text-xs font-black uppercase tracking-widest pb-2 border-b-2 transition-all ${activeTab === 'TRANSACTIONS' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400'}`}>Records</button>
            <button onClick={() => setActiveTab('LEDGER')} className={`text-xs font-black uppercase tracking-widest pb-2 border-b-2 transition-all ${activeTab === 'LEDGER' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400'}`}>Ledger</button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6 pb-24">
        {activeTab === 'OVERVIEW' && (
          <>
            <div className="grid grid-cols-2 gap-4">
                <div className="bg-emerald-600 p-5 rounded-2xl shadow-lg text-white">
                    <p className="text-emerald-100 text-[10px] font-black uppercase mb-1">Cash In Hand</p>
                    <h3 className="text-2xl font-black">{formatCurrency(balanceData.cashInHand)}</h3>
                </div>
                <div className="bg-blue-600 p-5 rounded-2xl shadow-lg text-white">
                    <p className="text-blue-100 text-[10px] font-black uppercase mb-1">Bank Balance</p>
                    <h3 className="text-2xl font-black">{formatCurrency(balanceData.cashAtBank)}</h3>
                </div>
            </div>
            <div className="grid grid-cols-3 gap-3">
                <div className="bg-white dark:bg-slate-900 p-3 rounded-xl border border-slate-100 dark:border-slate-800 text-center">
                    <p className="text-[10px] text-slate-400 font-black uppercase">Income</p>
                    <p className="text-sm font-black text-emerald-600">{formatCurrency(reportData.totalIncome)}</p>
                </div>
                <div className="bg-white dark:bg-slate-900 p-3 rounded-xl border border-slate-100 dark:border-slate-800 text-center">
                    <p className="text-[10px] text-slate-400 font-black uppercase">Expense</p>
                    <p className="text-sm font-black text-red-600">{formatCurrency(reportData.totalExpenses)}</p>
                </div>
                <div className="bg-white dark:bg-slate-900 p-3 rounded-xl border border-slate-100 dark:border-slate-800 text-center">
                    <p className="text-[10px] text-slate-400 font-black uppercase">Closing</p>
                    <p className="text-sm font-black text-blue-600">{formatCurrency(reportData.closingBalance)}</p>
                </div>
            </div>
          </>
        )}

        {activeTab === 'TRANSACTIONS' && (
          <div className="space-y-3">
             {state.financialRecords.filter(r => r.date.startsWith(selectedMonth)).sort((a,b) => b.date.localeCompare(a.date)).map(record => (
                <div key={record.id} className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-100 dark:border-slate-800 flex justify-between items-center group shadow-sm transition-all hover:border-slate-200 dark:hover:border-slate-700">
                    <div className="flex items-center space-x-3 overflow-hidden">
                        <div className={`w-10 h-10 shrink-0 rounded-full flex items-center justify-center ${record.type === 'INCOME' ? 'bg-green-50 text-green-600 dark:bg-green-900/20 dark:text-green-400' : 'bg-red-50 text-red-600 dark:bg-red-900/20 dark:text-red-400'}`}>
                            {record.type === 'INCOME' ? <ArrowUpRight size={20} /> : <ArrowDownRight size={20} />}
                        </div>
                        <div className="min-w-0">
                            <p className="text-sm font-black text-slate-800 dark:text-white leading-tight truncate">{record.description || 'No narration'}</p>
                            <div className="flex flex-wrap items-center mt-1 gap-2">
                                <p className="text-[10px] text-slate-400 uppercase font-black whitespace-nowrap">{formatDate(record.date)} • {record.paymentMode}</p>
                                <span className="inline-flex items-center text-[9px] font-black px-2 py-0.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-700 uppercase tracking-tighter">
                                   <Tags size={8} className="mr-1" />
                                   {record.category || 'General'}
                                </span>
                            </div>
                        </div>
                    </div>
                    <div className="text-right flex flex-col items-end shrink-0 ml-4">
                        <p className={`text-sm font-black ${record.type === 'INCOME' ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}`}>
                          {record.type === 'INCOME' ? '+' : '-'}{formatCurrency(record.amount)}
                        </p>
                        <div className="flex space-x-1 opacity-0 group-hover:opacity-100 transition-opacity mt-1">
                            <button onClick={() => onEditTransaction(record)} className="p-1.5 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-lg transition-colors"><Edit2 size={12} /></button>
                            <button onClick={() => handleDelete(record)} className="p-1.5 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-lg transition-colors"><Trash2 size={12} /></button>
                        </div>
                    </div>
                </div>
             ))}
          </div>
        )}

        {activeTab === 'LEDGER' && (
          <div className="space-y-4">
             {!selectedCategory ? (
               <>
                 <div className="relative">
                    <Search className="absolute left-3 top-3 text-blue-500" size={18} />
                    <input 
                      type="text" 
                      placeholder="Search accounts or categories..." 
                      className="w-full pl-10 pr-4 py-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none text-sm font-bold"
                      value={ledgerSearch}
                      onChange={(e) => setLedgerSearch(e.target.value)}
                    />
                 </div>

                 <div className="grid grid-cols-1 gap-3">
                    {categorizedLedger.map(cat => (
                      <button 
                        key={cat.name}
                        onClick={() => setSelectedCategory(cat.name)}
                        className="bg-white dark:bg-slate-900 p-4 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm flex items-center justify-between hover:border-blue-500 dark:hover:border-blue-400 transition-all group active:scale-[0.98]"
                      >
                         <div className="flex items-center space-x-4">
                            <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${cat.type === 'INCOME' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
                               <Wallet size={24} />
                            </div>
                            <div className="text-left">
                               <p className="text-sm font-black text-slate-800 dark:text-white uppercase tracking-tight">{cat.name}</p>
                               <p className="text-[10px] font-bold text-slate-400 uppercase">{cat.count} Transactions</p>
                            </div>
                         </div>
                         <div className="flex items-center space-x-3">
                            <div className="text-right">
                               <p className={`text-base font-black ${cat.type === 'INCOME' ? 'text-emerald-600' : 'text-red-600'}`}>
                                 {formatCurrency(cat.total)}
                               </p>
                            </div>
                            <ChevronRightIcon size={18} className="text-slate-300 group-hover:text-blue-500 transition-colors" />
                         </div>
                      </button>
                    ))}
                    {categorizedLedger.length === 0 && (
                      <div className="text-center py-20 text-slate-400 italic">No ledger accounts found.</div>
                    )}
                 </div>
               </>
             ) : (
               <div className="space-y-4 animate-in fade-in slide-in-from-right-4 duration-300">
                  <div className="flex items-center justify-between mb-2">
                     <button 
                       onClick={() => setSelectedCategory(null)}
                       className="flex items-center space-x-2 text-blue-600 font-black text-xs uppercase hover:underline"
                     >
                        <ArrowLeft size={16} />
                        <span>Back to Summary</span>
                     </button>
                     <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Account Details</span>
                  </div>

                  <div className="bg-blue-600 p-6 rounded-2xl text-white flex justify-between items-center shadow-lg">
                     <div>
                        <p className="text-[10px] font-black uppercase opacity-70 tracking-widest mb-1">Total for Account</p>
                        <h4 className="text-2xl font-black">{selectedCategory}</h4>
                        <p className="text-xl font-bold mt-1">{formatCurrency(detailRecords.reduce((sum, r) => sum + r.amount, 0))}</p>
                     </div>
                     <BookOpen size={32} className="opacity-30" />
                  </div>

                  <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-100 dark:border-slate-800 overflow-hidden shadow-sm">
                     <div className="divide-y divide-slate-50 dark:divide-slate-800">
                        {detailRecords.map(r => (
                           <div key={r.id} className="p-4 flex justify-between items-center hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors group">
                              <div className="flex items-center space-x-4">
                                 <div className="text-center min-w-[50px]">
                                    <p className="text-[9px] font-black text-slate-400 uppercase">{new Date(r.date).toLocaleDateString('en-IN', { month: 'short' })}</p>
                                    <p className="text-lg font-black text-slate-800 dark:text-white leading-none">{new Date(r.date).getDate()}</p>
                                 </div>
                                 <div>
                                    <p className="text-sm font-black text-slate-800 dark:text-white leading-tight">{r.description || 'No narration'}</p>
                                    <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">{r.paymentMode} • {r.type}</p>
                                 </div>
                              </div>
                              <div className="flex items-center space-x-4">
                                 <p className={`text-sm font-black ${r.type === 'INCOME' ? 'text-emerald-600' : 'text-red-600'}`}>
                                    {r.type === 'INCOME' ? '+' : '-'}{formatCurrency(r.amount)}
                                 </p>
                                 <div className="flex flex-col space-y-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button onClick={() => onEditTransaction(r)} className="text-blue-500 hover:bg-blue-100 p-1.5 rounded-lg transition-colors">
                                       <Edit2 size={14} />
                                    </button>
                                    <button onClick={() => handleDelete(r)} className="text-red-500 hover:bg-red-100 p-1.5 rounded-lg transition-colors">
                                       <Trash2 size={14} />
                                    </button>
                                 </div>
                              </div>
                           </div>
                        ))}
                     </div>
                  </div>
               </div>
             )}
          </div>
        )}
      </div>

      <button onClick={onAddTransaction} className="fixed bottom-24 right-4 bg-slate-900 dark:bg-white text-white dark:text-black p-4 rounded-full shadow-xl z-20 active:scale-90 transition-transform"><Plus size={24} /></button>

      {/* PDF TEMPLATE */}
      <div id="financial-report-template" className={`${isGeneratingPdf ? 'block' : 'hidden'} bg-white p-8 text-black text-xs leading-relaxed`}>
          <div className="text-center mb-6">
              <h1 className="text-xl font-black uppercase">CONTINENTAL HEIGHTS B WING</h1>
              <h2 className="text-sm font-bold uppercase mt-1">Financial Report: {new Date(selectedMonth + '-01').toLocaleDateString('en-IN', {month: 'long', year: 'numeric'})}</h2>
          </div>
          <div className="grid grid-cols-2 gap-8 mb-6 border p-4">
              <div>
                  <p className="font-bold text-slate-500 uppercase">Cash Flow Summary</p>
                  <p className="flex justify-between mt-2">Opening Balance: <span className="font-bold">{formatCurrency(reportData.openingBalance)}</span></p>
                  <p className="flex justify-between">Total Income: <span className="font-bold text-green-600">+{formatCurrency(reportData.totalIncome)}</span></p>
                  <p className="flex justify-between">Total Expenses: <span className="font-bold text-red-600">-{formatCurrency(reportData.totalExpenses)}</span></p>
                  <p className="flex justify-between border-t mt-1 pt-1 font-bold">Closing Balance: <span>{formatCurrency(reportData.closingBalance)}</span></p>
              </div>
              <div>
                  <p className="font-bold text-slate-500 uppercase">Current Funds</p>
                  <p className="flex justify-between mt-2">Cash In Hand: <span className="font-bold">{formatCurrency(reportData.globalCash)}</span></p>
                  <p className="flex justify-between">Bank Balance: <span className="font-bold">{formatCurrency(reportData.globalBank)}</span></p>
              </div>
          </div>
          <p className="font-black text-[10px] uppercase mb-2 border-b">Expense Details</p>
          <table className="w-full border-collapse">
              <thead>
                  <tr className="bg-slate-100"><th className="p-1 border text-left">Date</th><th className="p-1 border text-left">Category</th><th className="p-1 border text-left">Description</th><th className="p-1 border text-right">Amount</th></tr>
              </thead>
              <tbody>
                  {state.financialRecords.filter(r => r.date.startsWith(selectedMonth) && r.type === 'EXPENSE').map(r => (
                      <tr key={r.id}><td className="p-1 border">{formatDate(r.date).split(',')[0]}</td><td className="p-1 border">{r.category}</td><td className="p-1 border">{r.description}</td><td className="p-1 border text-right">{formatCurrency(r.amount)}</td></tr>
                  ))}
              </tbody>
          </table>
      </div>
    </div>
  );
};

export default FinanceDashboard;

import React, { useMemo, useState, useEffect } from 'react';
import { AppState, FinancialRecord } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { formatCurrency, formatDate, getTodayDateString } from '../utils/helpers';
import { Wallet, Plus, Trash2, Edit2, ChevronLeft, ChevronRight, IndianRupee, ArrowUpRight, ArrowDownRight, Download, Search, BookOpen, Tags, ChevronRight as ChevronRightIcon, ArrowLeft, Layers } from 'lucide-react';
import { deleteFinancialRecord } from '../services/storageService';

interface FinanceDashboardProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
  onAddTransaction: () => void;
  onEditTransaction: (record: FinancialRecord) => void;
}

type FinanceTab = 'OVERVIEW' | 'TRANSACTIONS' | 'LEDGER';

const FinanceDashboard: React.FC<FinanceDashboardProps> = ({ state, refreshState, onAddTransaction, onEditTransaction }) => {
  const [activeTab, setActiveTab] = useState<FinanceTab>('OVERVIEW');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);
  const [ledgerSearch, setLedgerSearch] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

  useEffect(() => {
    const currentMonth = new Date().toISOString().slice(0, 7);
    const hasCurrentData = state.financialRecords.some(r => r.date.startsWith(currentMonth));
    if (!hasCurrentData && state.financialRecords.length > 0) {
      const sorted = [...state.financialRecords].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      if (sorted[0]) setSelectedMonth(sorted[0].date.slice(0, 7));
    }
  }, [state.financialRecords]);

  const handlePrevMonth = () => {
    const d = new Date(selectedMonth + '-01');
    d.setMonth(d.getMonth() - 1);
    setSelectedMonth(d.toISOString().slice(0, 7));
  };

  const handleNextMonth = () => {
    const d = new Date(selectedMonth + '-01');
    d.setMonth(d.getMonth() + 1);
    setSelectedMonth(d.toISOString().slice(0, 7));
  };

  const balanceData = useMemo(() => {
    let cashInHand = 0;
    let cashAtBank = 0;
    const allRecords = [...state.financialRecords].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    allRecords.forEach(r => {
      const mode = r.paymentMode || 'CASH';
      if (r.type === 'INCOME') {
        if (mode === 'CASH') cashInHand += r.amount; else cashAtBank += r.amount;
      } else if (r.type === 'EXPENSE') {
        if (mode === 'CASH') cashInHand -= r.amount; else cashAtBank -= r.amount;
      } else if (r.type === 'TRANSFER') {
        if (mode === 'CASH') { cashInHand -= r.amount; cashAtBank += r.amount; }
        else { cashAtBank -= r.amount; cashInHand += r.amount; }
      }
    });
    return { cashInHand, cashAtBank };
  }, [state.financialRecords]);

  const reportData = useMemo(() => {
     const startOfMonthStr = selectedMonth + '-01';
     const startOfNextMonth = new Date(selectedMonth + '-01');
     startOfNextMonth.setMonth(startOfNextMonth.getMonth() + 1);
     const endOfMonthStr = startOfNextMonth.toISOString().slice(0, 10);
     let openingBalance = 0;
     const maintenanceBefore = state.transactions.filter(t => t.date < startOfMonthStr).reduce((sum, t) => sum + t.amount, 0);
     state.financialRecords.forEach(r => {
         if (r.date < startOfMonthStr) {
             if (r.type === 'INCOME') openingBalance += r.amount;
             if (r.type === 'EXPENSE') openingBalance -= r.amount;
         }
     });
     openingBalance += maintenanceBefore;
     const maintenanceThisMonth = state.transactions.filter(t => t.date >= startOfMonthStr && t.date < endOfMonthStr).reduce((sum, t) => sum + t.amount, 0);
     const incomeRecords = state.financialRecords.filter(r => r.type === 'INCOME' && r.date >= startOfMonthStr && r.date < endOfMonthStr);
     const totalOtherIncome = incomeRecords.reduce((sum, r) => sum + r.amount, 0);
     const expenseRecords = state.financialRecords.filter(r => r.type === 'EXPENSE' && r.date >= startOfMonthStr && r.date < endOfMonthStr);
     const totalExpenses = expenseRecords.reduce((sum, r) => sum + r.amount, 0);
     const totalIncome = maintenanceThisMonth + totalOtherIncome;
     const closingBalance = openingBalance + totalIncome - totalExpenses;
     return { openingBalance, maintenanceThisMonth, totalOtherIncome, totalExpenses, totalIncome, closingBalance, globalCash: balanceData.cashInHand, globalBank: balanceData.cashAtBank };
  }, [state, selectedMonth, balanceData]);

  // CATEGORIZED LEDGER LOGIC: Unique categories with total amounts
  const categorizedLedger = useMemo(() => {
    const categories: Record<string, { totalIncome: number; totalExpense: number; count: number }> = {};

    state.financialRecords.forEach(r => {
      const cat = r.category || 'General';
      if (!categories[cat]) {
        categories[cat] = { totalIncome: 0, totalExpense: 0, count: 0 };
      }
      if (r.type === 'INCOME') categories[cat].totalIncome += r.amount;
      if (r.type === 'EXPENSE') categories[cat].totalExpense += r.amount;
      categories[cat].count += 1;
    });

    return Object.entries(categories)
      .map(([name, data]) => ({ name, ...data }))
      .filter(c => c.name.toLowerCase().includes(ledgerSearch.toLowerCase()))
      .sort((a, b) => a.name.localeCompare(b.name));
  }, [state.financialRecords, ledgerSearch]);

  const detailRecords = useMemo(() => {
    if (!selectedCategory) return [];
    return state.financialRecords
      .filter(r => r.category === selectedCategory)
      .sort((a, b) => b.date.localeCompare(a.date));
  }, [state.financialRecords, selectedCategory]);

  const generatePDF = () => {
    setIsGeneratingPdf(true);
    setTimeout(() => {
      const element = document.getElementById('financial-report-template');
      if (!element) return;
      const opt = { margin: 0.5, filename: `Financial_Report_${selectedMonth}.pdf`, image: { type: 'jpeg', quality: 0.98 }, html2canvas: { scale: 2 }, jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' } };
      (window as any).html2pdf().from(element).set(opt).save().then(() => setIsGeneratingPdf(false));
    }, 100);
  };

  const handleDelete = (record: FinancialRecord) => {
    if(window.confirm(`Delete record: "${record.description || record.category}" (${formatCurrency(record.amount)})?`)) {
      const newState = deleteFinancialRecord(state, record.id);
      refreshState(newState);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-950">
      {/* Navigation Header */}
      <div className="sticky top-0 z-30 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 shadow-sm transition-colors">
        <div className="px-5 py-3 flex items-center justify-between">
            <div className="flex items-center space-x-2 bg-slate-100 dark:bg-slate-800 rounded-full p-1">
                <button onClick={handlePrevMonth} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-white dark:hover:bg-slate-700 text-slate-500 transition-all shadow-sm"><ChevronLeft size={16} /></button>
                <span className="text-sm font-bold text-slate-800 dark:text-white px-2 min-w-[100px] text-center">{new Date(selectedMonth + '-01').toLocaleDateString('en-IN', { month: 'short', year: 'numeric' })}</span>
                <button onClick={handleNextMonth} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-white dark:hover:bg-slate-700 text-slate-500 transition-all shadow-sm"><ChevronRight size={16} /></button>
            </div>
            <button onClick={generatePDF} className="flex items-center space-x-2 px-3 py-2 bg-slate-800 dark:bg-black text-white rounded-lg shadow-lg active:scale-95"><Download size={14} /><span className="text-xs font-bold">PDF</span></button>
        </div>
        <div className="flex px-4 pb-2 space-x-4">
            <button onClick={() => { setActiveTab('OVERVIEW'); setSelectedCategory(null); }} className={`text-xs font-black uppercase tracking-widest pb-2 border-b-2 transition-all ${activeTab === 'OVERVIEW' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400'}`}>Overview</button>
            <button onClick={() => { setActiveTab('TRANSACTIONS'); setSelectedCategory(null); }} className={`text-xs font-black uppercase tracking-widest pb-2 border-b-2 transition-all ${activeTab === 'TRANSACTIONS' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400'}`}>Records</button>
            <button onClick={() => setActiveTab('LEDGER')} className={`text-xs font-black uppercase tracking-widest pb-2 border-b-2 transition-all ${activeTab === 'LEDGER' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400'}`}>Ledger</button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6 pb-24">
        {activeTab === 'OVERVIEW' && (
          <div className="space-y-6">
            <div className="grid grid-cols-2 gap-4">
                <div className="bg-emerald-600 p-5 rounded-2xl shadow-lg text-white">
                    <p className="text-emerald-100 text-[10px] font-black uppercase mb-1">Cash In Hand</p>
                    <h3 className="text-2xl font-black">{formatCurrency(balanceData.cashInHand)}</h3>
                </div>
                <div className="bg-blue-600 p-5 rounded-2xl shadow-lg text-white">
                    <p className="text-blue-100 text-[10px] font-black uppercase mb-1">Bank Balance</p>
                    <h3 className="text-2xl font-black">{formatCurrency(balanceData.cashAtBank)}</h3>
                </div>
            </div>
            <div className="grid grid-cols-3 gap-3">
                <div className="bg-white dark:bg-slate-900 p-3 rounded-xl border border-slate-100 dark:border-slate-800 text-center">
                    <p className="text-[10px] text-slate-400 font-black uppercase">Income</p>
                    <p className="text-sm font-black text-emerald-600">{formatCurrency(reportData.totalIncome)}</p>
                </div>
                <div className="bg-white dark:bg-slate-900 p-3 rounded-xl border border-slate-100 dark:border-slate-800 text-center">
                    <p className="text-[10px] text-slate-400 font-black uppercase">Expense</p>
                    <p className="text-sm font-black text-red-600">{formatCurrency(reportData.totalExpenses)}</p>
                </div>
                <div className="bg-white dark:bg-slate-900 p-3 rounded-xl border border-slate-100 dark:border-slate-800 text-center">
                    <p className="text-[10px] text-slate-400 font-black uppercase">Closing</p>
                    <p className="text-sm font-black text-blue-600">{formatCurrency(reportData.closingBalance)}</p>
                </div>
            </div>
          </div>
        )}

        {activeTab === 'TRANSACTIONS' && (
          <div className="space-y-3">
             {state.financialRecords.filter(r => r.date.startsWith(selectedMonth)).sort((a,b) => b.date.localeCompare(a.date)).map(record => (
                <div key={record.id} className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-100 dark:border-slate-800 flex justify-between items-center group shadow-sm">
                    <div className="flex items-center space-x-3 overflow-hidden">
                        <div className={`w-10 h-10 shrink-0 rounded-full flex items-center justify-center ${record.type === 'INCOME' ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'}`}>
                            {record.type === 'INCOME' ? <ArrowUpRight size={20} /> : <ArrowDownRight size={20} />}
                        </div>
                        <div className="min-w-0">
                            <p className="text-sm font-black text-slate-800 dark:text-white truncate">{record.description || 'No narration'}</p>
                            <div className="flex items-center mt-1 space-x-2">
                                <span className="text-[9px] font-black px-1.5 py-0.5 rounded bg-slate-100 dark:bg-slate-800 text-slate-500 uppercase">{record.category}</span>
                                <p className="text-[10px] text-slate-400 uppercase font-black whitespace-nowrap">{formatDate(record.date)} • {record.paymentMode}</p>
                            </div>
                        </div>
                    </div>
                    <div className="text-right flex flex-col items-end shrink-0 ml-4">
                        <p className={`text-sm font-black ${record.type === 'INCOME' ? 'text-green-600' : 'text-red-600'}`}>
                          {record.type === 'INCOME' ? '+' : '-'}{formatCurrency(record.amount)}
                        </p>
                        <div className="flex space-x-1 opacity-0 group-hover:opacity-100 transition-opacity mt-1">
                            <button onClick={() => onEditTransaction(record)} className="p-1.5 text-blue-500 hover:bg-blue-50 rounded-lg transition-colors"><Edit2 size={12} /></button>
                            <button onClick={() => handleDelete(record)} className="p-1.5 text-red-500 hover:bg-red-50 rounded-lg transition-colors"><Trash2 size={12} /></button>
                        </div>
                    </div>
                </div>
             ))}
          </div>
        )}

        {activeTab === 'LEDGER' && (
          <div className="space-y-4">
             {!selectedCategory ? (
               <>
                 <div className="relative">
                    <Search className="absolute left-3 top-3 text-blue-500" size={18} />
                    <input 
                      type="text" 
                      placeholder="Search accounts or categories..." 
                      className="w-full pl-10 pr-4 py-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none text-sm font-bold shadow-sm"
                      value={ledgerSearch}
                      onChange={(e) => setLedgerSearch(e.target.value)}
                    />
                 </div>

                 <div className="grid grid-cols-1 gap-3">
                    {categorizedLedger.map(cat => (
                      <button 
                        key={cat.name}
                        onClick={() => setSelectedCategory(cat.name)}
                        className="bg-white dark:bg-slate-900 p-5 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm flex items-center justify-between hover:border-blue-500 transition-all group active:scale-[0.98]"
                      >
                         <div className="flex items-center space-x-4">
                            <div className="w-12 h-12 rounded-2xl bg-slate-50 dark:bg-slate-800 flex items-center justify-center text-slate-400 group-hover:text-blue-500 transition-colors">
                               <Layers size={24} />
                            </div>
                            <div className="text-left">
                               <p className="text-base font-black text-slate-800 dark:text-white uppercase tracking-tight">{cat.name}</p>
                               <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{cat.count} Payments recorded</p>
                            </div>
                         </div>
                         <div className="flex items-center space-x-4">
                            <div className="text-right">
                               <p className="text-sm font-black text-red-600">-{formatCurrency(cat.totalExpense)}</p>
