            <AlertCircle size={14} />
            <span className="text-[10px] font-bold uppercase tracking-wider">Pending</span>
          </div>
          <p className="text-xl font-bold text-red-700 dark:text-red-500 leading-tight">{stats.unpaidCount}</p>
