import { addNotice, deleteNotice, addContact, deleteContact } from '../services/storageService';
import { formatDate, getTodayDateString } from '../utils/helpers';
import { Megaphone, Phone, Trash2, Plus, Share2, Bell, AlertTriangle, Info, User, PhoneCall, X } from 'lucide-react';
import { BUILDING_NAME } from '../constants';

interface CommunicationHubProps {
  state: AppState;
  refreshState: (newState: AppState) => void;
}

type Tab = 'NOTICES' | 'CONTACTS';

const CommunicationHub: React.FC<CommunicationHubProps> = ({ state, refreshState }) => {
  const [activeTab, setActiveTab] = useState<Tab>('NOTICES');
  const [showForm, setShowForm] = useState(false);

  // Notice Form
  const [noticeTitle, setNoticeTitle] = useState('');
  const [noticeContent, setNoticeContent] = useState('');
  const [severity, setSeverity] = useState<'NORMAL' | 'URGENT' | 'INFO'>('NORMAL');

  // Contact Form
  const [contactName, setContactName] = useState('');
  const [contactRole, setContactRole] = useState('');
  const [contactMobile, setContactMobile] = useState('');

  const handleAddNotice = (e: React.FormEvent) => {
    e.preventDefault();
    if(!noticeTitle || !noticeContent) return;

    const newState = addNotice(state, {
        title: noticeTitle,
        content: noticeContent,
        severity,
        date: getTodayDateString()
    });
    refreshState(newState);
    setShowForm(false);
    setNoticeTitle('');
    setNoticeContent('');
    setSeverity('NORMAL');
  };

  const handleDeleteNotice = (id: string) => {
      if(window.confirm("Delete this notice?")) {
          const newState = deleteNotice(state, id);
          refreshState(newState);
      }
  };

  const handleShareNotice = (title: string, content: string) => {
      const text = `*NOTICE: ${title}*\n${BUILDING_NAME}\n\n${content}\n\n- Secretary/Manager`;
      window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
  };

  const handleAddContact = (e: React.FormEvent) => {
      e.preventDefault();
      if(!contactName || !contactMobile) return;

      const newState = addContact(state, {
          name: contactName,
          role: contactRole,
          mobile: contactMobile
      });
      refreshState(newState);
      setShowForm(false);
      setContactName('');
      setContactRole('');
      setContactMobile('');
  };

  const handleDeleteContact = (id: string) => {
      if(window.confirm("Delete this contact?")) {
          const newState = deleteContact(state, id);
          refreshState(newState);
      }
  };

  const renderNotices = () => (
      <div className="space-y-4">
          {(state.notices || []).length === 0 ? (
              <div className="text-center py-12 text-slate-400">
                  <Bell size={48} className="mx-auto mb-2 opacity-20" />
                  <p>No notices created yet.</p>
              </div>
          ) : (
              (state.notices || []).map(notice => (
                  <div key={notice.id} className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 p-4 shadow-sm relative overflow-hidden">
                      <div className={`absolute left-0 top-0 bottom-0 w-1 ${notice.severity === 'URGENT' ? 'bg-red-500' : notice.severity === 'INFO' ? 'bg-blue-500' : 'bg-slate-300'}`}></div>
                      <div className="flex justify-between items-start mb-2 pl-3">
                          <div>
                              <h3 className="font-bold text-slate-800 dark:text-white flex items-center">
                                  {notice.severity === 'URGENT' && <AlertTriangle size={16} className="text-red-500 mr-1" />}
                                  {notice.title}
                              </h3>
                              <p className="text-[10px] text-slate-400 font-medium uppercase">{formatDate(notice.date)}</p>
                          </div>
                          <div className="flex space-x-1">
                              <button onClick={() => handleShareNotice(notice.title, notice.content)} className="p-2 text-green-600 hover:bg-green-50 rounded-lg">
                                  <Share2 size={16} />
                              </button>
                              <button onClick={() => handleDeleteNotice(notice.id)} className="p-2 text-red-400 hover:bg-red-50 rounded-lg">
                                  <Trash2 size={16} />
                              </button>
                          </div>
                      </div>
                      <p className="text-sm text-slate-600 dark:text-slate-300 pl-3 whitespace-pre-wrap leading-relaxed">{notice.content}</p>
                  </div>
              ))
          )}
      </div>
  );

  const renderContacts = () => (
      <div className="grid grid-cols-1 gap-3">
          {(state.contacts || []).length === 0 ? (
              <div className="text-center py-12 text-slate-400">
                  <Phone size={48} className="mx-auto mb-2 opacity-20" />
                  <p>No contacts added.</p>
              </div>
          ) : (
              (state.contacts || []).map(contact => (
                  <div key={contact.id} className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 p-4 shadow-sm flex items-center justify-between">
                      <div className="flex items-center space-x-3">
                          <div className="w-10 h-10 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-slate-500">
                              <User size={20} />
                          </div>
                          <div>
                              <h3 className="font-bold text-slate-800 dark:text-white text-sm">{contact.name}</h3>
                              <p className="text-xs text-slate-500 dark:text-slate-400 font-medium">{contact.role}</p>
                          </div>
                      </div>
                      <div className="flex items-center space-x-2">
                           <a href={`tel:${contact.mobile}`} className="bg-green-100 text-green-700 p-2 rounded-full">
                               <PhoneCall size={18} />
                           </a>
                           <button onClick={() => handleDeleteContact(contact.id)} className="text-slate-300 hover:text-red-500 p-2">
                               <Trash2 size={18} />
                           </button>
                      </div>
                  </div>
              ))
          )}
      </div>
  );

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-950 transition-colors">
       <div className="bg-white dark:bg-slate-900 px-4 py-3 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-10 transition-colors">
           <div className="flex justify-between items-center mb-4">
              <h2 className="text-xl font-bold text-slate-800 dark:text-white flex items-center">
                 <Megaphone size={20} className="mr-2 text-amber-500" />
                 Communication Hub
              </h2>
              <button onClick={() => setShowForm(true)} className="bg-slate-900 dark:bg-white text-white dark:text-black p-2.5 rounded-xl shadow-md active:scale-95 transition-all">
                  <Plus size={20} />
              </button>
           </div>

           <div className="flex bg-slate-100 dark:bg-slate-800 rounded-lg p-1">
              <button onClick={() => setActiveTab('NOTICES')} className={`flex-1 py-1.5 rounded-md text-sm font-bold flex items-center justify-center transition-all ${activeTab === 'NOTICES' ? 'bg-white dark:bg-slate-700 text-slate-900 dark:text-white shadow-sm' : 'text-slate-500 dark:text-slate-400'}`}>
                 <Bell size={16} className="mr-2" /> Notices
              </button>
              <button onClick={() => setActiveTab('CONTACTS')} className={`flex-1 py-1.5 rounded-md text-sm font-bold flex items-center justify-center transition-all ${activeTab === 'CONTACTS' ? 'bg-white dark:bg-slate-700 text-slate-900 dark:text-white shadow-sm' : 'text-slate-500 dark:text-slate-400'}`}>
                 <Phone size={16} className="mr-2" /> Contacts
              </button>
           </div>
       </div>

       <div className="flex-1 overflow-y-auto p-4 pb-24">
           {activeTab === 'NOTICES' ? renderNotices() : renderContacts()}
       </div>

       {/* SLIDE UP FORM */}
       {showForm && (
           <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/50 backdrop-blur-sm p-4">
               <div className="bg-white dark:bg-slate-900 w-full max-w-lg rounded-2xl shadow-2xl p-6 animate-in slide-in-from-bottom duration-300">
                   <div className="flex justify-between items-center mb-6">
                       <h3 className="font-bold text-xl text-slate-800 dark:text-white">
                           {activeTab === 'NOTICES' ? 'New Notice' : 'Add Contact'}
                       </h3>
                       <button onClick={() => setShowForm(false)} className="text-slate-400 hover:text-slate-600"><X size={24} /></button>
                   </div>

                   {activeTab === 'NOTICES' ? (
                       <form onSubmit={handleAddNotice} className="space-y-4">
                           <div>
                               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Title</label>
                               <input type="text" value={noticeTitle} onChange={e => setNoticeTitle(e.target.value)} className="w-full p-3 bg-slate-50 dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 dark:text-white" placeholder="e.g. Water Cut" autoFocus />
                           </div>
                           <div>
                               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Content</label>
                               <textarea value={noticeContent} onChange={e => setNoticeContent(e.target.value)} className="w-full p-3 bg-slate-50 dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 h-32 dark:text-white" placeholder="Type message..."></textarea>
                           </div>
                           <div className="flex space-x-2">
                               {['NORMAL', 'URGENT', 'INFO'].map((lev) => (
                                   <button 
                                     key={lev}
                                     type="button" 
                                     onClick={() => setSeverity(lev as any)} 
                                     className={`flex-1 py-2 text-xs font-bold rounded-lg border ${severity === lev ? 'bg-slate-800 text-white dark:bg-white dark:text-black border-transparent' : 'border-slate-200 text-slate-500'}`}
                                   >
                                       {lev}
                                   </button>
                               ))}
                           </div>
                           <button type="submit" className="w-full bg-blue-600 text-white font-bold py-4 rounded-xl shadow-lg mt-2">Post Notice</button>
                       </form>
                   ) : (
                       <form onSubmit={handleAddContact} className="space-y-4">
                           <div>
                               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Name</label>
                               <input type="text" value={contactName} onChange={e => setContactName(e.target.value)} className="w-full p-3 bg-slate-50 dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 dark:text-white" placeholder="e.g. Rajesh Kumar" autoFocus />
                           </div>
                           <div>
                               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Role / Service</label>
                               <input type="text" value={contactRole} onChange={e => setContactRole(e.target.value)} className="w-full p-3 bg-slate-50 dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 dark:text-white" placeholder="e.g. Electrician, Lift AMC" />
                           </div>
                           <div>
                               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Mobile Number</label>
                               <input type="tel" value={contactMobile} onChange={e => setContactMobile(e.target.value)} className="w-full p-3 bg-slate-50 dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 dark:text-white" placeholder="9876543210" />
                           </div>
                           <button type="submit" className="w-full bg-green-600 text-white font-bold py-4 rounded-xl shadow-lg mt-2">Save Contact</button>
                       </form>
                   )}
               </div>
           </div>
       )}
    </div>
  );
};

export default CommunicationHub;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import PaymentForm from './components/PaymentForm';
import Reports from './components/Reports';
import Settings from './components/Settings';
import FinanceDashboard from './components/FinanceDashboard';
import FinanceForm from './components/FinanceForm';
import FlatMaster from './components/FlatMaster';
import HallBooking from './components/HallBooking';
import CommunicationHub from './components/CommunicationHub';
import { AppState, ViewState, Transaction, FinancialRecord } from './types';
import { loadData } from './services/storageService';
import { STORAGE_KEY } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [state, setState] = useState<AppState | null>(null);

  // Edit State for Maintenance Transactions
  const [transactionToEdit, setTransactionToEdit] = useState<Transaction | null>(null);

  // State for Finance Module
  const [showFinanceForm, setShowFinanceForm] = useState(false);
  const [financeRecordToEdit, setFinanceRecordToEdit] = useState<FinancialRecord | null>(null);

  useEffect(() => {
    // Load data from local storage on mount
    const data = loadData();
    setState(data);

    // Apply theme
    if (data.theme === 'DARK') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }

    // Listen for storage events (cross-tab synchronization)
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === STORAGE_KEY) {
        const newData = loadData();
        setState(newData);
        // Apply theme on storage change too
        if (newData.theme === 'DARK') {
          document.documentElement.classList.add('dark');
        } else {
          document.documentElement.classList.remove('dark');
        }
      }
    };

    window.addEventListener('storage', handleStorageChange);
    return () => {
      window.removeEventListener('storage', handleStorageChange);
    };
  }, []);

  // Update DOM when state theme changes
  useEffect(() => {
    if (state?.theme === 'DARK') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [state?.theme]);

  const handleStateUpdate = (newState: AppState) => {
    setState(newState);
  };

  const handleEditFromReport = (tx: Transaction) => {
    setTransactionToEdit(tx);
    setView('PAYMENT');
  };

  const clearEditMode = () => {
    setTransactionToEdit(null);
  };

  const handleEditFinanceRecord = (record: FinancialRecord) => {
    setFinanceRecordToEdit(record);
    setShowFinanceForm(true);
  };

  const closeFinanceForm = () => {
    setShowFinanceForm(false);
    setFinanceRecordToEdit(null);
  };

  if (!state) return <div className="flex h-screen items-center justify-center text-slate-500 dark:text-slate-400 bg-slate-50 dark:bg-slate-950">Loading...</div>;

  return (
    <Layout currentView={view} setView={setView}>
      {view === 'DASHBOARD' && <Dashboard state={state} refreshState={handleStateUpdate} />}

      {view === 'PAYMENT' && (
        <PaymentForm 
          state={state} 
          refreshState={handleStateUpdate} 
          initialTransactionToEdit={transactionToEdit}
          onClearEdit={clearEditMode}
        />
      )}

      {view === 'FLATS' && (
        <FlatMaster 
          state={state} 
          refreshState={handleStateUpdate}
        />
      )}

      {view === 'ACCOUNTS' && (
        <FinanceDashboard 
          state={state} 
          refreshState={handleStateUpdate}
          onAddTransaction={() => setShowFinanceForm(true)}
          onEditTransaction={handleEditFinanceRecord}
        />
      )}

      {view === 'HALL_BOOKING' && (
        <HallBooking 
          state={state} 
          refreshState={handleStateUpdate}
        />
      )}

      {view === 'COMMUNICATION' && (
        <CommunicationHub
          state={state}
          refreshState={handleStateUpdate}
        />
      )}

      {view === 'REPORTS' && (
        <Reports 
          state={state} 
          view="REPORTS" 
          refreshState={handleStateUpdate} 
          onEditTransaction={handleEditFromReport}
        />
      )}

      {view === 'UNPAID_LIST' && <Reports state={state} view="UNPAID_LIST" refreshState={handleStateUpdate} />}

      {view === 'SETTINGS' && <Settings state={state} refreshState={handleStateUpdate} />}

      {/* Modal for Finance Transactions */}
      {showFinanceForm && (
        <FinanceForm 
          state={state}
          refreshState={handleStateUpdate}
          onClose={closeFinanceForm}
          recordToEdit={financeRecordToEdit}
        />
      )}

    </Layout>
  );
};

export default App;

export enum PaymentStatus {
  PAID = 'PAID',
  UNPAID = 'UNPAID',
}

export interface Flat {
  id: string;
  flatNumber: string;
  ownerName: string; 
  status: PaymentStatus;
  mobile?: string;

  // Extended Master Fields
  isRented?: boolean;
  tenantName?: string;
  tenantMobile?: string;

  vehicle2WCount?: number;
  vehicle4WCount?: number;
  vehicle2WNumbers?: string; // Comma separated
  vehicle4WNumbers?: string; // Comma separated
}

export interface Transaction {
  receiptNo: number;
  date: string; // ISO String
  timestamp: number;
  flatId: string;
  flatNumber: string;
  ownerName: string;
  amount: number;
  mobile: string;
}

export interface FinancialRecord {
  id: string;
  type: 'INCOME' | 'EXPENSE' | 'TRANSFER';
  paymentMode: 'CASH' | 'BANK';
  amount: number;
  date: string; // ISO String YYYY-MM-DD
  category: string;
  description: string;
  timestamp: number;
}

export interface HallBooking {
  id: string;
  flatId: string;
  flatNumber: string;
  ownerName: string;
  mobile: string;
  hallType: 'BIG' | 'SMALL';
  bookingDate: string; // YYYY-MM-DD
  amount: number;
  timestamp: number;
}

export interface AppState {
  flats: Flat[];
  transactions: Transaction[];
  financialRecords: FinancialRecord[];
  hallBookings: HallBooking[];
  lastReceiptNo: number;
  theme?: 'LIGHT' | 'DARK';
  aiInsight?: {
    text: string;
    timestamp: number;
  };
}

export type ViewState = 'DASHBOARD' | 'PAYMENT' | 'FLATS' | 'ACCOUNTS' | 'REPORTS' | 'UNPAID_LIST' | 'SETTINGS' | 'HALL_BOOKING';

