      <nav className="fixed bottom-0 w-full bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800 pb-safe z-30 shadow-[0_-8px_30px_rgba(0,0,0,0.04)] dark:shadow-none transition-colors duration-200 overflow-x-auto no-scrollbar">
        <div className="flex justify-between items-center px-2 py-2 min-w-max md:min-w-0 md:justify-around space-x-2 md:space-x-0">
          {navItems.map((item) => {
            const isActive = currentView === item.id;
            return (
              <button
                key={item.id}
                onClick={() => setView(item.id as ViewState)}
                className={`group flex flex-col items-center justify-center w-16 md:w-full py-2 rounded-2xl transition-all duration-300 ease-in-out relative overflow-hidden shrink-0 ${
                  isActive 
                    ? `${item.activeBg} ${item.activeColor}` 
                    : 'text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800 hover:text-slate-600 dark:hover:text-slate-300'
                }`}
              >
                <div className={`transition-transform duration-300 ${isActive ? 'scale-110 -translate-y-0.5' : 'group-hover:-translate-y-0.5'}`}>
                   <item.icon 
                      size={24} 
                      strokeWidth={isActive ? 2.5 : 2} 
                      className={isActive ? "drop-shadow-sm" : ""}
                   />
                </div>
                <span className={`text-[10px] font-bold mt-0.5 transition-all duration-300 ${isActive ? 'opacity-100 translate-y-0' : 'opacity-70 group-hover:opacity-100'}`}>
                  {item.label}
                </span>

                {isActive && (
                    <div className={`absolute bottom-0.5 w-1 h-1 rounded-full ${item.activeColor.split(' ')[0].replace('text-', 'bg-')} opacity-50`}></div>
                )}
              </button>
            );
          })}
        </div>
      </nav>
    </div>
  );
};

