export const addNotice = (state: AppState, notice: Omit<Notice, 'id' | 'timestamp'>) => {
  const newState = {
    ...state,
    notices: [...(state.notices || [])]
  };

  const newNotice: Notice = {
    ...notice,
    id: `notice-${Date.now()}`,
    timestamp: Date.now()
  };

  // Sort by date descending (newest first)
  newState.notices = [newNotice, ...newState.notices];

  saveData(newState);
  return newState;
};

